def quantidade_pesquisas_card(historico_base, df_fallback=None):
    """
    Card Pesquisas:
    conta a quantidade total de linhas válidas carregadas da pasta VENDA_TESTE.
    Não conta arquivos.
    Não conta produtos únicos.
    Cada linha válida de produto pesquisado/retornado na pesquisa = 1.
    """

    try:
        if isinstance(historico_base, pd.DataFrame) and not historico_base.empty:
            base = historico_base.copy()
        elif isinstance(df_fallback, pd.DataFrame) and not df_fallback.empty:
            base = df_fallback.copy()
        else:
            return 0

        base = base.dropna(how="all")

        if base.empty:
            return 0

        candidatos = [
            "Produto",
            "PRODUTO",
            "Descrição",
            "Descricao",
            "EAN",
            "EAN (GTIN)",
            "GTIN",
            "Código de Barras",
            "Codigo de Barras",
            "Preço (R$)",
            "Preco (R$)",
            "Preço",
            "Preco",
            "Farmácia",
            "Farmacia",
            "Nome Fantasia",
            "Termo Pesquisado",
            "TERMO PESQUISADO",
        ]

        mapa = {str(c).strip().lower(): c for c in base.columns}
        colunas_validacao = []

        for c in candidatos:
            chave = str(c).strip().lower()
            if chave in mapa:
                colunas_validacao.append(mapa[chave])

        if not colunas_validacao:
            return int(len(base))

        mascara = pd.Series(False, index=base.index)

        for c in colunas_validacao:
            serie = base[c].fillna("").astype(str).str.strip()
            valida = (
                (serie != "") &
                (~serie.str.lower().isin(["nan", "none", "null", "não informado", "nao informado"]))
            )
            mascara = mascara | valida

        return int(mascara.sum())

    except Exception:
        try:
            return int(len(historico_base)) if isinstance(historico_base, pd.DataFrame) else 0
        except Exception:
            return 0


