def _numero_br_para_float_eirox(valor):
    try:
        if pd.isna(valor):
            return np.nan
        if isinstance(valor, (int, float, np.number)):
            return float(valor)
        texto = str(valor).strip().replace("R$", "").replace("%", "").replace(" ", "")
        if "," in texto and "." in texto:
            texto = texto.replace(".", "").replace(",", ".")
        elif "," in texto:
            texto = texto.replace(",", ".")
        return float(texto)
    except Exception:
        return np.nan


def _achar_coluna_eirox(df_base, exatos=None, contem=None):
    try:
        if df_base is None or df_base.empty:
            return None

        exatos = exatos or []
        contem = contem or []

        for alvo in exatos:
            for c in df_base.columns:
                if str(c).strip().lower() == str(alvo).strip().lower():
                    return c

        for termo in contem:
            for c in df_base.columns:
                if str(termo).lower() in str(c).lower():
                    return c
    except Exception:
        pass

    return None


def _normalizar_ean_eirox(valor):
    try:
        if pd.isna(valor):
            return ""
        return re.sub(r"\D", "", str(valor).strip())
    except Exception:
        return ""



