def _normalizar_texto_top40(valor):
    try:
        if pd.isna(valor):
            return ""
        texto = str(valor).strip()
        if texto.lower() in ["nan", "none", "null"]:
            return ""
        return texto
    except Exception:
        return ""


def _coluna_disponivel_top40(df_base, opcoes):
    try:
        if not isinstance(df_base, pd.DataFrame) or df_base.empty:
            return None

        mapa = {str(c).strip().lower(): c for c in df_base.columns}

        for col in opcoes:
            chave = str(col).strip().lower()
            if chave in mapa:
                return mapa[chave]

        for col in df_base.columns:
            nome = str(col).lower()
            for alvo in opcoes:
                if str(alvo).lower() in nome:
                    return col

    except Exception:
        pass

    return None


def preparar_top40_marca_bairro_historico(historico_base, df_fallback=None):
    """
    Top 40 deve usar a base original de pesquisas, porque é nela que ficam:
    Marca/Laboratório/Fabricante/Bairro/Farmácia/Endereço.
    """

    try:
        if isinstance(historico_base, pd.DataFrame) and not historico_base.empty:
            base = historico_base.copy()
        elif isinstance(df_fallback, pd.DataFrame) and not df_fallback.empty:
            base = df_fallback.copy()
        else:
            return pd.DataFrame(columns=["Marca_Top40", "Bairro_Top40"])

        # Marca: tenta pegar do histórico primeiro.
        col_marca = _coluna_disponivel_top40(
            base,
            [
                "Marca",
                "MARCA",
                "Laboratório",
                "Laboratorio",
                "LABORATORIO",
                "Fabricante",
                "FABRICANTE",
                "Família",
                "Familia",
                "FAMILIA",
                "Produto",
                "PRODUTO"
            ]
        )

        if col_marca:
            base["Marca_Top40"] = base[col_marca].apply(_normalizar_texto_top40)
        else:
            base["Marca_Top40"] = ""

        base.loc[base["Marca_Top40"].eq(""), "Marca_Top40"] = "Não informado"

        # Bairro: tenta variações comuns vindas da pesquisa de mercado.
        col_bairro = _coluna_disponivel_top40(
            base,
            [
                "Bairro",
                "BAIRRO",
                "bairro",
                "Localidade",
                "LOCALIDADE",
                "Região",
                "Regiao",
                "REGIAO",
                "Endereço",
                "Endereco",
                "ENDERECO",
                "Cidade",
                "CIDADE",
                "Município",
                "Municipio",
                "MUNICIPIO"
            ]
        )

        if col_bairro:
            base["Bairro_Top40"] = base[col_bairro].apply(_normalizar_texto_top40)
        else:
            base["Bairro_Top40"] = ""

        base.loc[base["Bairro_Top40"].eq(""), "Bairro_Top40"] = "Não informado"

        return base

    except Exception:
        return pd.DataFrame(columns=["Marca_Top40", "Bairro_Top40"])


def altura_top40(qtd):
    try:
        return max(520, min(1400, 180 + int(qtd) * 26))
    except Exception:
        return 720




