def heatmap_1x40_plotly(tabela, coluna_nome, titulo, eixo_y):
    try:
        if tabela is None or tabela.empty:
            return None

        tabela = tabela.copy()
        # V1.4.31 — ordem visual decrescente: maior quantidade à esquerda.
        tabela = tabela.sort_values("Quantidade de Pesquisas", ascending=False).head(40)

        nomes = tabela[coluna_nome].astype(str).tolist()
        valores = tabela["Quantidade de Pesquisas"].astype(float).tolist()
        textos = [f"{int(v):,}".replace(",", ".") for v in valores]

        fig = go.Figure(
            data=go.Heatmap(
                z=[valores],
                x=nomes,
                y=[eixo_y],
                text=[textos],
                texttemplate="%{text}",
                textfont={"color": "white", "size": 12},
                colorscale="Plasma",
                colorbar={
                    "title": {"text": "Quantidade de Pesquisas", "font": {"color": "white"}},
                    "tickfont": {"color": "white"}
                },
                hovertemplate=f"{eixo_y}: %{{x}}<br>Quantidade: %{{z:,.0f}}<extra></extra>"
            )
        )

        fig.update_layout(
            title=titulo,
            height=390,
            margin={"l": 20, "r": 40, "t": 65, "b": 130},
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor="rgba(0,0,0,0)",
            font={"color": "white"},
            xaxis={
                "title": coluna_nome.replace("_", " "),
                "tickangle": -90,
                "automargin": True,
                "tickfont": {"size": 10, "color": "white"},
                "showgrid": False,
            },
            yaxis={
                "title": eixo_y,
                "tickfont": {"size": 12, "color": "white"},
                "showgrid": False,
            },
        )

        return fig

    except Exception:
        return None



