def _normalizar_texto_heatmap(valor):
    try:
        if pd.isna(valor):
            return ""
        texto = str(valor).strip()
        if texto.lower() in ["nan", "none", "null"]:
            return ""
        return texto
    except Exception:
        return ""


def _coluna_disponivel_heatmap(df_base, opcoes):
    try:
        if not isinstance(df_base, pd.DataFrame) or df_base.empty:
            return None

        mapa = {str(c).strip().lower(): c for c in df_base.columns}

        for col in opcoes:
            chave = str(col).strip().lower()
            if chave in mapa:
                return mapa[chave]

        for col in df_base.columns:
            nome = str(col).lower()
            for alvo in opcoes:
                if str(alvo).lower() in nome:
                    return col
    except Exception:
        pass
    return None


def _extrair_marca_do_produto(texto):
    try:
        texto = _normalizar_texto_heatmap(texto).upper()
        if not texto:
            return ""

        # Remove pontuações simples e normaliza espaços.
        texto = re.sub(r"[^A-ZÀ-Ú0-9\s]", " ", texto)
        texto = re.sub(r"\s+", " ", texto).strip()

        # Se tiver marca conhecida no texto, prioriza.
        marcas_conhecidas = [
            "DOVE", "NIVEA", "ELSEVE", "L OREAL", "LOREAL", "PANTENE", "SEDA",
            "REXONA", "CLEAR", "COLGATE", "ORAL B", "SENSODYNE", "NEUTROGENA",
            "DORFLEX", "NEOSORO", "LAVITAN", "BENEGRIP", "BUSCOPAN", "DIPIRONA",
            "TYLENOL", "ADVIL", "ALIVIUM", "NATULAB", "CIMED", "EMS", "MEDLEY",
            "EUROFARMA", "ACHE", "SANOFI", "BAYER", "GSK", "GEOLAB", "TEUTO",
            "MULTILAB", "NOVA QUIMICA", "PHARLAB", "LEGRAND", "BIOLAB",
            "HASKELL", "MONANGE", "FRUCTIS", "GARNIER", "PALMOLIVE", "YPÊ", "YPE"
        ]

        for marca in marcas_conhecidas:
            if marca in texto:
                return marca

        # Fallback: primeira palavra relevante do produto.
        ignorar = {
            "ABSORVENTE", "ACEBROFILINA", "ACETILCISTEINA", "AGUA", "ALCOOL",
            "APARELHO", "CREME", "SHAMPOO", "CONDICIONADOR", "SABONETE",
            "DESODORANTE", "FRALDA", "LENCO", "LENÇO", "POMADA", "SOLUCAO",
            "SOLUÇÃO", "COMPRIMIDO", "CPR", "CAPS", "XAROPE", "INFANTIL",
            "ADULTO", "GENERICO", "GENÉRICO"
        }

        partes = texto.split()
        for p in partes[:4]:
            if len(p) >= 3 and not p.isdigit() and p not in ignorar:
                return p

        return partes[0] if partes else "Não informado"

    except Exception:
        return "Não informado"


def preparar_base_heatmap_1x40(historico_base, df_fallback=None):
    try:
        if isinstance(historico_base, pd.DataFrame) and not historico_base.empty:
            base = historico_base.copy()
        elif isinstance(df_fallback, pd.DataFrame) and not df_fallback.empty:
            base = df_fallback.copy()
        else:
            return pd.DataFrame(columns=["Marca_Heatmap", "Bairro_Heatmap"])

        # MARCA:
        # A base Primavera não possui coluna Marca. Então usamos Produto/Termo Pesquisado.
        col_marca_direta = _coluna_disponivel_heatmap(
            base,
            ["Marca", "MARCA", "Laboratório", "Laboratorio", "LABORATORIO", "Fabricante", "FABRICANTE"]
        )

        if col_marca_direta:
            base["Marca_Heatmap"] = base[col_marca_direta].apply(_normalizar_texto_heatmap)
        else:
            col_produto = _coluna_disponivel_heatmap(base, ["Produto", "PRODUTO", "Descrição", "Descricao"])
            col_termo = _coluna_disponivel_heatmap(base, ["Termo Pesquisado", "TERMO PESQUISADO", "Pesquisa", "Descricao_Pesquisa"])

            if col_produto:
                base["Marca_Heatmap"] = base[col_produto].apply(_extrair_marca_do_produto)
            elif col_termo:
                base["Marca_Heatmap"] = base[col_termo].apply(_extrair_marca_do_produto)
            else:
                base["Marca_Heatmap"] = "Não informado"

        base["Marca_Heatmap"] = base["Marca_Heatmap"].fillna("").astype(str).str.strip()
        base.loc[base["Marca_Heatmap"].eq(""), "Marca_Heatmap"] = "Não informado"

        # BAIRRO:
        # Usa diretamente a coluna Bairro do VENDA_TESTE.
        col_bairro = _coluna_disponivel_heatmap(
            base,
            ["Bairro", "BAIRRO", "bairro", "Localidade", "LOCALIDADE", "Região", "Regiao", "REGIAO"]
        )

        if col_bairro:
            base["Bairro_Heatmap"] = base[col_bairro].apply(_normalizar_texto_heatmap)
        else:
            base["Bairro_Heatmap"] = "Não informado"

        base["Bairro_Heatmap"] = base["Bairro_Heatmap"].fillna("").astype(str).str.strip()
        base.loc[base["Bairro_Heatmap"].eq(""), "Bairro_Heatmap"] = "Não informado"

        return base

    except Exception:
        return pd.DataFrame(columns=["Marca_Heatmap", "Bairro_Heatmap"])


def heatmap_1x40_plotly(tabela, coluna_nome, titulo, eixo_y):
    try:
        if tabela is None or tabela.empty:
            return None

        tabela = tabela.copy()
        # V1.4.31 — ordem visual decrescente: maior quantidade à esquerda.
        tabela = tabela.sort_values("Quantidade de Pesquisas", ascending=False).head(40)

        nomes = tabela[coluna_nome].astype(str).tolist()
        valores = tabela["Quantidade de Pesquisas"].astype(float).tolist()
        textos = [f"{int(v):,}".replace(",", ".") for v in valores]

        fig = go.Figure(
            data=go.Heatmap(
                z=[valores],
                x=nomes,
                y=[eixo_y],
                text=[textos],
                texttemplate="%{text}",
                textfont={"color": "white", "size": 12},
                colorscale="Plasma",
                colorbar={
                    "title": {"text": "Quantidade de Pesquisas", "font": {"color": "white"}},
                    "tickfont": {"color": "white"}
                },
                hovertemplate=f"{eixo_y}: %{{x}}<br>Quantidade: %{{z:,.0f}}<extra></extra>"
            )
        )

        fig.update_layout(
            title=titulo,
            height=390,
            margin={"l": 20, "r": 40, "t": 65, "b": 130},
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor="rgba(0,0,0,0)",
            font={"color": "white"},
            xaxis={
                "title": coluna_nome.replace("_", " "),
                "tickangle": -90,
                "automargin": True,
                "tickfont": {"size": 10, "color": "white"},
                "showgrid": False,
            },
            yaxis={
                "title": eixo_y,
                "tickfont": {"size": 12, "color": "white"},
                "showgrid": False,
            },
        )

        return fig

    except Exception:
        return None





def garantir_colunas_padrao_dashboard(df_base):
    try:
        if not isinstance(df_base, pd.DataFrame):
            return df_base

        df_base = df_base.copy()

        padroes = {
            "Família": "Não informado",
            "Familia": "Não informado",
            "CURVA": "Não informado",
            "Recomendacao": "MANTER",
            "Laboratório": "Não informado",
            "Produto": "",
            "EAN": "",
            "Margem_%": 0,
            "Lucro_Unitario": 0,
            "Ganho_Potencial": 0,
            "Preco_Medio": 0,
            "Preço Médio": 0,
            "Preço Atual": 0,
            "Preco_Atual": 0,
            "Custo": 0,
            "Qtd Vendida Mês Anterior": 0,
            "Qtd_Vendida_Mes_Anterior": 0,
        }

        for coluna, valor in padroes.items():
            if coluna not in df_base.columns:
                df_base[coluna] = valor

        # Sincroniza Família/Familia para evitar KeyError por acento.
        if "Família" not in df_base.columns and "Familia" in df_base.columns:
            df_base["Família"] = df_base["Familia"]
        if "Familia" not in df_base.columns and "Família" in df_base.columns:
            df_base["Familia"] = df_base["Família"]

        df_base["Família"] = df_base["Família"].fillna("Não informado").replace("", "Não informado")
        df_base["Familia"] = df_base["Familia"].fillna("Não informado").replace("", "Não informado")

        return df_base

    except Exception:
        return df_base


def construir_base_pricing_somente_pastas(historico, compra, venda_rede, estoque):
    try:
        h = historico.copy() if isinstance(historico, pd.DataFrame) else pd.DataFrame()
        c = compra.copy() if isinstance(compra, pd.DataFrame) else pd.DataFrame()
        v = venda_rede.copy() if isinstance(venda_rede, pd.DataFrame) else pd.DataFrame()
        e = estoque.copy() if isinstance(estoque, pd.DataFrame) else pd.DataFrame()

        if h.empty:
            return pd.DataFrame()

        col_ean_h = _achar_coluna_eirox(h, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"], ["ean", "gtin", "barras"])
        col_prod_h = _achar_coluna_eirox(h, ["Produto", "Descrição", "Descricao"], ["produto", "descri"])
        col_preco_h = _achar_coluna_eirox(h, ["Preço (R$)", "Preco (R$)", "Preço", "Preco", "Valor"], ["preço", "preco", "valor"])
        col_farm_h = _achar_coluna_eirox(h, ["Farmácia", "Farmacia", "Loja", "Estabelecimento", "Razão Social", "Razao Social"], ["farm", "loja", "estabelec", "razao", "razão", "social"])
        col_lab_h = _achar_coluna_eirox(h, ["Laboratório", "Laboratorio", "Fabricante"], ["labor", "fabric"])
        col_data_h = _achar_coluna_eirox(h, ["Data Emissão", "Data", "Data Pesquisa"], ["data", "emiss"])

        base = pd.DataFrame()
        base["EAN"] = h[col_ean_h].apply(_normalizar_ean_eirox) if col_ean_h else ""
        base["Produto"] = h[col_prod_h].astype(str) if col_prod_h else ""
        base["Preco_Concorrente"] = h[col_preco_h].apply(_numero_br_para_float_eirox) if col_preco_h else np.nan
        base["Farmacia_Concorrente"] = h[col_farm_h].astype(str) if col_farm_h else ""
        base["Laboratório"] = h[col_lab_h].astype(str) if col_lab_h else ""
        base["Data_Pesquisa"] = h[col_data_h] if col_data_h else ""
        base["Arquivo_Origem"] = h["Arquivo_Origem"] if "Arquivo_Origem" in h.columns else ""
        base = base[base["EAN"].astype(str).str.len() > 0].copy()

        base["_dedup"] = (
            base["EAN"].astype(str) + "|" +
            base["Farmacia_Concorrente"].astype(str).str.upper().str.strip() + "|" +
            base["Preco_Concorrente"].round(2).astype(str) + "|" +
            base["Arquivo_Origem"].astype(str)
        )
        base = base.drop_duplicates("_dedup").drop(columns=["_dedup"])

        agg = base.groupby("EAN", as_index=False).agg(
            Produto=("Produto", lambda x: next((str(i) for i in x if str(i).strip() and str(i).lower() != "nan"), "")),
            Laboratório=("Laboratório", lambda x: next((str(i) for i in x if str(i).strip() and str(i).lower() != "nan"), "")),
            Preco_Medio=("Preco_Concorrente", "mean"),
            Menor_Preco=("Preco_Concorrente", "min"),
            Preco_Maximo_Competitivo=("Preco_Concorrente", "max"),
            Qtde_Pesquisas_Linhas=("Preco_Concorrente", "count")
        )

        idx_min = base.sort_values("Preco_Concorrente").dropna(subset=["Preco_Concorrente"]).drop_duplicates("EAN")
        if not idx_min.empty:
            agg = agg.merge(
                idx_min[["EAN", "Farmacia_Concorrente", "Data_Pesquisa"]].rename(columns={
                    "Farmacia_Concorrente": "Loja Menor Preço Concorrente",
                    "Data_Pesquisa": "Data Menor Preço"
                }),
                on="EAN",
                how="left"
            )

        if not v.empty:
            col_ean_v = _achar_coluna_eirox(v, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"], ["ean", "gtin", "barras"])
            col_qtd_v = _achar_coluna_eirox(v, ["Quantidade", "Qtd", "Qtde", "QTD_VENDIDA", "Qtd Vendida"], ["quant", "qtd", "qtde"])
            col_val_v = _achar_coluna_eirox(v, ["Valor", "Valor Total", "Valor_Liquido", "Venda", "Venda Preço Antigo"], ["valor", "liquido", "líquido", "venda"])
            col_preco_v = _achar_coluna_eirox(v, ["Preço", "Preco", "Valor Unitario", "Valor Unitário", "valorunitario"], ["preço", "preco", "unit"])

            tmp = pd.DataFrame()
            tmp["EAN"] = v[col_ean_v].apply(_normalizar_ean_eirox) if col_ean_v else ""
            tmp["Qtd_Vendida_Mes_Anterior"] = v[col_qtd_v].apply(_numero_br_para_float_eirox) if col_qtd_v else 0
            tmp["Venda_Preco_Antigo"] = v[col_val_v].apply(_numero_br_para_float_eirox) if col_val_v else np.nan
            tmp["Preco_Atual_Venda"] = v[col_preco_v].apply(_numero_br_para_float_eirox) if col_preco_v else np.nan

            vend = tmp.groupby("EAN", as_index=False).agg(
                Qtd_Vendida_Mes_Anterior=("Qtd_Vendida_Mes_Anterior", "sum"),
                Venda_Preco_Antigo=("Venda_Preco_Antigo", "sum"),
                Preco_Atual_Venda=("Preco_Atual_Venda", "mean")
            )
            agg = agg.merge(vend, on="EAN", how="left")

        if not c.empty:
            col_ean_c = _achar_coluna_eirox(c, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"], ["ean", "gtin", "barras"])
            col_custo_c = _achar_coluna_eirox(c, ["Custo", "Custo Unitário", "Custo_Unitario", "Preço Compra", "Preco Compra"], ["custo", "compra"])
            col_lab_c = _achar_coluna_eirox(c, ["Laboratório", "Laboratorio", "Fabricante", "Marca"], ["labor", "fabric", "marca"])

            tmp = pd.DataFrame()
            tmp["EAN"] = c[col_ean_c].apply(_normalizar_ean_eirox) if col_ean_c else ""
            tmp["Custo"] = c[col_custo_c].apply(_numero_br_para_float_eirox) if col_custo_c else np.nan
            tmp["Laboratório_Compra"] = c[col_lab_c].astype(str) if col_lab_c else ""

            comp = tmp.groupby("EAN", as_index=False).agg(
                Custo=("Custo", "mean"),
                Laboratório_Compra=("Laboratório_Compra", lambda x: next((str(i) for i in x if str(i).strip() and str(i).lower() != "nan"), ""))
            )
            agg = agg.merge(comp, on="EAN", how="left")

        if not e.empty:
            col_ean_e = _achar_coluna_eirox(e, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"], ["ean", "gtin", "barras"])
            col_est_e = _achar_coluna_eirox(e, ["Estoque", "Qtd Estoque", "Quantidade Estoque"], ["estoque"])
            col_custo_e = _achar_coluna_eirox(e, ["Custo", "Custo Unitário", "Custo_Unitario"], ["custo"])

            tmp = pd.DataFrame()
            tmp["EAN"] = e[col_ean_e].apply(_normalizar_ean_eirox) if col_ean_e else ""
            tmp["Estoque"] = e[col_est_e].apply(_numero_br_para_float_eirox) if col_est_e else np.nan
            tmp["Custo_Estoque"] = e[col_custo_e].apply(_numero_br_para_float_eirox) if col_custo_e else np.nan

            est = tmp.groupby("EAN", as_index=False).agg(
                Estoque=("Estoque", "sum"),
                Custo_Estoque=("Custo_Estoque", "mean")
            )
            agg = agg.merge(est, on="EAN", how="left")

        agg["Preco_Atual"] = agg["Preco_Atual_Venda"] if "Preco_Atual_Venda" in agg.columns else np.nan
        agg["Preco_Atual"] = agg["Preco_Atual"].fillna(agg["Preco_Medio"])

        if "Custo" not in agg.columns:
            agg["Custo"] = np.nan
        if "Custo_Estoque" in agg.columns:
            agg["Custo"] = agg["Custo"].fillna(agg["Custo_Estoque"])

        if "Qtd_Vendida_Mes_Anterior" not in agg.columns:
            agg["Qtd_Vendida_Mes_Anterior"] = 0
        if "Venda_Preco_Antigo" not in agg.columns:
            agg["Venda_Preco_Antigo"] = agg["Preco_Atual"].fillna(0) * agg["Qtd_Vendida_Mes_Anterior"].fillna(0)

        agg["Preço Sugerido Mercado"] = agg["Preco_Maximo_Competitivo"].fillna(agg["Preco_Medio"]).fillna(agg["Preco_Atual"])
        agg["Preco_Sugerido_Mercado"] = agg["Preço Sugerido Mercado"]
        agg["Lucro_Unitario"] = agg["Preco_Atual"].fillna(0) - agg["Custo"].fillna(0)
        agg["Margem_%"] = np.where(agg["Preco_Atual"].fillna(0) > 0, agg["Lucro_Unitario"] / agg["Preco_Atual"], 0)
        agg["Ganho_Unitario"] = (agg["Preco_Sugerido_Mercado"].fillna(0) - agg["Preco_Atual"].fillna(0)).clip(lower=0)
        agg["Ganho_Potencial"] = agg["Ganho_Unitario"] * agg["Qtd_Vendida_Mes_Anterior"].fillna(0)
        agg["Ganho Produto"] = agg["Ganho_Potencial"]
        agg["Venda Projetada Preço Sugerido"] = agg["Preco_Sugerido_Mercado"].fillna(0) * agg["Qtd_Vendida_Mes_Anterior"].fillna(0)
        agg["Recomendacao"] = np.where(
            agg["Preco_Sugerido_Mercado"] > agg["Preco_Atual"],
            "SUBIR PREÇO",
            np.where(agg["Preco_Sugerido_Mercado"] < agg["Preco_Atual"], "BAIXAR PREÇO", "MANTER")
        )

        if "Laboratório_Compra" in agg.columns:
            agg["Laboratório"] = agg["Laboratório"].replace("", np.nan).fillna(agg["Laboratório_Compra"]).fillna("Não informado")
        else:
            agg["Laboratório"] = agg["Laboratório"].replace("", "Não informado").fillna("Não informado")

        agg["Preço Médio"] = agg["Preco_Medio"]
        agg["Menor Preço"] = agg["Menor_Preco"]
        agg["Preço Atual"] = agg["Preco_Atual"]
        agg["Qtd Vendida Mês Anterior"] = agg["Qtd_Vendida_Mes_Anterior"]
        agg["Venda Preço Antigo"] = agg["Venda_Preco_Antigo"]
        agg["Lucro Unitário"] = agg["Lucro_Unitario"]

        return agg

    except Exception as erro:
        try:
            st.error(f"Erro ao construir base das pastas: {erro}")
        except Exception:
            pass
        return pd.DataFrame()




