ARQUIVO_CADASTRO_CNPJ_CLIENTE = Path("CADASTRO_CLIENTE_CNPJ.csv")


def normalizar_cnpj_eirox(valor):
    try:
        texto = str(valor)
        texto = re.sub(r"\D", "", texto)
        if texto.lower() in ["nan", "none"]:
            return ""
        return texto.zfill(14) if texto and texto != "0" else ""
    except Exception:
        return ""


def carregar_cnpjs_cliente():
    try:
        if not ARQUIVO_CADASTRO_CNPJ_CLIENTE.exists():
            modelo = pd.DataFrame([
                {
                    "CNPJ": "",
                    "Nome_Loja": "Loja propria Castro",
                    "Cidade": "Primavera do Leste",
                    "UF": "MT",
                    "Observacao": "Preencha aqui o CNPJ da loja cliente"
                }
            ])
            modelo.to_csv(
                ARQUIVO_CADASTRO_CNPJ_CLIENTE,
                index=False,
                sep=";",
                encoding="utf-8-sig"
            )

        try:
            cadastro = pd.read_csv(
                ARQUIVO_CADASTRO_CNPJ_CLIENTE,
                sep=";",
                dtype=str,
                encoding="utf-8-sig"
            )
        except Exception:
            cadastro = pd.read_csv(
                ARQUIVO_CADASTRO_CNPJ_CLIENTE,
                dtype=str,
                encoding="utf-8-sig"
            )

        if cadastro.empty or "CNPJ" not in cadastro.columns:
            return set(), cadastro

        cadastro["CNPJ_Limpo"] = cadastro["CNPJ"].apply(normalizar_cnpj_eirox)
        cnpjs = set(cadastro["CNPJ_Limpo"].dropna().astype(str).str.strip())
        cnpjs = {c for c in cnpjs if c and c != "00000000000000"}

        return cnpjs, cadastro

    except Exception:
        return set(), pd.DataFrame()


def encontrar_coluna_cnpj_cliente(base):
    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return None

        opcoes_exatas = [
            "CNPJ", "CPF/CNPJ", "CPF CNPJ", "cpfcnpj", "CpfCnpj",
            "CNPJ Loja", "CNPJ_Loja", "CNPJ Estabelecimento",
            "CNPJ_Emitente", "CNPJ Emitente"
        ]

        for alvo in opcoes_exatas:
            for col in base.columns:
                if str(col).strip().lower() == str(alvo).strip().lower():
                    return col

        for col in base.columns:
            nome = str(col).lower()
            if "cnpj" in nome or "cpfcnpj" in nome or "cpf/cnpj" in nome:
                return col

        return None
    except Exception:
        return None


def aplicar_classificacao_cliente_concorrente(base, nome_base=""):
    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return base

        base = base.copy()
        cnpjs_cliente, cadastro = carregar_cnpjs_cliente()
        col_cnpj = encontrar_coluna_cnpj_cliente(base)

        if not col_cnpj:
            base["Tipo_Estabelecimento"] = "Sem CNPJ"
            base["CNPJ_Limpo"] = ""
            return base

        base["CNPJ_Limpo"] = base[col_cnpj].apply(normalizar_cnpj_eirox)

        base["Tipo_Estabelecimento"] = np.where(
            base["CNPJ_Limpo"].isin(cnpjs_cliente),
            "Cliente",
            "Concorrente"
        )

        base.loc[
            base["CNPJ_Limpo"].astype(str).str.strip().eq(""),
            "Tipo_Estabelecimento"
        ] = "Sem CNPJ"

        return base

    except Exception:
        return base


