ARQ_CLIENTES_CADASTRO = Path("CADASTRO_CLIENTES.csv")
ARQ_CLIENTE_CNPJS = Path("CADASTRO_CLIENTE_CNPJS.csv")
ARQ_USUARIOS_CLIENTES = Path("CADASTRO_USUARIOS_CLIENTES.csv")


def _ler_csv_cadastro_eirox(caminho, colunas):
    try:
        if not caminho.exists():
            pd.DataFrame(columns=colunas).to_csv(caminho, index=False, sep=";", encoding="utf-8-sig")
        try:
            df = pd.read_csv(caminho, sep=";", dtype=str, encoding="utf-8-sig")
        except Exception:
            df = pd.read_csv(caminho, dtype=str, encoding="utf-8-sig")
        for col in colunas:
            if col not in df.columns:
                df[col] = ""
        return df[colunas].fillna("")
    except Exception:
        return pd.DataFrame(columns=colunas)


def _salvar_csv_cadastro_eirox(df, caminho, colunas):
    try:
        df = df.copy()
        for col in colunas:
            if col not in df.columns:
                df[col] = ""
        df[colunas].fillna("").to_csv(caminho, index=False, sep=";", encoding="utf-8-sig")
        return True
    except Exception:
        return False


def carregar_clientes_cadastro():
    return _ler_csv_cadastro_eirox(ARQ_CLIENTES_CADASTRO, ["ClienteID", "Cliente", "Cidade", "UF", "Status"])


