def cnpjs_principais_do_usuario():
    """
    Todos os CNPJs do cliente em contexto são Principal.
    Todos os demais CNPJs presentes na base continuam disponíveis como Concorrentes.
    """
    try:
        ids = set(cliente_ids_do_usuario())
        if not ids:
            return set()

        cnpjs = carregar_cliente_cnpjs_cadastro()
        cnpjs = cnpjs[
            cnpjs["ClienteID"].astype(str).str.strip().isin(ids)
            & cnpjs["Status"].astype(str).str.upper().str.strip().ne("INATIVO")
        ].copy()

        cnpjs["CNPJ_Limpo"] = cnpjs["CNPJ"].apply(normalizar_cnpj_eirox)
        return {
            c for c in cnpjs["CNPJ_Limpo"].dropna().astype(str).str.strip().tolist()
            if c and c != "00000000000000"
        }
    except Exception:
        return set()


def aplicar_classificacao_principal_concorrente(base, nome_base=""):
    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return base

        base = base.copy()
        col_cnpj = encontrar_coluna_cnpj_cliente(base)

        if not col_cnpj:
            base["CNPJ_Limpo"] = ""
            base["Tipo_Estabelecimento"] = "Sem CNPJ"
            return base

        principais = cnpjs_principais_do_usuario()
        base["CNPJ_Limpo"] = base[col_cnpj].apply(normalizar_cnpj_eirox)
        base["Tipo_Estabelecimento"] = np.where(base["CNPJ_Limpo"].isin(principais), "Principal", "Concorrente")
        base.loc[base["CNPJ_Limpo"].astype(str).str.strip().eq(""), "Tipo_Estabelecimento"] = "Sem CNPJ"
        return base
    except Exception:
        return base



# --------------------------------------------------
# SINCRONIZAÇÃO CLIENTE / LOGIN / MULTIEMPRESA
# --------------------------------------------------

def eirox_sincronizar_cliente_empresa(cliente_id, nome_cliente, status="ATIVO"):
    """
    ClienteID e EmpresaID são a mesma chave no SaaS.
    Mantém o seletor do administrador sincronizado com a Gestão de Clientes.
    """
    try:
        if "carregar_empresas_sistema" not in globals() or "salvar_empresas_sistema" not in globals():
            return True

        base = carregar_empresas_sistema().copy()
        cid = str(cliente_id).strip()
        nome = str(nome_cliente).strip()
        ativa = "Não" if str(status).upper().strip() == "INATIVO" else "Sim"

        if "EmpresaID" not in base.columns:
            base["EmpresaID"] = ""
        if "Empresa" not in base.columns:
            base["Empresa"] = ""
        if "Ativa" not in base.columns:
            base["Ativa"] = "Sim"
        if "Criado_Em" not in base.columns:
            base["Criado_Em"] = ""

        mask = base["EmpresaID"].astype(str).str.strip().eq(cid)

        if mask.any():
            base.loc[mask, "Empresa"] = nome
            base.loc[mask, "Ativa"] = ativa
        else:
            nova = pd.DataFrame([{
                "EmpresaID": cid,
                "Empresa": nome,
                "Ativa": ativa,
                "Criado_Em": _agora_brasil_txt() if "_agora_brasil_txt" in globals() else ""
            }])
            base = pd.concat([base, nova], ignore_index=True)

        return salvar_empresas_sistema(base)
    except Exception:
        return False


def eirox_sincronizar_usuarios_cliente_login(cliente_id, grupo, usuarios_editados, senhas_digitadas=None):
    """
    Atualiza USUARIOS_EIROX.csv a partir da única tela Gestão de Clientes.

    - EmpresaID = ClienteID
    - Cliente comum nunca vira master.
    - Senha vazia preserva a senha já cadastrada.
    """
    try:
        if "carregar_usuarios_sistema" not in globals() or "salvar_usuarios_sistema" not in globals():
            return True

        cid = str(cliente_id).strip()
        grupo = str(grupo).strip()
        editados = usuarios_editados.copy() if isinstance(usuarios_editados, pd.DataFrame) else pd.DataFrame()
        senhas_digitadas = senhas_digitadas or {}

        sistema = carregar_usuarios_sistema().copy()

        obrigatorias = [
            "Usuario", "Nome", "Perfil", "Senha_Hash", "Ativo",
            "Expira_Em", "Forcar_Reset", "EmpresaID", "Criado_Em", "Atualizado_Em"
        ]
        for c in obrigatorias:
            if c not in sistema.columns:
                sistema[c] = ""

        # Usuários existentes do cliente que não aparecem mais no editor são inativados,
        # mas Paulo/masters nunca são alterados por essa tela.
        usuarios_editor = {
            str(v).strip().lower()
            for v in editados.get("Usuario", pd.Series(dtype=str)).tolist()
            if str(v).strip()
        }

        mask_cliente = sistema["EmpresaID"].astype(str).str.strip().eq(cid)
        mask_nao_master = ~sistema["Usuario"].astype(str).str.strip().str.lower().isin(["paulo", "paulomarques", "vanderlei"])
        mask_remover = mask_cliente & mask_nao_master & ~sistema["Usuario"].astype(str).str.strip().str.lower().isin(usuarios_editor)
        sistema.loc[mask_remover, "Ativo"] = "Não"

        agora = _agora_brasil_txt() if "_agora_brasil_txt" in globals() else ""

        for _, row in editados.iterrows():
            usuario = str(row.get("Usuario", "")).strip().lower()
            if not usuario or usuario in {"paulo", "paulomarques", "vanderlei"}:
                continue

            nome = str(row.get("Nome", "")).strip() or usuario
            perfil = str(row.get("Perfil", "Cliente")).strip()
            # Usuário vinculado a cliente não pode receber perfil master por acidente.
            if perfil.lower() in ["diretoria", "administrador", "admin", "master"]:
                perfil = "Cliente"

            status = str(row.get("Status", "ATIVO")).upper().strip()
            ativo = "Não" if status == "INATIVO" else "Sim"

            mask_usr = sistema["Usuario"].astype(str).str.strip().str.lower().eq(usuario)
            senha_digitada = str(senhas_digitadas.get(usuario, "")).strip()

            if mask_usr.any():
                sistema.loc[mask_usr, "Nome"] = nome
                sistema.loc[mask_usr, "Perfil"] = perfil
                sistema.loc[mask_usr, "Ativo"] = ativo
                sistema.loc[mask_usr, "EmpresaID"] = cid
                sistema.loc[mask_usr, "Atualizado_Em"] = agora
                if senha_digitada:
                    sistema.loc[mask_usr, "Senha_Hash"] = hashlib.sha256(senha_digitada.encode()).hexdigest()
                    sistema.loc[mask_usr, "Forcar_Reset"] = "Não"
            else:
                if not senha_digitada:
                    # Usuário novo precisa de senha.
                    continue
                nova = pd.DataFrame([{
                    "Usuario": usuario,
                    "Nome": nome,
                    "Perfil": perfil,
                    "Senha_Hash": hashlib.sha256(senha_digitada.encode()).hexdigest(),
                    "Ativo": ativo,
                    "Expira_Em": "",
                    "Forcar_Reset": "Não",
                    "EmpresaID": cid,
                    "Criado_Em": agora,
                    "Atualizado_Em": agora,
                }])
                sistema = pd.concat([sistema, nova], ignore_index=True)

        return salvar_usuarios_sistema(sistema)
    except Exception:
        return False


def _proximo_cliente_id_eirox(clientes):
    try:
        ids = pd.to_numeric(clientes.get("ClienteID", pd.Series(dtype=str)), errors="coerce").dropna()
        if ids.empty:
            return "1"
        return str(int(ids.max()) + 1)
    except Exception:
        return "1"


def _substituir_registros_cliente(base_completa, cliente_id, novos_registros, colunas):
    """Substitui somente os registros do cliente em edição e preserva os demais clientes."""
    try:
        base = base_completa.copy() if isinstance(base_completa, pd.DataFrame) else pd.DataFrame(columns=colunas)
        for col in colunas:
            if col not in base.columns:
                base[col] = ""

        cliente_id = str(cliente_id).strip()
        outros = base[base["ClienteID"].astype(str).str.strip().ne(cliente_id)].copy()

        novos = novos_registros.copy() if isinstance(novos_registros, pd.DataFrame) else pd.DataFrame(columns=colunas)
        for col in colunas:
            if col not in novos.columns:
                novos[col] = ""
        novos["ClienteID"] = cliente_id

        # Remove linhas totalmente vazias, mas preserva ClienteID.
        campos_dados = [c for c in colunas if c != "ClienteID"]
        if campos_dados:
            mask = novos[campos_dados].fillna("").astype(str).apply(lambda s: s.str.strip()).ne("").any(axis=1)
            novos = novos[mask].copy()

        return pd.concat([outros[colunas], novos[colunas]], ignore_index=True).fillna("")
    except Exception:
        return base_completa


def renderizar_crud_clientes_cnpjs_usuarios():
    """
    Gestão de clientes em UMA ÚNICA TELA.
    Cliente selecionado no topo controla dados cadastrais, CNPJs/lojas e usuários.
    """
    st.markdown("## 🏢 Gestão de Clientes")
    st.caption("Cadastre e mantenha cada cliente em uma única tela. CNPJs e usuários ficam vinculados automaticamente ao cliente selecionado.")

    clientes = carregar_clientes_cadastro()
    cnpjs_todos = carregar_cliente_cnpjs_cadastro()
    usuarios_todos = carregar_usuarios_clientes_cadastro()

    if clientes.empty:
        clientes = pd.DataFrame(columns=["ClienteID", "Cliente", "Cidade", "UF", "Status"])

    clientes = clientes.fillna("")
    clientes["ClienteID"] = clientes["ClienteID"].astype(str).str.strip()
    clientes["Cliente"] = clientes["Cliente"].astype(str).str.strip()

    # ------------------------------
    # SELETOR ÚNICO DO CLIENTE
    # ------------------------------
    opcoes = []
    mapa_opcoes = {}
    for _, r in clientes.iterrows():
        cid = str(r.get("ClienteID", "")).strip()
        nome = str(r.get("Cliente", "")).strip() or "Cliente sem nome"
        if cid:
            rotulo = f"{cid} - {nome}"
            opcoes.append(rotulo)
            mapa_opcoes[rotulo] = cid

    opcoes = ["➕ Novo cliente"] + opcoes

    selecionado = st.selectbox(
        "Cliente em edição",
        opcoes,
        key="gestao_cliente_selecionado",
        help="Toda a tela abaixo passa a mostrar somente os dados deste cliente."
    )

    novo_cliente = selecionado == "➕ Novo cliente"
    if novo_cliente:
        cliente_id = _proximo_cliente_id_eirox(clientes)
        registro = {"ClienteID": cliente_id, "Cliente": "", "Cidade": "", "UF": "", "Status": "ATIVO"}
    else:
        cliente_id = mapa_opcoes.get(selecionado, "")
        linha = clientes[clientes["ClienteID"].astype(str).str.strip().eq(str(cliente_id).strip())]
        registro = linha.iloc[0].to_dict() if not linha.empty else {"ClienteID": cliente_id, "Cliente": "", "Cidade": "", "UF": "", "Status": "ATIVO"}

    cnpjs_cliente = cnpjs_todos[
        cnpjs_todos["ClienteID"].astype(str).str.strip().eq(str(cliente_id).strip())
    ].copy() if not cnpjs_todos.empty else pd.DataFrame(columns=["ClienteID", "CNPJ", "Nome_Loja", "Cidade", "UF", "Status"])

    usuarios_cliente = usuarios_todos[
        usuarios_todos["ClienteID"].astype(str).str.strip().eq(str(cliente_id).strip())
    ].copy() if not usuarios_todos.empty else pd.DataFrame(columns=["Usuario", "ClienteID", "Perfil", "Status"])

    # ------------------------------
    # RESUMO DO CLIENTE
    # ------------------------------
    k1, k2, k3, k4 = st.columns(4)
    k1.metric("Cliente ID", cliente_id)
    k2.metric("CNPJs / Lojas", int(len(cnpjs_cliente)))
    k3.metric("Usuários vinculados", int(len(usuarios_cliente)))
    status_atual = str(registro.get("Status", "ATIVO") or "ATIVO").upper()
    k4.metric("Status", status_atual)

    st.markdown("### 1. Dados do cliente")
    col1, col2 = st.columns([2.3, 1])
    with col1:
        nome_cliente = st.text_input("Razão social / Nome do cliente", value=str(registro.get("Cliente", "")), key=f"cliente_nome_{cliente_id}")
    with col2:
        status_cliente = st.selectbox(
            "Status",
            ["ATIVO", "INATIVO"],
            index=0 if status_atual != "INATIVO" else 1,
            key=f"cliente_status_{cliente_id}"
        )

    c1, c2, c3 = st.columns([1.4, 0.6, 0.7])
    with c1:
        cidade_cliente = st.text_input("Cidade", value=str(registro.get("Cidade", "")), key=f"cliente_cidade_{cliente_id}")
    with c2:
        uf_atual = str(registro.get("UF", "")).upper().strip()
        ufs = ["", "AC", "AL", "AP", "AM", "BA", "CE", "DF", "ES", "GO", "MA", "MT", "MS", "MG", "PA", "PB", "PR", "PE", "PI", "RJ", "RN", "RS", "RO", "RR", "SC", "SP", "SE", "TO"]
        uf_cliente = st.selectbox("UF", ufs, index=ufs.index(uf_atual) if uf_atual in ufs else 0, key=f"cliente_uf_{cliente_id}")
    with c3:
        st.text_input("Cliente ID", value=cliente_id, disabled=True, key=f"cliente_id_visual_{cliente_id}")

    st.markdown("### 2. CNPJs e lojas do cliente")
    st.caption("Todos os CNPJs cadastrados aqui serão tratados como **Principal** quando este cliente estiver em contexto.")

    cols_cnpj = ["CNPJ", "Nome_Loja", "Cidade", "UF", "Status"]
    editor_cnpjs = cnpjs_cliente.copy()
    for c in ["ClienteID"] + cols_cnpj:
        if c not in editor_cnpjs.columns:
            editor_cnpjs[c] = ""
    editor_cnpjs = editor_cnpjs[cols_cnpj].fillna("")

    editado_cnpjs = eirox_data_editor_brl(
        editor_cnpjs,
        num_rows="dynamic",
        use_container_width=True,
        hide_index=True,
        key=f"editor_cliente_cnpjs_unificado_{cliente_id}",
        column_config={
            "CNPJ": st.column_config.TextColumn("CNPJ", help="CNPJ da loja/unidade"),
            "Nome_Loja": st.column_config.TextColumn("Loja / Nome fantasia"),
            "Cidade": st.column_config.TextColumn("Cidade"),
            "UF": st.column_config.TextColumn("UF", max_chars=2),
            "Status": st.column_config.SelectboxColumn("Status", options=["ATIVO", "INATIVO"]),
        }
    )

    st.markdown("### 3. Usuários com acesso ao cliente")
    st.caption(
        "O login reconhece automaticamente o grupo deste cliente. "
        "Usuários de cliente não podem trocar de empresa; administradores da Eirox podem."
    )

    cols_usr = ["Usuario", "Nome", "Perfil", "Status"]
    editor_usuarios = usuarios_cliente.copy()
    for c in ["ClienteID", "Grupo"] + cols_usr:
        if c not in editor_usuarios.columns:
            editor_usuarios[c] = ""
    editor_usuarios = editor_usuarios[cols_usr].fillna("")

    editado_usuarios = eirox_data_editor_brl(
        editor_usuarios,
        num_rows="dynamic",
        use_container_width=True,
        hide_index=True,
        key=f"editor_cliente_usuarios_unificado_{cliente_id}",
        column_config={
            "Usuario": st.column_config.TextColumn("Usuário"),
            "Nome": st.column_config.TextColumn("Nome"),
            "Perfil": st.column_config.SelectboxColumn(
                "Perfil",
                options=["Cliente", "Gestor", "Analista"]
            ),
            "Status": st.column_config.SelectboxColumn(
                "Status",
                options=["ATIVO", "INATIVO"]
            ),
        }
    )

    st.caption("🔑 Para criar usuário novo ou alterar senha, informe abaixo. Senha em branco mantém a senha atual.")
    senhas_digitadas = {}
    usuarios_ativos_editor = [
        str(v).strip().lower()
        for v in editado_usuarios.get("Usuario", pd.Series(dtype=str)).tolist()
        if str(v).strip()
    ]

    if usuarios_ativos_editor:
        cols_senha = st.columns(min(3, len(usuarios_ativos_editor)))
        for i, usr in enumerate(usuarios_ativos_editor):
            with cols_senha[i % len(cols_senha)]:
                senhas_digitadas[usr] = st.text_input(
                    f"Senha • {usr}",
                    type="password",
                    value="",
                    key=f"senha_cliente_{cliente_id}_{usr}",
                    help="Preencha apenas para criar o usuário ou alterar sua senha."
                )

    st.markdown("### 4. Regra aplicada automaticamente")
    st.info(
        "**Regra automática:** ao entrar, o usuário é vinculado ao Grupo/Cliente pelo login. "
        "Todos os CNPJs cadastrados acima são **Principal**. "
        "Todos os demais CNPJs existentes na base são **Concorrentes**. "
        "Somente administradores da Eirox podem trocar o cliente em contexto."
    )

    # ------------------------------
    # UM ÚNICO BOTÃO DE SALVAMENTO
    # ------------------------------
    salvar_tudo = st.button(
        "💾 Salvar cadastro completo do cliente",
        type="primary",
        use_container_width=True,
        key=f"salvar_cliente_unificado_{cliente_id}"
    )

    if salvar_tudo:
        nome_cliente_limpo = str(nome_cliente).strip()
        if not nome_cliente_limpo:
            st.error("Informe o nome/razão social do cliente antes de salvar.")
            return

        # Atualiza/inclui cliente sem alterar os demais.
        clientes_novo = clientes.copy()
        mask_cliente = clientes_novo["ClienteID"].astype(str).str.strip().eq(str(cliente_id).strip()) if not clientes_novo.empty else pd.Series(dtype=bool)
        registro_novo = {
            "ClienteID": str(cliente_id).strip(),
            "Cliente": nome_cliente_limpo,
            "Cidade": str(cidade_cliente).strip(),
            "UF": str(uf_cliente).strip().upper(),
            "Status": str(status_cliente).strip().upper(),
        }

        if not clientes_novo.empty and mask_cliente.any():
            for campo, valor in registro_novo.items():
                clientes_novo.loc[mask_cliente, campo] = valor
        else:
            clientes_novo = pd.concat([clientes_novo, pd.DataFrame([registro_novo])], ignore_index=True)

        cnpjs_novo = editado_cnpjs.copy()
        cnpjs_novo.insert(0, "ClienteID", str(cliente_id).strip())
        usuarios_novo = editado_usuarios.copy()
        usuarios_novo.insert(1, "ClienteID", str(cliente_id).strip())
        usuarios_novo["Grupo"] = nome_cliente_limpo

        base_cnpjs_final = _substituir_registros_cliente(
            cnpjs_todos,
            cliente_id,
            cnpjs_novo,
            ["ClienteID", "CNPJ", "Nome_Loja", "Cidade", "UF", "Status"]
        )
        base_usuarios_final = _substituir_registros_cliente(
            usuarios_todos,
            cliente_id,
            usuarios_novo,
            ["Usuario", "Nome", "ClienteID", "Grupo", "Perfil", "Status"]
        )

        ok1 = salvar_clientes_cadastro(clientes_novo)
        ok2 = salvar_cliente_cnpjs_cadastro(base_cnpjs_final)
        ok3 = salvar_usuarios_clientes_cadastro(base_usuarios_final)
        ok4 = eirox_sincronizar_cliente_empresa(
            cliente_id,
            nome_cliente_limpo,
            status_cliente
        )
        ok5 = eirox_sincronizar_usuarios_cliente_login(
            cliente_id,
            nome_cliente_limpo,
            usuarios_novo,
            senhas_digitadas
        )

        if ok1 and ok2 and ok3 and ok4 and ok5:
            st.success(
                f"Cliente **{nome_cliente_limpo}** salvo. "
                "Grupo, CNPJs, usuários, login e contexto multiempresa foram sincronizados."
            )
            st.rerun()
        else:
            st.error(
                "Não foi possível concluir toda a sincronização. "
                "Revise os dados de cliente, CNPJs e usuários."
            )


