# CORREÇÃO FINAL PIPELINE - LABORATÓRIO / FAMÍLIA / RECOMENDAÇÕES
# --------------------------------------------------

def eirox_normalizar_colunas_planilha(df):
    """Limpa nomes de colunas, remove Unnamed e tenta promover primeira linha como cabeçalho se necessário."""
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return df

        df = df.copy()
        df.columns = [str(c).strip() for c in df.columns]

        # Se quase tudo for Unnamed, tenta usar uma linha do próprio arquivo como cabeçalho.
        qtd_unnamed = sum(str(c).lower().startswith("unnamed") for c in df.columns)
        if qtd_unnamed >= max(2, int(len(df.columns) * 0.5)):
            for idx in range(min(15, len(df_filtrado))):
                linha = df.iloc[idx].fillna("").astype(str).str.strip().tolist()
                texto = " ".join(linha).lower()
                score = 0
                for termo in ["ean", "gtin", "barra", "produto", "descr", "labor", "fabric", "famil", "class", "curva", "custo"]:
                    if termo in texto:
                        score += 1
                if score >= 2:
                    novo_header = [str(x).strip() if str(x).strip() else f"COL_{i}" for i, x in enumerate(linha)]
                    df = df.iloc[idx+1:].copy()
                    df.columns = novo_header
                    break

        df.columns = [str(c).strip() for c in df.columns]
        return df.dropna(how="all")
    except Exception:
        return df


def eirox_coluna(df, opcoes):
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return None
        mapa = {str(c).strip().lower(): c for c in df.columns}
        for op in opcoes:
            k = str(op).strip().lower()
            if k in mapa:
                return mapa[k]
        for c in df.columns:
            nome = str(c).strip().lower()
            for op in opcoes:
                if str(op).strip().lower() in nome:
                    return c
    except Exception:
        pass
    return None


def eirox_norm_ean(v):
    try:
        if pd.isna(v):
            return ""
        s = str(v).strip()
        if s.endswith(".0"):
            s = s[:-2]
        s = re.sub(r"\D", "", s)
        return s
    except Exception:
        return ""


def eirox_txt(v, padrao="Não informado"):
    try:
        if pd.isna(v):
            return padrao
        s = str(v).strip()
        if s.lower() in ["", "nan", "none", "null", "nat", "não informado", "nao informado"]:
            return padrao
        return s
    except Exception:
        return padrao


def eirox_mapa_auxiliar_produto(compra_base=None, estoque_base=None):
    """
    Monta mapa por EAN com Laboratório, Família, CURVA e Custo.
    Usa COMPRA_TESTE e ESTOQUE_TESTE mesmo quando o cabeçalho veio deslocado.
    """
    try:
        fontes = []
        for base in [compra_base, estoque_base]:
            if isinstance(base, pd.DataFrame) and not base.empty:
                aux = eirox_normalizar_colunas_planilha(base.copy())
                col_ean = eirox_coluna(aux, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras", "codigobarras", "Cod Barras", "Barras"])
                if not col_ean:
                    continue

                col_lab = eirox_coluna(aux, ["Laboratório", "Laboratorio", "LABORATORIO", "Fabricante", "FABRICANTE", "Marca", "MARCA"])
                col_fam = eirox_coluna(aux, ["Família", "Familia", "FAMILIA", "Classificação", "Classificacao", "Categoria", "Grupo", "Departamento", "Classe"])
                col_curva = eirox_coluna(aux, ["CURVA", "Curva", "Curva ABC", "ABC"])
                col_custo = eirox_coluna(aux, ["Custo", "Custo Unitário", "Custo_Unitario", "Preço Compra", "Preco Compra", "Custo Medio", "Custo Médio"])

                tmp = pd.DataFrame()
                tmp["EAN_JOIN"] = aux[col_ean].apply(eirox_norm_ean)
                if col_lab: tmp["Laboratório_aux"] = aux[col_lab].apply(lambda x: eirox_txt(x, ""))
                if col_fam: tmp["Família_aux"] = aux[col_fam].apply(lambda x: eirox_txt(x, ""))
                if col_curva: tmp["CURVA_aux"] = aux[col_curva].apply(lambda x: eirox_txt(x, ""))
                if col_custo: tmp["Custo_aux"] = pd.to_numeric(aux[col_custo].astype(str).str.replace(".", "", regex=False).str.replace(",", ".", regex=False), errors="coerce")

                tmp = tmp[tmp["EAN_JOIN"].astype(str).str.len() > 0].copy()
                if not tmp.empty:
                    fontes.append(tmp)

        if not fontes:
            return pd.DataFrame(columns=["EAN_JOIN", "Laboratório_aux", "Família_aux", "CURVA_aux", "Custo_aux"])

        full = pd.concat(fontes, ignore_index=True, sort=False)

        agg = {}
        for c in ["Laboratório_aux", "Família_aux", "CURVA_aux"]:
            if c in full.columns:
                agg[c] = lambda x: next((str(v).strip() for v in x if str(v).strip() and str(v).strip().lower() not in ["nan", "none", "null", "não informado", "nao informado"]), "")
        if "Custo_aux" in full.columns:
            agg["Custo_aux"] = "mean"

        return full.groupby("EAN_JOIN", as_index=False).agg(agg)
    except Exception:
        return pd.DataFrame(columns=["EAN_JOIN", "Laboratório_aux", "Família_aux", "CURVA_aux", "Custo_aux"])


def corrigir_pipeline_lab_familia_recomendacoes(df_base, compra_base=None, estoque_base=None):
    """
    Correção final:
    - recupera Laboratório/Família/CURVA/Custo por EAN;
    - evita 'Não informado' quando existe dado nas bases auxiliares;
    - aplica recomendações completas.
    """
    try:
        if not isinstance(df_base, pd.DataFrame) or df_base.empty:
            return df_base

        df = df_base.copy()

        col_ean = eirox_coluna(df, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras", "codigobarras"])
        if col_ean:
            df["EAN_JOIN"] = df[col_ean].apply(eirox_norm_ean)
        else:
            df["EAN_JOIN"] = ""

        mapa = eirox_mapa_auxiliar_produto(compra_base, estoque_base)

        for c in ["Laboratório", "Família", "Familia", "CURVA", "Custo"]:
            if c not in df.columns:
                if c == "Custo":
                    df[c] = np.nan
                else:
                    df[c] = "Não informado"

        if isinstance(mapa, pd.DataFrame) and not mapa.empty:
            df = df.merge(mapa, on="EAN_JOIN", how="left")

            if "Laboratório_aux" in df.columns:
                atual = df["Laboratório"].apply(lambda x: eirox_txt(x, ""))
                novo = df["Laboratório_aux"].apply(lambda x: eirox_txt(x, ""))
                df["Laboratório"] = np.where(atual.eq(""), novo, atual)

            if "Família_aux" in df.columns:
                atual = df["Família"].apply(lambda x: eirox_txt(x, ""))
                novo = df["Família_aux"].apply(lambda x: eirox_txt(x, ""))
                df["Família"] = np.where(atual.eq(""), novo, atual)

            if "CURVA_aux" in df.columns:
                atual = df["CURVA"].apply(lambda x: eirox_txt(x, ""))
                novo = df["CURVA_aux"].apply(lambda x: eirox_txt(x, ""))
                df["CURVA"] = np.where(atual.eq(""), novo, atual)

            if "Custo_aux" in df.columns:
                custo_atual = pd.to_numeric(df["Custo"], errors="coerce")
                df["Custo"] = custo_atual.fillna(df["Custo_aux"])

        # Fallback por descrição para família quando ainda faltar.
        if "Produto" in df.columns:
            prod = df["Produto"].fillna("").astype(str).str.upper()
            fam_vazia = df["Família"].apply(lambda x: eirox_txt(x, "")).eq("")
            df.loc[fam_vazia & prod.str.contains("FRALDA|LENÇO|LENCO|INFANTIL|PANTS", regex=True), "Família"] = "Infantil"
            df.loc[fam_vazia & prod.str.contains("SHAMPOO|CONDICIONADOR|CREME|SABONETE|DESODORANTE|DOVE|NIVEA|REXONA|COLGATE", regex=True), "Família"] = "Higiene e Beleza"
            df.loc[fam_vazia & prod.str.contains("DORFLEX|NEOSORO|BENEGRIP|BUSCOPAN|DIPIRONA|PARACETAMOL|IBUPROFENO|ALIVIUM", regex=True), "Família"] = "Medicamentos"

        df["Laboratório"] = df["Laboratório"].apply(lambda x: eirox_txt(x, "Não informado"))
        df["Família"] = df["Família"].apply(lambda x: eirox_txt(x, "Não informado"))
        df["Familia"] = df["Família"]
        df["CURVA"] = df["CURVA"].apply(lambda x: eirox_txt(x, "Não informado"))

        # Recomendações completas
        def num_col(opcoes, default=0):
            for c in opcoes:
                if c in df.columns:
                    return pd.to_numeric(df[c], errors="coerce").fillna(default)
            return pd.Series(default, index=df.index)

        preco_atual = num_col(["Preco_Atual", "Preço Atual", "Preco Atual", "Preço_Atual"], 0)
        preco_sug = num_col(["Preco_Sugerido_Mercado", "Preço Sugerido Mercado", "Preço Máximo Competitivo", "Preco_Maximo_Competitivo", "Preço Recomendado", "Preco_Recomendado"], 0)
        preco_sug = preco_sug.where(preco_sug > 0, preco_atual)
        custo = num_col(["Custo"], 0)

        diff = pd.Series(0.0, index=df.index)
        mask = preco_atual > 0
        diff.loc[mask] = (preco_sug.loc[mask] - preco_atual.loc[mask]) / preco_atual.loc[mask]

        rec = pd.Series("MANTER", index=df.index, dtype=object)
        rec.loc[custo <= 0] = "SEM CUSTO"
        rec.loc[(preco_atual <= 0) & (custo > 0)] = "SEM PREÇO ATUAL"
        rec.loc[(custo > 0) & (preco_atual > 0) & (diff >= 0.03)] = "SUBIR PREÇO"
        rec.loc[(custo > 0) & (preco_atual > 0) & (diff <= -0.03)] = "BAIXAR PREÇO"
        rec.loc[(custo > 0) & (preco_atual > 0) & (diff.abs() < 0.03)] = "MANTER"
        rec.loc[(preco_sug <= 0) & (preco_atual > 0) & (custo > 0)] = "ANALISAR MANUALMENTE"

        df["Recomendacao"] = rec
        df["Recomendação"] = rec

        df.drop(columns=[c for c in ["EAN_JOIN", "Laboratório_aux", "Família_aux", "CURVA_aux", "Custo_aux"] if c in df.columns], inplace=True, errors="ignore")
        return df
    except Exception:
        return df_base



# --------------------------------------------------
# REGRA OFICIAL DE REDE - MENOR PREÇO CONCORRENTE
# --------------------------------------------------

def identificar_rede_menor_preco_eirox(nome_farmacia="", nome_rede=""):
    """
    Recria a regra do projeto antigo:
    identifica a Rede a partir da Farmácia/Nome Fantasia/Razão Social.
    """

    try:
        texto = f"{nome_rede} {nome_farmacia}".upper().strip()
        texto = re.sub(r"\s+", " ", texto)

        if not texto or texto in ["NAN", "NONE", "NULL"]:
            return "Não informado"

        regras = [
            (["ULTRA POPULAR", "ULTRAPOPULAR"], "ULTRA POPULAR"),
            (["DROGARIA PRIMAVERA", "PRIMAVERA LESTE", "PRIMAVERA DO LESTE"], "PRIMAVERA"),
            (["POUPAQUI", "POUPAQUI"], "POUPAQUI"),
            (["PAGUE MENOS"], "PAGUE MENOS"),
            (["RAIA", "DROGASIL", "RAIADROGASIL"], "RAIADROGASIL"),
            (["DROGA RAIA"], "DROGA RAIA"),
            (["BIOFARMA"], "BIOFARMA"),
            (["HSG"], "HSG"),
            (["D A DE CASTRO", "D. A DE CASTRO", "D.A DE CASTRO", "CASTRO"], "CASTRO"),
            (["DROGARIA SAO PAULO", "DROGARIA SÃO PAULO"], "DROGARIA SÃO PAULO"),
            (["NISSEI"], "NISSEI"),
            (["PACHECO"], "PACHECO"),
            (["DROGARIA ARAUJO", "ARAÚJO", "ARAUJO"], "ARAUJO"),
            (["PANVEL"], "PANVEL"),
            (["CLAMED", "DROGARIA CATARINENSE"], "CLAMED"),
            (["FARMACIA PREÇO POPULAR", "PRECO POPULAR", "PREÇO POPULAR"], "PREÇO POPULAR"),
        ]

        for termos, rede in regras:
            for termo in termos:
                if termo in texto:
                    return rede

        # Fallback: usa as primeiras palavras do nome fantasia/razão social.
        texto_limpo = re.sub(r"[^A-ZÀ-Ú0-9\s]", " ", texto)
        texto_limpo = re.sub(r"\s+", " ", texto_limpo).strip()

        remover = {
            "DROGARIA", "DROGARIAS", "FARMACIA", "FARMÁCIA", "FARMA",
            "LTDA", "EIRELI", "S", "A", "SA", "S/A", "COMERCIO", "COMÉRCIO",
            "DE", "DA", "DO", "DOS", "DAS", "PRODUTOS", "FARMACEUTICOS",
            "FARMACÊUTICOS", "ME", "EPP", "CIA"
        }

        partes = [p for p in texto_limpo.split() if p not in remover and len(p) > 1]

        if partes:
            return " ".join(partes[:2])

        return "OUTROS"

    except Exception:
        return "Não informado"


def aplicar_regra_rede_menor_preco(df_base):
    """
    Preenche Rede_Menor_Preco_Concorrente quando estiver vazio,
    usando Farmácia_Menor_Preco / Farmacia_Menor_Preco / Loja Menor Preço.
    """

    try:
        if not isinstance(df_base, pd.DataFrame) or df_base.empty:
            return df_base

        df = df_base.copy()

        # Garante coluna final.
        if "Rede_Menor_Preco_Concorrente" not in df.columns:
            df["Rede_Menor_Preco_Concorrente"] = ""

        # Identifica a melhor coluna de farmácia menor preço.
        opcoes_farmacia = [
            "Farmácia_Menor_Preco",
            "Farmacia_Menor_Preco",
            "Farmácia Menor Preço",
            "Farmacia Menor Preco",
            "Loja Menor Preço Concorrente",
            "Loja do Menor Preço",
            "Loja do Menor Preco",
            "Loja Menor Preço",
            "Farmácia",
            "Farmacia",
            "Nome Fantasia",
            "Razão Social",
            "Razao Social",
        ]

        col_farmacia = None
        mapa = {str(c).strip().lower(): c for c in df.columns}

        for alvo in opcoes_farmacia:
            chave = str(alvo).strip().lower()
            if chave in mapa:
                col_farmacia = mapa[chave]
                break

        if col_farmacia is None:
            for c in df.columns:
                nome = str(c).lower()
                if "farm" in nome or "fantasia" in nome or "razao" in nome or "razão" in nome or "loja menor" in nome:
                    col_farmacia = c
                    break

        # Coluna de rede já existente, se houver.
        col_rede_origem = None
        for alvo in ["Rede", "rede", "Rede_Concorrente", "Rede Concorrente"]:
            chave = str(alvo).strip().lower()
            if chave in mapa:
                col_rede_origem = mapa[chave]
                break

        if col_farmacia is None:
            df["Rede_Menor_Preco_Concorrente"] = df["Rede_Menor_Preco_Concorrente"].replace("", "Não informado").fillna("Não informado")
            return df

        rede_atual = df["Rede_Menor_Preco_Concorrente"].fillna("").astype(str).str.strip()

        farmacia = df[col_farmacia].fillna("").astype(str)
        rede_origem = df[col_rede_origem].fillna("").astype(str) if col_rede_origem else ""

        nova_rede = [
            identificar_rede_menor_preco_eirox(f, r if isinstance(r, str) else "")
            for f, r in zip(farmacia, rede_origem if hasattr(rede_origem, "__iter__") and not isinstance(rede_origem, str) else [""] * len(df))
        ]

        df["Rede_Menor_Preco_Concorrente"] = [
            atual if atual and atual.lower() not in ["nan", "none", "null", "não informado", "nao informado"] else novo
            for atual, novo in zip(rede_atual, nova_rede)
        ]

        df["Rede_Menor_Preco_Concorrente"] = (
            df["Rede_Menor_Preco_Concorrente"]
            .fillna("Não informado")
            .astype(str)
            .str.strip()
            .replace({"": "Não informado", "nan": "Não informado", "None": "Não informado"})
        )

        return df

    except Exception:
        return df_base



# --------------------------------------------------
# REGRA OFICIAL: CLIENTE SELECIONADO / CNPJ PRINCIPAL / CONCORRENTE
# E CUSTO OFICIAL PELO ESTOQUE_TESTE
# --------------------------------------------------

def eirox_normalizar_cnpj_oficial(valor):
    try:
        texto = re.sub(r"\D", "", str(valor))
        if texto.lower() in ["nan", "none", "null"] or texto == "":
            return ""
        if len(texto) <= 14:
            texto = texto.zfill(14)
        return texto[-14:]
    except Exception:
        return ""


def eirox_cliente_selecionado_sidebar():
    """
    Captura o cliente/empresa selecionado no menu lateral.
    Compatível com o texto exibido no selectbox: '1 - D. A DE CASTRO E CIA LTDA'.
    """
    try:
        # Tenta chaves mais prováveis do session_state.
        for chave, valor in st.session_state.items():
            nome = str(chave).lower()
            if any(t in nome for t in ["empresa", "cliente", "contexto"]):
                if valor is not None and str(valor).strip():
                    return str(valor).strip()

        # Fallback para primeiro cliente ativo.
        if "carregar_clientes_cadastro" in globals():
            clientes = carregar_clientes_cadastro()
            if isinstance(clientes, pd.DataFrame) and not clientes.empty:
                if "Status" in clientes.columns:
                    ativos = clientes[clientes["Status"].astype(str).str.upper().str.strip().ne("INATIVO")]
                    if not ativos.empty:
                        clientes = ativos
                if "ClienteID" in clientes.columns and "Cliente" in clientes.columns:
                    r = clientes.iloc[0]
                    return f"{r.get('ClienteID','')} - {r.get('Cliente','')}".strip(" -")
        return ""
    except Exception:
        return ""


def eirox_cliente_id_selecionado():
    try:
        selecionado = eirox_cliente_selecionado_sidebar()
        texto = str(selecionado).strip()

        # Padrão '1 - Cliente'
        m = re.match(r"^\s*([A-Za-z0-9_\-]+)\s*[-–]\s*", texto)
        if m:
            return str(m.group(1)).strip()

        if "carregar_clientes_cadastro" in globals():
            clientes = carregar_clientes_cadastro()
            if isinstance(clientes, pd.DataFrame) and not clientes.empty:
                # tenta comparar pelo nome contido
                for _, r in clientes.iterrows():
                    cid = str(r.get("ClienteID", "")).strip()
                    nome = str(r.get("Cliente", "")).strip()
                    if cid and cid == texto:
                        return cid
                    if nome and nome.upper() in texto.upper():
                        return cid

        return texto
    except Exception:
        return ""


def eirox_cnpjs_do_cliente_selecionado():
    """
    Retorna CNPJs vinculados ao cliente selecionado no menu lateral.
    Usa CADASTRO_CLIENTE_CNPJS.csv / funções existentes do projeto.
    """
    try:
        cliente_id = eirox_cliente_id_selecionado()
        if not cliente_id:
            return set()

        cnpjs = pd.DataFrame()

        if "carregar_cliente_cnpjs_cadastro" in globals():
            cnpjs = carregar_cliente_cnpjs_cadastro()
        else:
            arq = Path("CADASTRO_CLIENTE_CNPJS.csv")
            if arq.exists():
                try:
                    cnpjs = pd.read_csv(arq, sep=";", dtype=str, encoding="utf-8-sig")
                except Exception:
                    cnpjs = pd.read_csv(arq, dtype=str, encoding="utf-8-sig")

        if not isinstance(cnpjs, pd.DataFrame) or cnpjs.empty:
            return set()

        for col in ["ClienteID", "CNPJ", "Status"]:
            if col not in cnpjs.columns:
                cnpjs[col] = ""

        cnpjs = cnpjs[
            cnpjs["ClienteID"].astype(str).str.strip().eq(str(cliente_id).strip())
            & cnpjs["Status"].astype(str).str.upper().str.strip().ne("INATIVO")
        ].copy()

        return {
            eirox_normalizar_cnpj_oficial(v)
            for v in cnpjs["CNPJ"].tolist()
            if eirox_normalizar_cnpj_oficial(v)
        }

    except Exception:
        return set()


def eirox_coluna_cnpj_oficial(df):
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return None
        opcoes = [
            "CNPJ", "CPF/CNPJ", "CPF CNPJ", "cpfcnpj", "CpfCnpj",
            "CNPJ Loja", "CNPJ_Loja", "CNPJ Estabelecimento",
            "CNPJ_Emitente", "CNPJ Emitente", "cnpj", "cnpj_emitente"
        ]
        mapa = {str(c).strip().lower(): c for c in df.columns}
        for alvo in opcoes:
            k = str(alvo).strip().lower()
            if k in mapa:
                return mapa[k]
        for c in df.columns:
            n = str(c).lower()
            if "cnpj" in n or "cpfcnpj" in n or "cpf/cnpj" in n:
                return c
        return None
    except Exception:
        return None


def aplicar_principal_concorrente_cliente_selecionado(df_base):
    """
    Regra global:
    - CNPJ vinculado ao cliente selecionado no menu lateral = Principal
    - Demais CNPJs = Concorrente
    - Sem CNPJ = Concorrente sem CNPJ
    """
    try:
        if not isinstance(df_base, pd.DataFrame) or df_base.empty:
            return df_base

        df = df_base.copy()
        principais = eirox_cnpjs_do_cliente_selecionado()
        col_cnpj = eirox_coluna_cnpj_oficial(df)

        if "CNPJ_Limpo" not in df.columns:
            df["CNPJ_Limpo"] = ""

        if col_cnpj:
            df["CNPJ_Limpo"] = df[col_cnpj].apply(eirox_normalizar_cnpj_oficial)

        if principais:
            df["Tipo_Estabelecimento"] = np.where(
                df["CNPJ_Limpo"].isin(principais),
                "Principal",
                "Concorrente"
            )
        else:
            # Sem cadastro: não marca nada como principal.
            df["Tipo_Estabelecimento"] = "Concorrente"

        df.loc[df["CNPJ_Limpo"].astype(str).str.strip().eq(""), "Tipo_Estabelecimento"] = "Concorrente sem CNPJ"
        df["Eh_Principal"] = df["Tipo_Estabelecimento"].eq("Principal")
        df["Eh_Concorrente"] = ~df["Eh_Principal"]

        return df

    except Exception:
        return df_base


def eirox_coluna_generica(df, opcoes):
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return None
        mapa = {str(c).strip().lower(): c for c in df.columns}
        for alvo in opcoes:
            k = str(alvo).strip().lower()
            if k in mapa:
                return mapa[k]
        for c in df.columns:
            n = str(c).strip().lower()
            for alvo in opcoes:
                if str(alvo).strip().lower() in n:
                    return c
        return None
    except Exception:
        return None


def eirox_numero_br_para_float(v):
    try:
        if pd.isna(v):
            return np.nan
        if isinstance(v, (int, float, np.number)):
            return float(v)
        s = str(v).strip().replace("R$", "").replace("%", "").replace(" ", "")
        if "," in s and "." in s:
            s = s.replace(".", "").replace(",", ".")
        elif "," in s:
            s = s.replace(",", ".")
        return float(s)
    except Exception:
        return np.nan


def mapa_custo_unitario_estoque_teste(estoque_base):
    """
    Custo oficial:
    Custo Unitário = coluna 'Custo Médio' / coluna 'Estoque'
    agrupado por EAN.
    """
    try:
        if not isinstance(estoque_base, pd.DataFrame) or estoque_base.empty:
            return pd.DataFrame(columns=["EAN_JOIN_CUSTO", "Custo_Estoque_Unitario"])

        est = estoque_base.copy()

        col_ean = eirox_coluna_generica(est, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras", "codigobarras", "Barras"])
        col_custo_medio = eirox_coluna_generica(est, ["Custo Médio", "Custo Medio", "Custo_Medio", "Custo Médio Total", "Custo Medio Total"])
        col_estoque = eirox_coluna_generica(est, ["Estoque", "Qtd Estoque", "Quantidade Estoque", "Qtd_Estoque"])

        if not col_ean or not col_custo_medio or not col_estoque:
            return pd.DataFrame(columns=["EAN_JOIN_CUSTO", "Custo_Estoque_Unitario"])

        est["EAN_JOIN_CUSTO"] = est[col_ean].apply(lambda x: re.sub(r"\D", "", str(x).replace(".0", "")))
        est["_CUSTO_MEDIO_TOTAL"] = est[col_custo_medio].apply(eirox_numero_br_para_float)
        est["_ESTOQUE_QTD"] = est[col_estoque].apply(eirox_numero_br_para_float)

        est = est[
            est["EAN_JOIN_CUSTO"].astype(str).str.len().gt(0)
            & est["_ESTOQUE_QTD"].fillna(0).gt(0)
        ].copy()

        if est.empty:
            return pd.DataFrame(columns=["EAN_JOIN_CUSTO", "Custo_Estoque_Unitario"])

        # Soma custo médio total e estoque por EAN, depois divide.
        agg = est.groupby("EAN_JOIN_CUSTO", as_index=False).agg(
            Custo_Medio_Total=("_CUSTO_MEDIO_TOTAL", "sum"),
            Estoque_Total=("_ESTOQUE_QTD", "sum")
        )
        agg["Custo_Estoque_Unitario"] = np.where(
            agg["Estoque_Total"] > 0,
            agg["Custo_Medio_Total"] / agg["Estoque_Total"],
            np.nan
        )

        return agg[["EAN_JOIN_CUSTO", "Custo_Estoque_Unitario"]]

    except Exception:
        return pd.DataFrame(columns=["EAN_JOIN_CUSTO", "Custo_Estoque_Unitario"])


def aplicar_custo_oficial_estoque_teste(df_base, estoque_base=None):
    """
    Substitui/define Custo pelo custo unitário oficial do ESTOQUE_TESTE:
    Custo Médio / Estoque.
    """
    try:
        if not isinstance(df_base, pd.DataFrame) or df_base.empty:
            return df_base

        df = df_base.copy()
        mapa = mapa_custo_unitario_estoque_teste(estoque_base)

        if "Custo" not in df.columns:
            df["Custo"] = np.nan

        col_ean = eirox_coluna_generica(df, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras", "codigobarras"])
        if not col_ean or mapa.empty:
            return df

        df["EAN_JOIN_CUSTO"] = df[col_ean].apply(lambda x: re.sub(r"\D", "", str(x).replace(".0", "")))
        df = df.merge(mapa, on="EAN_JOIN_CUSTO", how="left")

        custo_estoque = pd.to_numeric(df["Custo_Estoque_Unitario"], errors="coerce")
        df["Custo"] = custo_estoque.combine_first(pd.to_numeric(df["Custo"], errors="coerce"))

        # Recalcula lucro/margem com custo oficial, quando houver preço atual.
        preco = None
        for c in ["Preco_Atual", "Preço Atual", "Preco Atual", "Preço_Atual"]:
            if c in df.columns:
                preco = pd.to_numeric(df[c], errors="coerce")
                break

        if preco is not None:
            df["Lucro_Unitario"] = preco.fillna(0) - pd.to_numeric(df["Custo"], errors="coerce").fillna(0)
            df["Lucro Unitário"] = df["Lucro_Unitario"]
            df["Margem_%"] = np.where(preco.fillna(0) > 0, df["Lucro_Unitario"] / preco, 0)

        df.drop(columns=["EAN_JOIN_CUSTO", "Custo_Estoque_Unitario"], inplace=True, errors="ignore")
        return df

    except Exception:
        return df_base


def aplicar_regras_cliente_e_custo_oficiais(df_base, estoque_base=None):
    try:
        df = aplicar_principal_concorrente_cliente_selecionado(df_base)
        df = aplicar_custo_oficial_estoque_teste(df, estoque_base)
        return df
    except Exception:
        return df_base



