def eirox_numero_curto_visual(v):
    try:
        v = float(v)
        if abs(v) >= 1000000:
            return f"{v/1000000:,.1f} mi".replace(",", "X").replace(".", ",").replace("X", ".")
        if abs(v) >= 1000:
            return f"{v/1000:,.1f} mil".replace(",", "X").replace(".", ",").replace("X", ".")
        return f"{v:,.0f}".replace(",", ".")
    except Exception:
        return "0"


