def eirox_norm_cnpj_comparacao(valor):
    try:
        texto = re.sub(r"\D", "", str(valor))
        if not texto:
            return ""
        return texto.zfill(14)[-14:]
    except Exception:
        return ""


def eirox_coluna_cnpj_comparacao(df):
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return None
        opcoes = [
            "CNPJ", "CPF/CNPJ", "CPF CNPJ", "cpfcnpj", "CpfCnpj",
            "CNPJ Loja", "CNPJ_Loja", "CNPJ Estabelecimento",
            "CNPJ_Emitente", "CNPJ Emitente", "cnpj", "cnpj_emitente"
        ]
        mapa = {str(c).strip().lower(): c for c in df.columns}
        for alvo in opcoes:
            k = str(alvo).strip().lower()
            if k in mapa:
                return mapa[k]
        for c in df.columns:
            n = str(c).lower()
            if "cnpj" in n or "cpfcnpj" in n or "cpf/cnpj" in n:
                return c
    except Exception:
        pass
    return None


def eirox_cnpjs_cliente_menu_comparacao():
    try:
        if "eirox_cnpjs_do_cliente_selecionado" in globals():
            s = eirox_cnpjs_do_cliente_selecionado()
            if s:
                return {eirox_norm_cnpj_comparacao(x) for x in s if eirox_norm_cnpj_comparacao(x)}

        cliente_id = ""
        if "eirox_cliente_id_selecionado" in globals():
            cliente_id = str(eirox_cliente_id_selecionado()).strip()

        if not cliente_id:
            return set()

        arq = Path("CADASTRO_CLIENTE_CNPJS.csv")
        if not arq.exists():
            return set()

        try:
            cad = pd.read_csv(arq, sep=";", dtype=str, encoding="utf-8-sig")
        except Exception:
            cad = pd.read_csv(arq, dtype=str, encoding="utf-8-sig")

        if "ClienteID" not in cad.columns or "CNPJ" not in cad.columns:
            return set()

        if "Status" not in cad.columns:
            cad["Status"] = "ATIVO"

        cad = cad[
            cad["ClienteID"].astype(str).str.strip().eq(cliente_id)
            & cad["Status"].astype(str).str.upper().str.strip().ne("INATIVO")
        ].copy()

        return {eirox_norm_cnpj_comparacao(x) for x in cad["CNPJ"].tolist() if eirox_norm_cnpj_comparacao(x)}

    except Exception:
        return set()


def eirox_aplicar_principal_comparacao_hist(analise_hist):
    """
    Força a tela Rede/Loja vs Concorrentes a tratar como Principal todos os CNPJs
    vinculados à empresa selecionada no menu lateral.
    """
    try:
        if not isinstance(analise_hist, pd.DataFrame) or analise_hist.empty:
            return analise_hist, pd.DataFrame(), pd.DataFrame(), False

        hist = analise_hist.copy()
        cnpjs_principais = eirox_cnpjs_cliente_menu_comparacao()
        col_cnpj = eirox_coluna_cnpj_comparacao(hist)

        if col_cnpj and cnpjs_principais:
            hist["_CNPJ_COMP"] = hist[col_cnpj].apply(eirox_norm_cnpj_comparacao)
            hist["_EH_PRINCIPAL_MENU"] = hist["_CNPJ_COMP"].isin(cnpjs_principais)

            base_principal = hist[hist["_EH_PRINCIPAL_MENU"]].copy()
            base_concorrentes = hist[~hist["_EH_PRINCIPAL_MENU"]].copy()

            if not base_principal.empty:
                base_principal["Tipo_Comparacao"] = "Principal"
                base_concorrentes["Tipo_Comparacao"] = "Concorrente"
                return hist, base_principal, base_concorrentes, True

        return hist, pd.DataFrame(), pd.DataFrame(), False

    except Exception:
        return analise_hist, pd.DataFrame(), pd.DataFrame(), False


def eirox_metricas_analise_produtos_comparacao(analise_produtos):
    try:
        if not isinstance(analise_produtos, pd.DataFrame) or analise_produtos.empty:
            return 0, 0, 0, 0

        base = analise_produtos.copy()

        # Produtos = quantidade de linhas/produtos comuns exibidos na tabela.
        produtos = int(len(base))

        if "Qtd_Pesquisas_Selecionado" in base.columns:
            pesquisas = int(pd.to_numeric(base["Qtd_Pesquisas_Selecionado"], errors="coerce").fillna(0).sum())
        else:
            pesquisas = int(len(base))

        if "Ganho_Potencial_Simulador" in base.columns:
            potencial = pd.to_numeric(base["Ganho_Potencial_Simulador"], errors="coerce").fillna(0).sum()
        elif "Ganho_Potencial" in base.columns:
            potencial = pd.to_numeric(base["Ganho_Potencial"], errors="coerce").fillna(0).sum()
        elif "Potencial de Captura" in base.columns:
            potencial = pd.to_numeric(base["Potencial de Captura"], errors="coerce").fillna(0).sum()
        else:
            potencial = 0

        if "Dif_vs_Concorrente_R$" in base.columns:
            dif = pd.to_numeric(base["Dif_vs_Concorrente_R$"], errors="coerce")
            media_dif = dif.dropna().mean()
        else:
            media_dif = 0

        if pd.isna(media_dif):
            media_dif = 0

        return produtos, pesquisas, potencial, media_dif

    except Exception:
        return 0, 0, 0, 0



