def eirox_cnpj_limpo_forcado(valor):
    try:
        s = re.sub(r"\D", "", str(valor))
        if not s:
            return ""
        return s.zfill(14)[-14:]
    except Exception:
        return ""


def eirox_coluna_por_nome_forcado(df, opcoes):
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return None
        mapa = {str(c).strip().lower(): c for c in df.columns}
        for op in opcoes:
            k = str(op).strip().lower()
            if k in mapa:
                return mapa[k]
        for c in df.columns:
            nome = str(c).strip().lower()
            for op in opcoes:
                if str(op).strip().lower() in nome:
                    return c
    except Exception:
        pass
    return None


def eirox_empresa_contexto_id_forcado():
    try:
        if "empresa_contexto_atual" in globals():
            v = empresa_contexto_atual()
            if v is not None and str(v).strip():
                return str(v).strip()

        for chave, valor in st.session_state.items():
            nome = str(chave).lower()
            if any(t in nome for t in ["empresa", "cliente", "contexto"]):
                texto = str(valor).strip()
                if texto:
                    m = re.match(r"^\s*([A-Za-z0-9_\-]+)\s*[-–]\s*", texto)
                    if m:
                        return str(m.group(1)).strip()
                    return texto

        return "1"
    except Exception:
        return "1"


def eirox_cnpjs_cliente_contexto_forcado():
    try:
        empresa_id = eirox_empresa_contexto_id_forcado()
        cad = pd.DataFrame()

        if "carregar_cliente_cnpjs_cadastro" in globals():
            cad = carregar_cliente_cnpjs_cadastro()
        elif Path("CADASTRO_CLIENTE_CNPJS.csv").exists():
            try:
                cad = pd.read_csv("CADASTRO_CLIENTE_CNPJS.csv", sep=";", dtype=str, encoding="utf-8-sig")
            except Exception:
                cad = pd.read_csv("CADASTRO_CLIENTE_CNPJS.csv", dtype=str, encoding="utf-8-sig")
        elif Path("clientes_cnpjs.csv").exists():
            try:
                cad = pd.read_csv("clientes_cnpjs.csv", sep=";", dtype=str, encoding="utf-8-sig")
            except Exception:
                cad = pd.read_csv("clientes_cnpjs.csv", dtype=str, encoding="utf-8-sig")

        if not isinstance(cad, pd.DataFrame) or cad.empty:
            return set()

        if "ClienteID" not in cad.columns:
            col_id = eirox_coluna_por_nome_forcado(cad, ["ClienteID", "EmpresaID", "cliente_id", "empresa_id", "ID"])
            cad["ClienteID"] = cad[col_id] if col_id else empresa_id

        if "CNPJ" not in cad.columns:
            col_cnpj = eirox_coluna_por_nome_forcado(cad, ["CNPJ", "cpfcnpj", "CPF/CNPJ", "CNPJ Loja"])
            if col_cnpj:
                cad["CNPJ"] = cad[col_cnpj]
            else:
                return set()

        if "Status" not in cad.columns:
            cad["Status"] = "ATIVO"

        cad = cad[
            cad["ClienteID"].astype(str).str.strip().eq(str(empresa_id).strip())
            & cad["Status"].astype(str).str.upper().str.strip().ne("INATIVO")
        ].copy()

        return {eirox_cnpj_limpo_forcado(x) for x in cad["CNPJ"].tolist() if eirox_cnpj_limpo_forcado(x)}
    except Exception:
        return set()


def eirox_coluna_cnpj_base_forcado(df):
    return eirox_coluna_por_nome_forcado(
        df,
        [
            "CNPJ", "CPF/CNPJ", "CPF CNPJ", "cpfcnpj", "CpfCnpj",
            "CNPJ Loja", "CNPJ_Loja", "CNPJ Estabelecimento",
            "CNPJ_Emitente", "CNPJ Emitente", "cnpj", "cnpj_emitente"
        ]
    )


def eirox_preparar_hist_comparacao_por_cnpj(analise_hist):
    try:
        if not isinstance(analise_hist, pd.DataFrame) or analise_hist.empty:
            return analise_hist, pd.DataFrame(), pd.DataFrame(), False

        hist = analise_hist.copy()
        cnpjs_cliente = eirox_cnpjs_cliente_contexto_forcado()
        col_cnpj = eirox_coluna_cnpj_base_forcado(hist)

        if not cnpjs_cliente or not col_cnpj:
            return hist, pd.DataFrame(), pd.DataFrame(), False

        hist["_CNPJ_FORCADO"] = hist[col_cnpj].apply(eirox_cnpj_limpo_forcado)
        hist["_EH_PRINCIPAL_FORCADO"] = hist["_CNPJ_FORCADO"].isin(cnpjs_cliente)

        principal = hist[hist["_EH_PRINCIPAL_FORCADO"]].copy()
        concorrente = hist[~hist["_EH_PRINCIPAL_FORCADO"]].copy()

        if principal.empty:
            return hist, pd.DataFrame(), pd.DataFrame(), False

        principal["Tipo_Comparacao"] = "Principal"
        concorrente["Tipo_Comparacao"] = "Concorrente"

        return hist, principal, concorrente, True
    except Exception:
        return analise_hist, pd.DataFrame(), pd.DataFrame(), False


def eirox_metricas_cards_comparacao_forcada(analise_produtos):
    try:
        if not isinstance(analise_produtos, pd.DataFrame) or analise_produtos.empty:
            return 0, 0, 0, 0

        base = analise_produtos.copy()
        produtos = int(len(base))

        if "Qtd_Pesquisas_Selecionado" in base.columns:
            pesquisas = int(pd.to_numeric(base["Qtd_Pesquisas_Selecionado"], errors="coerce").fillna(0).sum())
        else:
            pesquisas = int(len(base))

        if "Ganho_Potencial_Simulador" in base.columns:
            potencial = pd.to_numeric(base["Ganho_Potencial_Simulador"], errors="coerce").fillna(0).sum()
        elif "Ganho_Potencial" in base.columns:
            potencial = pd.to_numeric(base["Ganho_Potencial"], errors="coerce").fillna(0).sum()
        else:
            potencial = 0

        if "Dif_vs_Concorrente_R$" in base.columns:
            media_dif = pd.to_numeric(base["Dif_vs_Concorrente_R$"], errors="coerce").dropna().mean()
        else:
            media_dif = 0

        if pd.isna(media_dif):
            media_dif = 0

        return produtos, pesquisas, potencial, media_dif
    except Exception:
        return 0, 0, 0, 0



