# ============================================================
# EIROX PRICING — NÚCLEO CANÔNICO DE NEGÓCIO
# Fonte de verdade do projeto:
#   1. 📊 Geral
#   2. ⬆️ Subir Preço
#   3. ⬇️ Baixar Preço
#   4. 🤝 Negociar Compra
#
# Toda visão complementar deve respeitar:
# cliente/CNPJs em contexto, município global, principal x
# concorrentes e os mesmos campos de preço/custo/margem.
# ============================================================

EIROX_TELAS_CANONICAS = (
    "📊 Geral",
    "⬆️ Subir Preço",
    "⬇️ Baixar Preço",
    "🤝 Negociar Compra",
)

def eirox_contexto_canonico():
    """Retorna o contexto único usado por todo o projeto."""
    cliente_id, cliente_nome = eirox_cliente_contexto_global()
    municipio = st.session_state.get(
        "eirox_municipio_global",
        st.session_state.get("municipio_global", "Todos")
    )
    return {
        "cliente_id": cliente_id,
        "cliente_nome": cliente_nome,
        "municipio": municipio or "Todos",
    }


def eirox_aplicar_regra_canonica(base):
    """
    Pipeline obrigatório para visões complementares.
    1) aplica cliente/CNPJs;
    2) aplica município global;
    3) preserva a classificação Principal x Concorrente.
    """
    if not isinstance(base, pd.DataFrame):
        return pd.DataFrame()

    df = base.copy()

    try:
        df = eirox_aplicar_cliente_contexto_global(df)
    except Exception:
        pass

    try:
        if "eirox_aplicar_filtro_municipio" in globals():
            df = eirox_aplicar_filtro_municipio(df)
    except Exception:
        pass

    return df


def eirox_validar_regra_canonica(base):
    """Diagnóstico leve para impedir que uma tela use contexto divergente."""
    if not isinstance(base, pd.DataFrame) or base.empty:
        return {
            "linhas": 0,
            "principal": 0,
            "concorrentes": 0,
        }

    principal = 0
    concorrentes = 0
    if "Tipo_Estabelecimento" in base.columns:
        s = base["Tipo_Estabelecimento"].astype(str)
        principal = int(s.eq("Principal").sum())
        concorrentes = int((~s.eq("Principal")).sum())

    return {
        "linhas": int(len(base)),
        "principal": principal,
        "concorrentes": concorrentes,
    }





def eirox_enriquecer_menor_preco_concorrente(base, historico_base=None):
    """
    V1.4.9 — referência única e atômica do menor preço concorrente.

    Para cada EAN, preço, loja e data são sempre obtidos da MESMA linha
    vencedora do histórico. A linha vencedora é o menor preço concorrente
    positivo. Em empate de preço, prioriza-se a ocorrência com data mais
    recente. Datas válidas já existentes na base não são apagadas.
    """
    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return base

        hist = historico_base
        if hist is None:
            hist = historico if "historico" in globals() else pd.DataFrame()
        if not isinstance(hist, pd.DataFrame) or hist.empty:
            return base.copy()

        h = hist.copy()

        # Mantém a classificação oficial Principal x Concorrente, mas não
        # depende dela para localizar as colunas originais da pesquisa.
        try:
            h = eirox_aplicar_regra_canonica(h)
        except Exception:
            try:
                h = eirox_aplicar_cliente_contexto_global(h)
            except Exception:
                pass

        def _col(df, opcoes):
            mapa = {str(c).strip().casefold(): c for c in df.columns}
            for op in opcoes:
                k = str(op).strip().casefold()
                if k in mapa:
                    return mapa[k]
            return None

        def _ean(serie):
            return (
                serie.astype(str)
                .str.replace(".0", "", regex=False)
                .str.replace(r"\D", "", regex=True)
                .str.strip()
            )

        def _datas(serie):
            txt = serie.fillna("").astype(str).str.strip()
            txt = txt.str.replace(
                r"\s+(AMT|AMST|BRT|BRST|GMT(?:[+-]\d+)?|UTC(?:[+-]\d+)?)\s+",
                " ", regex=True, flags=re.IGNORECASE
            )
            # Primeiro tenta o formato real dos arquivos de pesquisa Nota MT.
            dt = pd.to_datetime(
                txt,
                format="%a %b %d %H:%M:%S %Y",
                errors="coerce"
            )
            faltou = dt.isna() & txt.ne("")
            if faltou.any():
                try:
                    dt2 = pd.to_datetime(
                        txt[faltou], errors="coerce", dayfirst=True, format="mixed"
                    )
                except Exception:
                    dt2 = pd.to_datetime(txt[faltou], errors="coerce", dayfirst=True)
                dt.loc[faltou] = dt2
            return dt

        c_ean = _col(h, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"])
        c_preco = _col(h, ["Preço (R$)", "Preco (R$)", "Preço", "Preco", "Valor"])
        c_loja = _col(h, ["Farmácia", "Farmacia", "Loja", "Estabelecimento", "Nome Fantasia"])
        c_data = _col(h, ["Data Emissão", "Data Emissao", "Data Pesquisa", "Data da Pesquisa", "Data"])

        if not c_ean or not c_preco or not c_loja:
            return base.copy()

        h["_EAN_ATOM"] = _ean(h[c_ean])
        h["_PRECO_ATOM"] = pd.to_numeric(h[c_preco], errors="coerce")
        h["_LOJA_ATOM"] = h[c_loja].fillna("").astype(str).str.strip()
        h["_DATA_ATOM"] = _datas(h[c_data]) if c_data else pd.NaT

        # Exclui cliente principal quando essa classificação estiver disponível.
        if "Tipo_Estabelecimento" in h.columns:
            h = h[~h["Tipo_Estabelecimento"].astype(str).str.casefold().eq("principal")].copy()
        elif "Eh_Concorrente" in h.columns:
            mask = h["Eh_Concorrente"].fillna(False).astype(bool)
            if mask.any():
                h = h[mask].copy()

        h = h[
            h["_EAN_ATOM"].ne("") &
            h["_PRECO_ATOM"].notna() &
            h["_PRECO_ATOM"].gt(0) &
            h["_LOJA_ATOM"].ne("")
        ].copy()
        if h.empty:
            return base.copy()

        # Se a mesma combinação EAN+loja+preço apareceu sem data em uma linha e
        # com data em outra, recupera a data da MESMA combinação antes de vencer.
        datas_mesma_ocorrencia = (
            h.dropna(subset=["_DATA_ATOM"])
            .groupby(["_EAN_ATOM", "_LOJA_ATOM", "_PRECO_ATOM"], dropna=False)["_DATA_ATOM"]
            .max()
            .to_dict()
        )
        sem_data = h["_DATA_ATOM"].isna()
        if sem_data.any() and datas_mesma_ocorrencia:
            h.loc[sem_data, "_DATA_ATOM"] = [
                datas_mesma_ocorrencia.get((e, l, p), pd.NaT)
                for e, l, p in zip(
                    h.loc[sem_data, "_EAN_ATOM"],
                    h.loc[sem_data, "_LOJA_ATOM"],
                    h.loc[sem_data, "_PRECO_ATOM"]
                )
            ]

        # Menor preço absoluto por EAN. Em empate, data mais recente; depois a
        # última ocorrência física para estabilidade determinística.
        h["_ORDEM_ATOM"] = np.arange(len(h))
        h["_DATA_ORD_ATOM"] = h["_DATA_ATOM"].fillna(pd.Timestamp.min)
        vencedores = (
            h.sort_values(
                ["_EAN_ATOM", "_PRECO_ATOM", "_DATA_ORD_ATOM", "_ORDEM_ATOM"],
                ascending=[True, True, False, False]
            )
            .drop_duplicates("_EAN_ATOM", keep="first")
            [["_EAN_ATOM", "_PRECO_ATOM", "_LOJA_ATOM", "_DATA_ATOM"]]
            .copy()
        )

        vencedores = vencedores.rename(columns={
            "_EAN_ATOM": "_EAN_JOIN_ATOM",
            "_PRECO_ATOM": "_PRECO_WIN_ATOM",
            "_LOJA_ATOM": "_LOJA_WIN_ATOM",
            "_DATA_ATOM": "_DATA_WIN_ATOM",
        })

        out = base.copy()
        c_ean_base = _col(out, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"])
        if not c_ean_base:
            return out
        out["_EAN_JOIN_ATOM"] = _ean(out[c_ean_base])
        out = out.merge(vencedores, on="_EAN_JOIN_ATOM", how="left", sort=False)

        # Colunas oficiais: agora são preenchidas em conjunto, sem buscas
        # independentes que possam quebrar o vínculo preço-loja-data.
        out["Menor Preço Concorrente"] = out["_PRECO_WIN_ATOM"]
        out["Loja do Menor Preço"] = out["_LOJA_WIN_ATOM"].fillna("")
        out["Data da Pesquisa"] = out["_DATA_WIN_ATOM"].apply(
            lambda x: x.strftime("%d/%m/%Y") if not pd.isna(x) else "Sem data na fonte"
        )

        out = out.drop(columns=[
            "_EAN_JOIN_ATOM", "_PRECO_WIN_ATOM", "_LOJA_WIN_ATOM", "_DATA_WIN_ATOM"
        ], errors="ignore")
        return out

    except Exception:
        # Nunca derruba a aplicação por falha de enriquecimento.
        return base.copy() if isinstance(base, pd.DataFrame) else pd.DataFrame()

def eirox_padronizar_campos_pesquisa_global(base):
    """
    V1.4.9 — camada única de dados de pesquisa para todas as telas.

    Mantém as colunas originais e garante aliases canônicos usados pelo projeto:
    - Menor_Preco
    - Rede_Menor_Preco_Concorrente
    - Farmacia_Menor_Preco
    - Data_Pesquisa

    A fonte continua sendo eirox_enriquecer_menor_preco_concorrente; esta função
    apenas propaga os mesmos valores para os nomes consumidos por outras telas.
    """
    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return base

        out = base.copy()

        def _texto_vazio(serie):
            txt = serie.astype("string").fillna("").str.strip()
            return txt.isin([
                "", "nan", "NaN", "None", "none", "NaT", "null",
                "Não informado", "Nao informado"
            ])

        # Menor preço: preserva valor existente e completa somente quando faltante.
        origem_preco = next((c for c in [
            "Menor Preço Concorrente", "Menor Preco Concorrente",
            "Menor_Preco_Concorrente", "Menor Preço", "Menor_Preco"
        ] if c in out.columns), None)
        if "Menor_Preco" not in out.columns:
            out["Menor_Preco"] = np.nan
        if origem_preco:
            atual = pd.to_numeric(out["Menor_Preco"], errors="coerce")
            novo = pd.to_numeric(out[origem_preco], errors="coerce")
            out["Menor_Preco"] = atual.where(atual.gt(0), novo)

        # Farmácia/loja vencedora: mesma linha usada no menor preço.
        origem_farmacia = next((c for c in [
            "Farmacia_Menor_Preco", "Farmácia_Menor_Preco",
            "Loja do Menor Preço", "Loja Menor Preço",
            "Loja do Menor Preco", "Loja Menor Preco"
        ] if c in out.columns), None)
        if "Farmacia_Menor_Preco" not in out.columns:
            out["Farmacia_Menor_Preco"] = ""
        if origem_farmacia:
            vazio = _texto_vazio(out["Farmacia_Menor_Preco"])
            out.loc[vazio, "Farmacia_Menor_Preco"] = out.loc[vazio, origem_farmacia]

        # Alias acentuado para telas antigas, sem substituir informação existente.
        if "Farmácia_Menor_Preco" not in out.columns:
            out["Farmácia_Menor_Preco"] = out["Farmacia_Menor_Preco"]

        # Data única da pesquisa: preserva a data real e completa aliases.
        origem_data = next((c for c in [
            "Data_Pesquisa", "Data da Pesquisa", "Data Pesquisa",
            "Data_Menor_Concorrente", "Data Pesquisa Concorrente"
        ] if c in out.columns), None)
        if "Data_Pesquisa" not in out.columns:
            out["Data_Pesquisa"] = ""
        if origem_data:
            atual_txt = out["Data_Pesquisa"].astype("string").fillna("").str.strip()
            vazio = atual_txt.isin(["", "nan", "NaN", "None", "none", "NaT", "null", "Sem data na fonte"])
            out.loc[vazio, "Data_Pesquisa"] = out.loc[vazio, origem_data]

        if "Data Pesquisa" not in out.columns:
            out["Data Pesquisa"] = out["Data_Pesquisa"]

        # Rede vencedora: usa a regra oficial já existente do projeto,
        # agora com Farmacia_Menor_Preco disponível para todas as telas.
        out = aplicar_regra_rede_menor_preco(out)

        return out
    except Exception:
        return base


def eirox_rotulo_loja_mapa(valor, limite=24):
    """
    Rótulo curto exibido diretamente no mapa.
    Mantém o nome completo no hover.
    """
    try:
        nome = str(valor).strip()
        if not nome:
            return ""
        if len(nome) <= limite:
            return nome
        return nome[: max(1, limite - 1)].rstrip() + "…"
    except Exception:
        return ""


def eirox_cliente_contexto_global():
    """
    Regra única de contexto do Eirox Pricing.

    Usuário cliente:
      - usa obrigatoriamente o EmpresaID/ClienteID do login.
      - não pode trocar o cliente.

    Administrador:
      - usa o EmpresaID/ClienteID selecionado no menu lateral.

    Nunca tenta descobrir o cliente varrendo chaves genéricas da session_state.
    """
    try:
        # empresa_contexto_atual já possui a regra:
        # master -> cliente selecionado; cliente comum -> empresa do login.
        if "empresa_contexto_atual" in globals():
            cliente_id = str(empresa_contexto_atual()).strip()
        else:
            if "usuario_master" in globals() and usuario_master():
                cliente_id = str(
                    st.session_state.get(
                        "empresa_id_contexto",
                        st.session_state.get("empresa_id_usuario", "1")
                    )
                ).strip()
            else:
                cliente_id = str(
                    st.session_state.get("empresa_id_usuario", "1")
                ).strip()

        if not cliente_id:
            cliente_id = "1"

        cliente_nome = ""

        # 1. Cadastro unificado é a fonte prioritária.
        try:
            cad = carregar_clientes_cadastro() if "carregar_clientes_cadastro" in globals() else pd.DataFrame()
            if isinstance(cad, pd.DataFrame) and not cad.empty and "ClienteID" in cad.columns:
                linha = cad[
                    cad["ClienteID"].astype(str).str.strip().eq(cliente_id)
                ]
                if not linha.empty and "Cliente" in linha.columns:
                    cliente_nome = str(linha.iloc[0]["Cliente"]).strip()
        except Exception:
            pass

        # 2. Compatibilidade com EMPRESAS_EIROX.
        if not cliente_nome:
            try:
                if "obter_nome_empresa" in globals():
                    nome = str(obter_nome_empresa(cliente_id)).strip()
                    if nome and nome.lower() not in [
                        "empresa não identificada",
                        "empresa nao identificada"
                    ]:
                        cliente_nome = nome
            except Exception:
                pass

        # 3. Último fallback controlado.
        if not cliente_nome:
            cliente_nome = f"Cliente {cliente_id}"

        return cliente_id, cliente_nome

    except Exception:
        return "1", "Cliente 1"




def eirox_norm_cnpj_global(valor):
    try:
        s = re.sub(r"\D", "", str(valor))
        if not s:
            return ""
        return s.zfill(14)[-14:]
    except Exception:
        return ""


def eirox_coluna_global(df, opcoes):
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return None

        mapa = {str(c).strip().lower(): c for c in df.columns}

        for op in opcoes:
            k = str(op).strip().lower()
            if k in mapa:
                return mapa[k]

        for c in df.columns:
            nome = str(c).strip().lower()
            for op in opcoes:
                if str(op).strip().lower() in nome:
                    return c

    except Exception:
        pass

    return None


def eirox_cnpjs_cliente_global():
    """
    Busca os CNPJs do cliente selecionado.
    Aceita:
    - função existente do projeto
    - CADASTRO_CLIENTE_CNPJS.csv
    - clientes_cnpjs.csv
    """
    try:
        cliente_id, _ = eirox_cliente_contexto_global()

        if "eirox_cnpjs_cliente_contexto_forcado" in globals():
            cnpjs = eirox_cnpjs_cliente_contexto_forcado()
            if cnpjs:
                return {eirox_norm_cnpj_global(x) for x in cnpjs if eirox_norm_cnpj_global(x)}

        if "eirox_cnpjs_do_cliente_selecionado" in globals():
            cnpjs = eirox_cnpjs_do_cliente_selecionado()
            if cnpjs:
                return {eirox_norm_cnpj_global(x) for x in cnpjs if eirox_norm_cnpj_global(x)}

        cad = pd.DataFrame()
        for arq in ["CADASTRO_CLIENTE_CNPJS.csv", "clientes_cnpjs.csv", "cadastro_cliente_cnpjs.csv"]:
            p = Path(arq)
            if p.exists():
                try:
                    cad = pd.read_csv(p, sep=";", dtype=str, encoding="utf-8-sig")
                except Exception:
                    cad = pd.read_csv(p, dtype=str, encoding="utf-8-sig")
                break

        if not isinstance(cad, pd.DataFrame) or cad.empty:
            return set()

        if "ClienteID" not in cad.columns:
            col_id = eirox_coluna_global(cad, ["ClienteID", "EmpresaID", "cliente_id", "empresa_id", "ID"])
            cad["ClienteID"] = cad[col_id] if col_id else cliente_id

        if "CNPJ" not in cad.columns:
            col_cnpj = eirox_coluna_global(cad, ["CNPJ", "CPF/CNPJ", "cpfcnpj", "CNPJ Loja"])
            if not col_cnpj:
                return set()
            cad["CNPJ"] = cad[col_cnpj]

        if "Status" not in cad.columns:
            cad["Status"] = "ATIVO"

        cad = cad[
            cad["ClienteID"].astype(str).str.strip().eq(str(cliente_id).strip())
            & cad["Status"].astype(str).str.upper().str.strip().ne("INATIVO")
        ].copy()

        return {eirox_norm_cnpj_global(x) for x in cad["CNPJ"].tolist() if eirox_norm_cnpj_global(x)}

    except Exception:
        return set()


def eirox_coluna_cnpj_global(df):
    return eirox_coluna_global(
        df,
        [
            "CNPJ", "CPF/CNPJ", "CPF CNPJ", "cpfcnpj", "CpfCnpj",
            "CNPJ Loja", "CNPJ_Loja", "CNPJ Estabelecimento",
            "CNPJ_Emitente", "CNPJ Emitente", "cnpj", "cnpj_emitente"
        ]
    )


def eirox_aplicar_cliente_contexto_global(df_base):
    """
    Regra mestre aplicada em todo o projeto:
    - CNPJs vinculados ao cliente em contexto = Principal.
    - Todos os outros CNPJs da base = Concorrente.
    - A Rede dos registros Principais recebe sempre o nome do cliente/grupo.
    """
    try:
        if not isinstance(df_base, pd.DataFrame) or df_base.empty:
            return df_base

        df = df_base.copy()
        cliente_id, cliente_nome = eirox_cliente_contexto_global()
        cnpjs = eirox_cnpjs_cliente_global()

        if "Rede" not in df.columns:
            df["Rede"] = ""

        mask_principal = pd.Series(False, index=df.index)

        col_cnpj = eirox_coluna_cnpj_global(df)

        # Regra principal: vínculo formal por CNPJ.
        if col_cnpj and cnpjs:
            cnpj_linha = df[col_cnpj].apply(eirox_norm_cnpj_global)
            mask_principal = cnpj_linha.isin(cnpjs)

        # Compatibilidade somente quando a base realmente usa ID de rede,
        # nunca por qualquer valor arbitrário de tela/session_state.
        if not mask_principal.any() and cliente_id and "Rede" in df.columns:
            rede_txt = df["Rede"].fillna("").astype(str).str.strip()
            mask_principal = rede_txt.eq(str(cliente_id).strip())

        df["Tipo_Estabelecimento"] = np.where(
            mask_principal,
            "Principal",
            "Concorrente"
        )
        df["Tipo_Comparacao"] = df["Tipo_Estabelecimento"]
        df["Eh_Principal"] = mask_principal
        df["Eh_Concorrente"] = ~mask_principal

        # Padroniza o contexto da rede principal em TODAS as linhas/telas.
        # "Rede" continua representando o estabelecimento da própria linha;
        # já Rede_Principal/Rede_Selecionada representam o cliente contra o qual
        # cada concorrente está sendo comparado e, portanto, não podem ficar vazias.
        if cliente_nome:
            df.loc[mask_principal, "Rede"] = cliente_nome
            df["Rede_Principal"] = cliente_nome
            df["Rede_Selecionada"] = cliente_nome

        return df

    except Exception:
        return df_base






