def _eirox_cmp_coluna(df, nomes):
    try:
        return eirox_coluna_global(df, nomes)
    except Exception:
        return None


def _eirox_cmp_normalizar_ean(serie):
    return (
        serie
        .astype(str)
        .str.replace(".0", "", regex=False)
        .str.replace(r"\D", "", regex=True)
        .str.strip()
    )


def eirox_preparar_cliente_x_concorrente(base):
    """
    Prepara o histórico respeitando:
    - Município global;
    - cliente/grupo em contexto;
    - último preço conhecido de cada farmácia por EAN;
    - menor preço válido dentro de cada rede após considerar a data mais recente.
    """
    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return pd.DataFrame()

        b = base.copy()

        if "Rede" not in b.columns and "Farmácia" in b.columns:
            try:
                b["Rede"] = b["Farmácia"].apply(identificar_rede)
            except Exception:
                b["Rede"] = b["Farmácia"].astype(str)

        c_ean = _eirox_cmp_coluna(
            b,
            ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"]
        )
        c_preco = _eirox_cmp_coluna(
            b,
            ["Preço (R$)", "Preco (R$)", "Preço", "Preco", "Valor"]
        )
        c_farmacia = _eirox_cmp_coluna(
            b,
            ["Farmácia", "Farmacia", "Loja", "Estabelecimento", "Nome Fantasia"]
        )
        c_rede = _eirox_cmp_coluna(
            b,
            ["Rede", "Bandeira", "Grupo"]
        )
        c_produto = _eirox_cmp_coluna(
            b,
            ["Produto", "Descricao_Unica", "Descrição", "Descricao"]
        )
        c_data = _eirox_cmp_coluna(
            b,
            ["Data Emissão", "Data Emissao", "Data", "Data Pesquisa", "Data da Pesquisa"]
        )

        if not c_ean or not c_preco or not c_farmacia:
            return pd.DataFrame()

        b["EAN_CMP"] = _eirox_cmp_normalizar_ean(b[c_ean])
        b["PRECO_CMP"] = pd.to_numeric(b[c_preco], errors="coerce")
        b["FARMACIA_CMP"] = b[c_farmacia].fillna("").astype(str).str.strip()
        b["REDE_CMP"] = (
            b[c_rede].fillna("").astype(str).str.strip()
            if c_rede else b["FARMACIA_CMP"]
        )
        b["PRODUTO_CMP"] = (
            b[c_produto].fillna("").astype(str).str.strip()
            if c_produto else ""
        )

        if c_data:
            b["DATA_CMP"] = pd.to_datetime(
                b[c_data],
                errors="coerce",
                dayfirst=True
            )
        else:
            b["DATA_CMP"] = pd.NaT

        b = b[
            b["EAN_CMP"].ne("")
            & b["PRECO_CMP"].notna()
            & (b["PRECO_CMP"] > 0)
            & b["FARMACIA_CMP"].ne("")
        ].copy()

        b = eirox_aplicar_regra_canonica(b)

        # Regra: primeiro fica somente o registro mais recente de cada
        # farmácia para cada EAN. Se não houver data, preserva o último registro.
        b["_ORDEM_CMP"] = range(len(b))
        b = b.sort_values(
            ["EAN_CMP", "FARMACIA_CMP", "DATA_CMP", "_ORDEM_CMP"],
            na_position="first"
        )
        b = (
            b.groupby(
                ["EAN_CMP", "FARMACIA_CMP"],
                as_index=False,
                dropna=False
            )
            .tail(1)
            .copy()
        )

        return b

    except Exception:
        return pd.DataFrame()


def eirox_redes_concorrentes_por_cobertura(base_preparada):
    """
    Ordena concorrentes pela quantidade de EANs em comum com o cliente.
    O primeiro é o 'Principal Concorrente' sugerido.
    """
    try:
        if not isinstance(base_preparada, pd.DataFrame) or base_preparada.empty:
            return pd.DataFrame()

        principal = base_preparada[
            base_preparada["Tipo_Estabelecimento"].astype(str).eq("Principal")
        ].copy()

        concorr = base_preparada[
            ~base_preparada["Tipo_Estabelecimento"].astype(str).eq("Principal")
        ].copy()

        if principal.empty or concorr.empty:
            return pd.DataFrame()

        eans_principal = set(principal["EAN_CMP"].dropna().astype(str))
        concorr = concorr[concorr["EAN_CMP"].astype(str).isin(eans_principal)]

        if concorr.empty:
            return pd.DataFrame()

        resumo = (
            concorr.groupby("REDE_CMP", dropna=False)
            .agg(
                Produtos_Comparaveis=("EAN_CMP", "nunique"),
                Lojas=("FARMACIA_CMP", "nunique")
            )
            .reset_index()
            .rename(columns={"REDE_CMP": "Concorrente"})
            .sort_values(
                ["Produtos_Comparaveis", "Lojas", "Concorrente"],
                ascending=[False, False, True]
            )
        )

        return resumo

    except Exception:
        return pd.DataFrame()


def eirox_montar_cliente_x_concorrente(base_preparada, rede_concorrente):
    try:
        if not isinstance(base_preparada, pd.DataFrame) or base_preparada.empty:
            return pd.DataFrame()

        _, cliente_nome = eirox_cliente_contexto_global()

        principal = base_preparada[
            base_preparada["Tipo_Estabelecimento"].astype(str).eq("Principal")
        ].copy()

        concorr = base_preparada[
            (~base_preparada["Tipo_Estabelecimento"].astype(str).eq("Principal"))
            & base_preparada["REDE_CMP"].astype(str).eq(str(rede_concorrente))
        ].copy()

        if principal.empty or concorr.empty:
            return pd.DataFrame()

        # Menor preço válido de cada rede, considerando somente o preço
        # mais recente de cada farmácia (já tratado no preparo).
        idx_cli = principal.groupby("EAN_CMP")["PRECO_CMP"].idxmin()
        cli = principal.loc[idx_cli].copy()

        idx_con = concorr.groupby("EAN_CMP")["PRECO_CMP"].idxmin()
        con = concorr.loc[idx_con].copy()

        cli = cli[
            [
                "EAN_CMP", "PRODUTO_CMP", "PRECO_CMP",
                "FARMACIA_CMP", "DATA_CMP"
            ]
        ].rename(
            columns={
                "PRODUTO_CMP": "Produto",
                "PRECO_CMP": "Preço Cliente",
                "FARMACIA_CMP": "Loja Cliente",
                "DATA_CMP": "Data Cliente"
            }
        )

        con = con[
            [
                "EAN_CMP", "PRODUTO_CMP", "PRECO_CMP",
                "FARMACIA_CMP", "DATA_CMP"
            ]
        ].rename(
            columns={
                "PRODUTO_CMP": "Produto Concorrente",
                "PRECO_CMP": "Preço Concorrente",
                "FARMACIA_CMP": "Loja Concorrente",
                "DATA_CMP": "Data Concorrente"
            }
        )

        out = cli.merge(con, on="EAN_CMP", how="inner")

        if out.empty:
            return out

        out["Produto"] = (
            out["Produto"]
            .where(out["Produto"].astype(str).str.strip().ne(""), out["Produto Concorrente"])
        )
        out["Cliente"] = cliente_nome
        out["Principal Concorrente"] = str(rede_concorrente)

        out["Dif R$"] = (
            out["Preço Cliente"] - out["Preço Concorrente"]
        ).round(2)

        out["Dif %"] = np.where(
            out["Preço Concorrente"] > 0,
            out["Dif R$"] / out["Preço Concorrente"] * 100,
            np.nan
        )
        out["Dif %"] = pd.to_numeric(out["Dif %"], errors="coerce").round(2)

        out["Status"] = np.select(
            [
                out["Dif R$"] < -0.01,
                out["Dif R$"] > 0.01,
            ],
            [
                "CLIENTE MAIS BARATO",
                "CONCORRENTE MAIS BARATO",
            ],
            default="PREÇOS IGUAIS"
        )

        out = out.rename(columns={"EAN_CMP": "EAN"})
        out = out.sort_values(["Dif %", "EAN"], ascending=[False, True])

        return out

    except Exception:
        return pd.DataFrame()




def eirox_brl(valor, vazio="—"):
    """Formata valor monetário no padrão brasileiro: R$ 1.234,56."""
    try:
        if valor is None or (isinstance(valor, float) and np.isnan(valor)):
            return vazio
        n = float(valor)
        s = f"{n:,.2f}"
        s = s.replace(",", "X").replace(".", ",").replace("X", ".")
        return f"R$ {s}"
    except Exception:
        return vazio


def eirox_percentual_br(valor, casas=2, vazio="—"):
    try:
        if valor is None or (isinstance(valor, float) and np.isnan(valor)):
            return vazio
        return f"{float(valor):.{casas}f}%".replace(".", ",")
    except Exception:
        return vazio


def eirox_colunas_monetarias(df):
    """
    Detecta somente colunas financeiras.
    Evita falsos positivos como 'Loja do Menor Preço' e
    evita falsos negativos como 'Preço Sugerido'/'Venda Projetada'.
    """
    if not isinstance(df, pd.DataFrame):
        return []

    cols = []

    for c in df.columns:
        nome = str(c).strip()
        n = nome.lower()

        # Campos explicitamente não monetários.
        if any(frase in n for frase in [
            "loja do menor preço",
            "loja menor preço",
            "loja_menor_preco",
            "rede_menor_preco",
            "rede menor preco",
            "rede menor preço",
            "farmacia_menor_preco",
            "farmácia_menor_preco",
            "farmacia menor preco",
            "farmácia menor preço",
            "rede_preco_maximo_competitivo",
            "rede preço máximo competitivo",
            "rede preco maximo competitivo",
            "loja_preco_maximo_competitivo",
            "loja preço máximo competitivo",
            "loja preco maximo competitivo",
            "farmacia_preco_maximo_competitivo",
            "farmácia_preco_maximo_competitivo",
            "farmacia preço máximo competitivo",
            "farmácia preço máximo competitivo",
            "data_preco_maximo_competitivo",
            "data preço máximo competitivo",
            "data preco maximo competitivo",
            "data_menor_preco",
            "data menor preço",
            "data menor preco",
            "data da pesquisa",
            "data pesquisa",
            "data_pesquisa",
        ]):
            continue

        # V1.4.11 — campos descritivos ligados a preço nunca são moeda.
        # Ex.: "Rede Preço Máximo Competitivo" e "Data Preço Máximo Competitivo"
        # contêm a palavra "preço", mas são texto/data. A exportação já estava
        # correta; apenas a visualização os convertia para número e os deixava vazios.
        if any(k in n for k in ["rede", "loja", "farmácia", "farmacia", "data"]):
            if "preço" in n or "preco" in n:
                continue

        # Identificadores / quantitativos / percentuais.
        tokens = set(re.findall(r"[a-zà-ÿ0-9]+", n))
        if tokens.intersection({
            "ean", "gtin", "id", "ranking", "curva",
            "qtd", "quantidade", "itens", "estoque"
        }):
            continue

        if "%" in nome or tokens.intersection({
            "percentual", "participação", "participacao",
            "margempercentual"
        }):
            continue

        # Expressões monetárias prioritárias.
        monetario = any(frase in n for frase in [
            "preço", "preco",
            "custo",
            "ganho",
            "lucro",
            "faturamento",
            "receita",
            "economia",
            "potencial",
            "investimento",
            "ticket",
            "mrr",
            "venda preço",
            "venda preco",
            "venda projetada",
            "valor",
        ])

        if monetario:
            cols.append(c)

    return cols

def eirox_column_config_brl(df, config_existente=None):
    """
    Cria/combina column_config para exibir valores monetários como Real.
    Mantém os dados numéricos internamente para cálculos e exportação.
    """
    cfg = dict(config_existente or {})
    if isinstance(df, pd.DataFrame):
        for c in eirox_colunas_monetarias(df):
            if c not in cfg:
                cfg[c] = st.column_config.NumberColumn(
                    str(c),
                    format="R$ %.2f"
                )
    return cfg




def eirox_numero_br(valor, casas=2, vazio=""):
    """Formata número no padrão pt-BR sem símbolo monetário."""
    try:
        if valor is None or pd.isna(valor):
            return vazio
        n = float(valor)
        s = f"{n:,.{casas}f}"
        return s.replace(",", "X").replace(".", ",").replace("X", ".")
    except Exception:
        return vazio


def eirox_colunas_numericas_nao_monetarias(df):
    """Detecta medidas numéricas, excluindo IDs/EAN/datas/textos/percentuais/moeda."""
    if not isinstance(df, pd.DataFrame):
        return []

    monetarias = set(eirox_colunas_monetarias(df))
    cols = []

    for c in df.columns:
        if c in monetarias:
            continue

        nome = str(c).strip()
        n = nome.lower()

        if any(k in n for k in [
            "ean","gtin","código","codigo"," id","id ","empresaid",
            "data","curva","produto","laboratório","laboratorio",
            "família","familia","loja","farmácia","farmacia",
            "ação","acao","recomend","status","categoria","empresa",
            "município","municipio","rede","descrição","descricao"
        ]):
            continue

        if "%" in nome or any(k in n for k in [
            "margem","percentual","participação","participacao",
            "variação","variacao","taxa"
        ]):
            continue

        try:
            s = pd.to_numeric(df[c], errors="coerce")
            if s.notna().sum() >= max(1, int(len(df) * 0.50)):
                cols.append(c)
        except Exception:
            pass

    return cols


def eirox_dataframe_visual_br(df):
    """
    Cria cópia somente para visualização:
    - moeda: R$ 1.234,56
    - decimal: 1.234,56
    - quantidade: 1.234
    - percentual: 12,34%
    - datas/textos preservados
    O DataFrame original não é alterado.
    """
    if not isinstance(df, pd.DataFrame):
        return df

    out = df.copy()
    monetarias = set(eirox_colunas_monetarias(out))
    numericas = set(eirox_colunas_numericas_nao_monetarias(out))

    for c in monetarias:
        out[c] = out[c].apply(
            lambda v: eirox_numero_para_brl_texto(v, vazio="")
        )

    for c in numericas:
        nome = str(c).lower()
        casas = 0 if any(k in nome for k in [
            "qtd","quantidade","ranking","itens","estoque","produtos","registros","unidades","qtde"
        ]) else 2
        out[c] = out[c].apply(
            lambda v, _casas=casas: eirox_numero_br(v, casas=_casas, vazio="")
        )

    for c in out.columns:
        nome = str(c).lower()
        if c in monetarias:
            continue
        if "%" in str(c) or any(k in nome for k in [
            "margem","percentual","participação","participacao",
            "variação","variacao","taxa"
        ]):
            def _pct(v):
                try:
                    if v is None or pd.isna(v):
                        return ""
                    s = str(v).strip()
                    if "%" in s:
                        return s.replace(".", ",")
                    return f"{float(v):.2f}%".replace(".", ",")
                except Exception:
                    return ""
            out[c] = out[c].apply(_pct)

    # proteção textual geral para datas de pesquisa
    for c in ["Data da Pesquisa", "Data Pesquisa", "Data_Pesquisa"]:
        if c in out.columns:
            s = out[c].astype("string").fillna("")
            s = s.str.strip()
            s = s.replace({
                "<NA>": "Sem data na fonte",
                "None": "Sem data na fonte",
                "none": "Sem data na fonte",
                "nan": "Sem data na fonte",
                "NaN": "Sem data na fonte",
                "NaT": "Sem data na fonte",
                "": "Sem data na fonte",
            })
            out[c] = s

    return out


_eirox_export_excel_auto_counter = 0
_eirox_suprimir_export_auto_st = False


def _eirox_slug_exportacao(valor):
    """Nome seguro e curto para arquivos/chaves de exportação."""
    texto = str(valor or "dados").strip().lower()
    texto = re.sub(r"[^a-z0-9áàâãéêíóôõúç_-]+", "_", texto)
    texto = (
        texto.replace("á", "a").replace("à", "a").replace("â", "a").replace("ã", "a")
             .replace("é", "e").replace("ê", "e").replace("í", "i")
             .replace("ó", "o").replace("ô", "o").replace("õ", "o")
             .replace("ú", "u").replace("ç", "c")
    )
    texto = re.sub(r"_+", "_", texto).strip("_")
    return texto[:80] or "dados"


def _eirox_exportar_excel_automatico(data, titulo=None):
    """
    V1.4.4 - disponibiliza o mesmo botão padrão de Excel após toda tabela
    informativa do projeto, sem alterar o DataFrame original nem as regras.
    """
    global _eirox_export_excel_auto_counter

    try:
        if not isinstance(data, pd.DataFrame) or data.empty or len(data.columns) == 0:
            return None

        helper = globals().get("eirox_botao_excel_padrao")
        if not callable(helper):
            return None

        _eirox_export_excel_auto_counter += 1
        pagina_atual = globals().get("pagina", "Dados")
        titulo_export = titulo or f"{pagina_atual} - Dados"
        slug_pagina = _eirox_slug_exportacao(pagina_atual)
        nome_arquivo = f"eirox_{slug_pagina}_{_eirox_export_excel_auto_counter:02d}.xlsx"
        chave = f"eirox_excel_auto_{slug_pagina}_{_eirox_export_excel_auto_counter:02d}"

        return helper(
            data,
            titulo_export,
            nome_arquivo,
            key=chave,
            use_container_width=True
        )
    except Exception:
        # Exportação nunca deve impedir a renderização da tela.
        return None


def eirox_dataframe_brl(data=None, *args, **kwargs):
    """
    Wrapper global de visualização pt-BR.
    Converte apenas a cópia mostrada na tela; dados originais seguem numéricos.

    V1.4.22: a exportação padrão permanece a ser responsabilidade do interceptor
    universal de st.dataframe. Assim, tabelas chamadas diretamente por st.dataframe
    e tabelas chamadas por este wrapper recebem o MESMO botão "📊 Exportar Excel",
    sem duplicar botões.
    """
    try:
        if isinstance(data, pd.DataFrame):
            visual = eirox_dataframe_visual_br(data)

            # Como valores visuais já são strings pt-BR, remove configs numéricos
            # que fariam o Streamlit reinterpretá-los como padrão en-US.
            cfg = kwargs.get("column_config")
            if isinstance(cfg, dict):
                monetarias = set(eirox_colunas_monetarias(data))
                numericas = set(eirox_colunas_numericas_nao_monetarias(data))
                for c in list(cfg.keys()):
                    if c in monetarias or c in numericas:
                        cfg.pop(c, None)
                kwargs["column_config"] = cfg

            return st.dataframe(visual, *args, **kwargs)
    except Exception:
        pass

    return st.dataframe(data, *args, **kwargs)

def eirox_data_editor_brl(data=None, *args, **kwargs):
    """Wrapper global de data_editor preservando edição e formatando moeda."""
    try:
        if isinstance(data, pd.DataFrame):
            existente = kwargs.get("column_config")
            kwargs["column_config"] = eirox_column_config_brl(data, existente)
    except Exception:
        pass
    return st.data_editor(data, *args, **kwargs)



def eirox_numero_para_brl_texto(v, vazio=""):
    """
    Exportação CSV: transforma número em texto no padrão brasileiro.
    Ex.: 3151.75 -> R$ 3.151,75
    """
    try:
        if v is None or pd.isna(v):
            return vazio

        if isinstance(v, str):
            s = v.strip()
            if not s:
                return vazio

            # já está em R$ brasileiro
            if s.startswith("R$"):
                return s

            # tenta converter formatos brasileiro/americano
            limpo = (
                s.replace("R$", "")
                 .replace(" ", "")
            )

            if "," in limpo and "." in limpo:
                # assume 1.234,56
                limpo = limpo.replace(".", "").replace(",", ".")
            elif "," in limpo:
                limpo = limpo.replace(",", ".")

            n = float(limpo)
        else:
            n = float(v)

        s = f"{n:,.2f}"
        s = s.replace(",", "X").replace(".", ",").replace("X", ".")
        return f"R$ {s}"

    except Exception:
        return vazio


def eirox_exportar_csv_brl(df):
    """
    Retorna DataFrame pronto para CSV:
    - colunas monetárias como texto R$ 1.234,56
    - percentuais como texto brasileiro
    - demais colunas preservadas.
    """
    if not isinstance(df, pd.DataFrame):
        return pd.DataFrame()

    out = df.copy()

    # colunas monetárias
    for c in eirox_colunas_monetarias(out):
        out[c] = out[c].apply(eirox_numero_para_brl_texto)

    # percentuais
    for c in out.columns:
        nome = str(c).lower()
        if "%" in str(c) or any(k in nome for k in [
            "margem", "percentual", "participação", "participacao",
            "variação", "variacao"
        ]):
            if c in eirox_colunas_monetarias(out):
                continue

            def _pct(v):
                try:
                    if v is None or pd.isna(v):
                        return ""
                    if isinstance(v, str) and "%" in v:
                        return v
                    return f"{float(v):.2f}%".replace(".", ",")
                except Exception:
                    return ""
            out[c] = out[c].apply(_pct)

    return out



def eirox_exportar_csv_ptbr(df):
    """CSV pt-BR: moeda, número e percentual já formatados visualmente."""
    return eirox_dataframe_visual_br(df)


def eirox_csv_ptbr_bytes(df):
    return eirox_exportar_csv_ptbr(df).to_csv(
        index=False,
        sep=";"
    ).encode("utf-8-sig")


def eirox_csv_ptbr_bytes(df):
    """
    CSV para Excel em pt-BR:
    - separador ;
    - UTF-8 BOM
    - monetários R$ 1.234,56
    """
    export = eirox_exportar_csv_brl(df)
    return export.to_csv(
        index=False,
        sep=";"
    ).encode("utf-8-sig")


def eirox_excel_padrao_bytes(df, titulo="Exportação Eirox", nome_aba="Dados"):
    """
    Excel padrão Eirox usando OPENPYXL.
    Não depende de xlsxwriter.

    Padrões:
    - moeda: R$ 1.234,56
    - decimal: 1.234,56
    - quantidade: 1.234
    - datas: dd/mm/aaaa
    - filtros, congelamento, tabela e larguras automáticas
    """
    try:
        if not isinstance(df, pd.DataFrame):
            return b""

        export = df.copy()

        # limpa valores técnicos preservando tipos
        export = export.replace({
            "None": "",
            "nan": "",
            "NaN": "",
            "NaT": "",
            "null": "",
        })

        wb = Workbook()
        ws = wb.active

        aba = re.sub(r'[\[\]:*?/\\\\]', "", str(nome_aba or "Dados"))[:31] or "Dados"
        ws.title = aba
        ws.sheet_view.showGridLines = False
        ws.freeze_panes = "A6"

        # cores
        bg_title = "0B2740"
        bg_header = "12324B"
        bg_sub = "071827"
        white = "FFFFFF"
        muted = "8EA9BE"
        line = "28465F"

        thin = Side(style="thin", color=line)

        last_col = max(1, len(export.columns))

        # título
        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=last_col)
        c = ws.cell(1, 1)
        c.value = f"EIROX PRICING ENTERPRISE | {titulo}"
        c.font = Font(color=white, bold=True, size=16)
        c.fill = PatternFill("solid", fgColor=bg_title)
        c.alignment = Alignment(horizontal="left", vertical="center")

        ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=last_col)
        c = ws.cell(2, 1)
        c.value = "Relatório padronizado para análise, filtros e conferência."
        c.font = Font(color=muted, size=10)
        c.fill = PatternFill("solid", fgColor=bg_sub)

        ws.merge_cells(start_row=3, start_column=1, end_row=3, end_column=last_col)
        c = ws.cell(3, 1)
        c.value = (
            f"Gerado em {datetime.now().strftime('%d/%m/%Y %H:%M')} | "
            f"Registros: {len(export):,}".replace(",", ".")
        )
        c.font = Font(color=muted, size=9)
        c.fill = PatternFill("solid", fgColor=bg_sub)

        ws.row_dimensions[1].height = 26
        ws.row_dimensions[2].height = 20
        ws.row_dimensions[3].height = 18
        ws.row_dimensions[4].height = 7

        header_row = 5

        # cabeçalho
        for col_idx, col in enumerate(export.columns, start=1):
            cell = ws.cell(header_row, col_idx)
            cell.value = str(col)
            cell.font = Font(color=white, bold=True)
            cell.fill = PatternFill("solid", fgColor=bg_header)
            cell.alignment = Alignment(horizontal="left", vertical="center")
            cell.border = Border(bottom=thin)

        monetarias = set(eirox_colunas_monetarias(export))
        numericas = set(eirox_colunas_numericas_nao_monetarias(export))

        # dados
        for r_idx, (_, row) in enumerate(export.iterrows(), start=header_row + 1):
            for c_idx, col in enumerate(export.columns, start=1):
                val = row[col]
                cell = ws.cell(r_idx, c_idx)
                nome = str(col).lower()

                if val is None or pd.isna(val):
                    cell.value = ""
                    continue

                # moeda
                if col in monetarias:
                    try:
                        cell.value = float(val)
                        cell.number_format = 'R$ #,##0.00'
                    except Exception:
                        cell.value = str(val)

                # quantidade / número
                elif col in numericas:
                    try:
                        num = float(val)
                        if any(k in nome for k in [
                            "qtd", "quantidade", "ranking",
                            "itens", "estoque", "produtos", "registros"
                        ]):
                            cell.value = int(round(num))
                            cell.number_format = '#,##0'
                        else:
                            cell.value = num
                            cell.number_format = '#,##0.00'
                    except Exception:
                        cell.value = str(val)

                # percentual
                elif "%" in str(col) or any(k in nome for k in [
                    "margem", "percentual", "participação", "participacao",
                    "variação", "variacao", "taxa"
                ]):
                    try:
                        num = float(val)
                        cell.value = num
                        # valores no projeto normalmente já estão em escala 0-100
                        cell.number_format = '0.00'
                    except Exception:
                        cell.value = str(val)

                # data
                elif any(k in nome for k in ["data", "dt_"]):
                    try:
                        dt = pd.to_datetime(val, errors="coerce", dayfirst=True)
                        if not pd.isna(dt):
                            cell.value = dt.to_pydatetime()
                            cell.number_format = 'dd/mm/yyyy'
                        else:
                            cell.value = str(val)
                    except Exception:
                        cell.value = str(val)

                else:
                    cell.value = val

                cell.alignment = Alignment(vertical="center")

        # tabela estruturada
        if len(export.columns) > 0 and len(export) > 0:
            ref = f"A{header_row}:{get_column_letter(len(export.columns))}{header_row + len(export)}"
            safe_name = re.sub(
                r"\W+",
                "",
                f"TabelaEirox{abs(hash((titulo, len(export), len(export.columns))))}"
            )[:200]
            if not safe_name or safe_name[0].isdigit():
                safe_name = "TabelaEirox" + safe_name

            tab = Table(displayName=safe_name, ref=ref)
            style = TableStyleInfo(
                name="TableStyleMedium2",
                showFirstColumn=False,
                showLastColumn=False,
                showRowStripes=True,
                showColumnStripes=False,
            )
            tab.tableStyleInfo = style
            ws.add_table(tab)

        # larguras
        for idx, col in enumerate(export.columns, start=1):
            values = [str(col)]
            for v in export[col].head(300).tolist():
                if v is not None and not pd.isna(v):
                    values.append(str(v))

            width = max(len(v) for v in values) + 2 if values else 12
            width = min(max(width, 11), 38)
            ws.column_dimensions[get_column_letter(idx)].width = width

        # filtro quando tabela vazia
        if len(export.columns) > 0 and len(export) == 0:
            ws.auto_filter.ref = (
                f"A{header_row}:{get_column_letter(len(export.columns))}{header_row}"
            )

        buffer = BytesIO()
        wb.save(buffer)
        buffer.seek(0)
        return buffer.getvalue()

    except Exception as exc:
        try:
            st.error(f"Erro ao gerar Excel: {exc}")
        except Exception:
            pass
        return b""

def eirox_botao_excel_padrao(
    df,
    titulo,
    arquivo,
    key=None,
    use_container_width=True
):
    dados = eirox_excel_padrao_bytes(df, titulo=titulo)
    return st.download_button(
        "📊 Exportar Excel",
        data=dados,
        file_name=arquivo,
        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        key=key,
        use_container_width=use_container_width,
        disabled=not bool(dados)
    )


def render_cliente_x_principal_concorrente():
    st.subheader("⚖️ Cliente x Principal Concorrente")
    legenda_tela(
        "⚖️ Cliente x Principal Concorrente",
        "Comparação direta do cliente em contexto com a principal rede concorrente."
    )

    try:
        _, cliente_nome = eirox_cliente_contexto_global()

        base_cmp = eirox_preparar_cliente_x_concorrente(
            historico if "historico" in globals() else pd.DataFrame()
        )

        if base_cmp.empty:
            st.warning("Não há pesquisas suficientes para montar a comparação.")
            return

        cobertura = eirox_redes_concorrentes_por_cobertura(base_cmp)

        if cobertura.empty:
            st.warning(
                "Não foi encontrado concorrente com produtos comparáveis ao cliente nos filtros atuais."
            )
            return

        opcoes = cobertura["Concorrente"].dropna().astype(str).tolist()
        concorrente_padrao = opcoes[0]

        c1, c2 = st.columns([1.1, 1.4])

        c1.text_input(
            "Cliente Principal",
            value=cliente_nome,
            disabled=True,
            key="cmp_cliente_principal"
        )

        concorrente = c2.selectbox(
            "Principal Concorrente",
            opcoes,
            index=0,
            key="cmp_principal_concorrente",
            help=(
                "O padrão é a rede concorrente com maior quantidade de EANs "
                "em comum com o cliente. Você pode trocar a rede manualmente."
            )
        )

        comp = eirox_montar_cliente_x_concorrente(
            base_cmp,
            concorrente
        )

        if comp.empty:
            st.warning("O concorrente selecionado não possui EANs comparáveis ao cliente.")
            return

        st.caption(
            f"Principal sugerido automaticamente: {concorrente_padrao} • "
            f"Regra de preço: último preço por farmácia e menor preço válido da rede por EAN."
        )

        # Filtros da tela
        f1, f2 = st.columns([1.2, 2])
        status_opcoes = [
            "Todos",
            "CLIENTE MAIS BARATO",
            "CONCORRENTE MAIS BARATO",
            "PREÇOS IGUAIS"
        ]
        status_sel = f1.selectbox(
            "Situação",
            status_opcoes,
            index=0,
            key="cmp_status"
        )
        busca_cmp = f2.text_input(
            "Buscar Produto ou EAN",
            key="cmp_busca"
        )

        view = comp.copy()

        if status_sel != "Todos":
            view = view[view["Status"].eq(status_sel)].copy()

        if busca_cmp:
            termo = str(busca_cmp).strip()
            view = view[
                view["EAN"].astype(str).str.contains(termo, case=False, na=False)
                | view["Produto"].astype(str).str.contains(termo, case=False, na=False)
            ].copy()

        total = len(view)
        cliente_melhor = int(view["Status"].eq("CLIENTE MAIS BARATO").sum())
        concorr_melhor = int(view["Status"].eq("CONCORRENTE MAIS BARATO").sum())
        iguais = int(view["Status"].eq("PREÇOS IGUAIS").sum())

        m1, m2, m3, m4 = st.columns(4)
        m1.metric("Produtos comparados", total)
        m2.metric("Cliente mais barato", cliente_melhor)
        m3.metric("Concorrente mais barato", concorr_melhor)
        m4.metric("Preços iguais", iguais)

        if total > 0:
            media_dif = pd.to_numeric(view["Dif %"], errors="coerce").dropna()
            dif_media = float(media_dif.mean()) if not media_dif.empty else 0.0
            st.caption(
                f"Diferença média Cliente x {concorrente}: "
                f"{dif_media:+.2f}%"
            )

        exibir = view[
            [
                "EAN",
                "Produto",
                "Cliente",
                "Preço Cliente",
                "Loja Cliente",
                "Principal Concorrente",
                "Preço Concorrente",
                "Loja Concorrente",
                "Dif R$",
                "Dif %",
                "Status",
                "Data Cliente",
                "Data Concorrente",
            ]
        ].copy()

        for c in ["Data Cliente", "Data Concorrente"]:
            exibir[c] = pd.to_datetime(
                exibir[c],
                errors="coerce"
            ).dt.strftime("%d/%m/%Y")

        st.markdown("### 📋 Comparação produto a produto")
        eirox_dataframe_brl(
            exibir,
            use_container_width=True,
            hide_index=True,
            height=570,
            column_config={
                "Preço Cliente": st.column_config.NumberColumn(
                    "Preço Cliente", format="R$ %.2f"
                ),
                "Preço Concorrente": st.column_config.NumberColumn(
                    "Preço Concorrente", format="R$ %.2f"
                ),
                "Dif R$": st.column_config.NumberColumn(
                    "Dif R$", format="R$ %.2f"
                ),
                "Dif %": st.column_config.NumberColumn(
                    "Dif %", format="%.2f%%"
                ),
            }
        )

        if pode_exportar and not exibir.empty:
            st.download_button(
                "📥 Exportar Cliente x Principal Concorrente",
                exibir.to_csv(
                    index=False,
                    sep=";",
                    encoding="utf-8-sig"
                ).encode("utf-8-sig"),
                "cliente_x_principal_concorrente.csv",
                "text/csv",
                use_container_width=True,
                key="download_cliente_x_concorrente"
            )
            eirox_botao_excel_padrao(
                exibir,
                "Cliente x Principal Concorrente",
                "cliente_x_principal_concorrente.xlsx",
                key="excel_cliente_x_principal",
                use_container_width=True
            )

        with st.expander("📊 Ranking de concorrentes por cobertura", expanded=False):
            eirox_dataframe_brl(
                cobertura,
                use_container_width=True,
                hide_index=True
            )

    except Exception as exc:
        st.error(f"Não foi possível montar Cliente x Principal Concorrente: {exc}")


def eirox_nome_rede_principal():
    """
    Nome oficial exibido em qualquer campo 'Rede Principal'.
    """
    try:
        _, nome = eirox_cliente_contexto_global()
        return str(nome).strip() or "Cliente em contexto"
    except Exception:
        return "Cliente em contexto"


def eirox_forcar_rede_principal_tabela(base):
    """
    Garante consistência visual nas tabelas consolidadas.
    Não altera a farmácia/loja; apenas o nome da Rede Principal.
    """
    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return base
        out = base.copy()
        nome = eirox_nome_rede_principal()

        for c in [
            "Rede_Principal",
            "Rede_Selecionada",
            "Rede Principal"
        ]:
            if c in out.columns:
                out[c] = nome

        return out
    except Exception:
        return base



def eirox_forcar_nome_cliente_em_rede_principal(base):
    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return base
        out = base.copy()
        _, nome_cliente = eirox_cliente_contexto_global()
        if nome_cliente:
            for coluna in ["Rede_Selecionada", "Rede_Principal", "Rede Principal"]:
                if coluna in out.columns:
                    out[coluna] = nome_cliente
        return out
    except Exception:
        return base


def eirox_base_principal_concorrente_global(df_base):
    """
    Retorna base total, base principal e base concorrente usando sempre o cliente em contexto.
    """
    try:
        base = eirox_aplicar_cliente_contexto_global(df_base)
        principal = base[base["Tipo_Estabelecimento"].eq("Principal")].copy()
        concorrente = base[~base["Tipo_Estabelecimento"].eq("Principal")].copy()
        return base, principal, concorrente
    except Exception:
        return df_base, pd.DataFrame(), pd.DataFrame()


def eirox_metricas_cards_cliente_global(analise_produtos):
    try:
        if not isinstance(analise_produtos, pd.DataFrame) or analise_produtos.empty:
            return 0, 0, 0, 0

        base = analise_produtos.copy()
        produtos = int(len(base))

        if "Qtd_Pesquisas_Selecionado" in base.columns:
            pesquisas = int(pd.to_numeric(base["Qtd_Pesquisas_Selecionado"], errors="coerce").fillna(0).sum())
        else:
            pesquisas = int(len(base))

        if "Ganho_Potencial_Simulador" in base.columns:
            potencial = pd.to_numeric(base["Ganho_Potencial_Simulador"], errors="coerce").fillna(0).sum()
        elif "Ganho_Potencial" in base.columns:
            potencial = pd.to_numeric(base["Ganho_Potencial"], errors="coerce").fillna(0).sum()
        elif "Potencial de Captura" in base.columns:
            potencial = pd.to_numeric(base["Potencial de Captura"], errors="coerce").fillna(0).sum()
        else:
            potencial = 0

        if "Dif_vs_Concorrente_R$" in base.columns:
            media = pd.to_numeric(base["Dif_vs_Concorrente_R$"], errors="coerce").dropna().mean()
        else:
            media = 0

        if pd.isna(media):
            media = 0

        return produtos, pesquisas, potencial, media

    except Exception:
        return 0, 0, 0, 0


# --------------------------------------------------
# PRINCIPAL = BASE DE PRODUTOS DO CLIENTE / CONCORRENTE = PESQUISAS
# --------------------------------------------------

def eirox_base_cliente_produtos_para_comparacao(df_produtos, cliente_nome="Cliente selecionado"):
    """
    Monta a base principal da tela Rede/Loja vs Concorrentes usando os produtos do cliente,
    não apenas as pesquisas capturadas do próprio CNPJ.
    Isso evita a tela retornar só 1 produto quando a pesquisa do cliente tiver poucas linhas.
    """
    try:
        if not isinstance(df_produtos, pd.DataFrame) or df_produtos.empty:
            return pd.DataFrame()

        base = df_produtos.copy()

        # Normaliza EAN.
        if "EAN" not in base.columns and "EAN (GTIN)" in base.columns:
            base["EAN"] = base["EAN (GTIN)"]

        if "EAN" not in base.columns:
            return pd.DataFrame()

        base["EAN"] = (
            base["EAN"]
            .astype(str)
            .str.replace(".0", "", regex=False)
            .str.replace(r"\D", "", regex=True)
            .str.strip()
        )

        base = base[base["EAN"].astype(str).str.len().gt(0)].copy()

        # Preço principal vem da base interna / simulador / preço atual.
        preco_col = None
        for c in ["Preco_Atual", "Preço Atual", "Preco Atual", "Preço_Atual", "Preco_Medio", "Preço Médio"]:
            if c in base.columns:
                preco_col = c
                break

        if preco_col is None:
            return pd.DataFrame()

        base["_PRECO_PRINCIPAL_COMP"] = pd.to_numeric(base[preco_col], errors="coerce")
        base = base.dropna(subset=["_PRECO_PRINCIPAL_COMP"]).copy()

        if base.empty:
            return pd.DataFrame()

        produto_col = "Produto" if "Produto" in base.columns else None

        agg = (
            base
            .groupby("EAN", as_index=False)
            .agg(
                Produto_Pesquisa=(produto_col, "first") if produto_col else ("EAN", "first"),
                Preco_Selecionado=("_PRECO_PRINCIPAL_COMP", "mean"),
                Qtd_Pesquisas_Selecionado=("_PRECO_PRINCIPAL_COMP", "count")
            )
        )

        agg["Farmacia_Selecionada"] = cliente_nome
        agg["Rede_Selecionada"] = cliente_nome

        return agg

    except Exception:
        return pd.DataFrame()


def eirox_preferir_base_cliente_se_tiver_mais_produtos(preco_selecionado_atual, df_produtos, cliente_nome):
    """
    Se a base do cliente tiver mais produtos do que as pesquisas próprias, usa a base do cliente.
    """
    try:
        base_cliente = eirox_base_cliente_produtos_para_comparacao(df_produtos, cliente_nome)

        if not isinstance(base_cliente, pd.DataFrame) or base_cliente.empty:
            return preco_selecionado_atual

        atual_qtd = 0
        if isinstance(preco_selecionado_atual, pd.DataFrame) and not preco_selecionado_atual.empty:
            atual_qtd = int(preco_selecionado_atual["EAN"].nunique()) if "EAN" in preco_selecionado_atual.columns else len(preco_selecionado_atual)

        nova_qtd = int(base_cliente["EAN"].nunique()) if "EAN" in base_cliente.columns else len(base_cliente)

        if nova_qtd > atual_qtd:
            return base_cliente

        return preco_selecionado_atual

    except Exception:
        return preco_selecionado_atual



