def eirox_num_col_rec_antiga(df, opcoes, default=0):
    try:
        for c in opcoes:
            if c in df.columns:
                return pd.to_numeric(df[c], errors="coerce").fillna(default)
        return pd.Series(default, index=df.index)
    except Exception:
        return pd.Series(default, index=df.index)


def aplicar_engine_recomendacoes_restaurada(df_base):
    """
    Categorias oficiais do projeto Pricing antigo:

    - SUBIR PREÇO URGENTE
    - SUBIR PREÇO
    - MANTER
    - COMPETITIVO
    - ANALISAR REDUÇÃO
    - SEM CUSTO

    Esta função substitui as regras novas e padroniza todo o projeto
    com a classificação original.
    """
    try:
        if not isinstance(df_base, pd.DataFrame) or df_base.empty:
            return df_base

        df = df_base.copy()

        custo = eirox_num_col_rec_antiga(
            df,
            ["Custo", "Custo Unitário", "Custo_Unitario", "Custo_Estoque_Unitario"],
            0
        )

        preco_atual = eirox_num_col_rec_antiga(
            df,
            [
                "Preco_Atual",
                "Preço Atual",
                "Preco Atual",
                "Preço_Atual",
                "Preco_Selecionado",
                "Preço Principal",
                "Preco_Medio",
                "Preço Médio"
            ],
            0
        )

        # Referência principal do mercado/concorrência.
        preco_ref = eirox_num_col_rec_antiga(
            df,
            [
                "Preco_Sugerido_Mercado",
                "Preço Sugerido Mercado",
                "Preco_Recomendado",
                "Preço Recomendado",
                "Preço Máximo Competitivo",
                "Preco_Maximo_Competitivo",
                "Menor_Preco_Concorrente",
                "Menor Preço Concorrente",
                "Menor_Preco",
                "Menor Preço"
            ],
            0
        )

        # Se não houver referência, usa preço atual para cair em MANTER/SEM CUSTO.
        preco_ref = preco_ref.where(preco_ref > 0, preco_atual)

        dif_pct = pd.Series(0.0, index=df.index)
        mask = (preco_atual > 0) & (preco_ref > 0)
        dif_pct.loc[mask] = (preco_ref.loc[mask] - preco_atual.loc[mask]) / preco_atual.loc[mask]

        margem_atual = pd.Series(0.0, index=df.index)
        mask_margem = preco_atual > 0
        margem_atual.loc[mask_margem] = (preco_atual.loc[mask_margem] - custo.loc[mask_margem]) / preco_atual.loc[mask_margem]

        # Ganho unitário/potencial ajudam a diferenciar urgente.
        ganho_unit = eirox_num_col_rec_antiga(
            df,
            ["Ganho_Unitario", "Ganho Unitário", "Lucro_Unitario", "Lucro Unitário"],
            0
        )

        ganho_potencial = eirox_num_col_rec_antiga(
            df,
            [
                "Ganho_Potencial_Simulador",
                "Ganho_Potencial",
                "Ganho Potencial",
                "Ganho Produto",
                "Ganho_Potencial_Final",
                "Ganho_Potencial_Atualizado"
            ],
            0
        )

        rec = pd.Series("MANTER", index=df.index, dtype=object)

        # 1. Sem custo sempre prevalece.
        rec.loc[custo <= 0] = "SEM CUSTO"

        # 2. Abaixo da referência: subir preço.
        rec.loc[(custo > 0) & (preco_atual > 0) & (dif_pct >= 0.03)] = "SUBIR PREÇO"

        # 3. Urgente quando gap é alto ou potencial é relevante.
        rec.loc[
            (custo > 0)
            & (preco_atual > 0)
            & (
                (dif_pct >= 0.10)
                | ((dif_pct >= 0.05) & (ganho_potencial > 1000))
                | ((dif_pct >= 0.05) & (ganho_unit > 1))
            )
        ] = "SUBIR PREÇO URGENTE"

        # 4. Preço muito próximo/abaixo do menor mercado: competitivo.
        rec.loc[
            (custo > 0)
            & (preco_atual > 0)
            & (dif_pct <= 0.02)
            & (dif_pct >= -0.05)
            & (margem_atual > 0)
        ] = "COMPETITIVO"

        # 5. Muito acima da referência: analisar redução.
        # Como dif_pct = referencia - preço atual, valor negativo indica preço atual acima do mercado.
        rec.loc[
            (custo > 0)
            & (preco_atual > 0)
            & (dif_pct <= -0.05)
        ] = "ANALISAR REDUÇÃO"

        # 6. Alinhado, mas sem necessidade de ação.
        rec.loc[
            (custo > 0)
            & (preco_atual > 0)
            & (dif_pct.abs() < 0.03)
            & ~(rec.isin(["COMPETITIVO", "ANALISAR REDUÇÃO"]))
        ] = "MANTER"

        # Normalização final exatamente com categorias antigas.
        categorias_validas = [
            "SUBIR PREÇO URGENTE",
            "SUBIR PREÇO",
            "MANTER",
            "COMPETITIVO",
            "ANALISAR REDUÇÃO",
            "SEM CUSTO"
        ]

        rec = rec.fillna("MANTER").astype(str).str.upper().str.strip()
        rec = rec.replace(
            {
                "BAIXAR PREÇO": "ANALISAR REDUÇÃO",
                "SEM PREÇO ATUAL": "MANTER",
                "ACIMA DO MERCADO": "ANALISAR REDUÇÃO",
                "LÍDER DE PREÇO": "COMPETITIVO",
                "ANALISAR MANUALMENTE": "MANTER",
                "REVISAR CUSTO/MARGEM": "SEM CUSTO",
                "": "MANTER"
            }
        )

        rec = rec.where(rec.isin(categorias_validas), "MANTER")

        df["Recomendacao"] = rec
        df["Recomendação"] = rec
        df["Recomendacao_Oficial"] = rec
        df["Recomendação Oficial"] = rec

        return df

    except Exception:
        return df_base


def eirox_acoes_recomendadas_pricing_antigo():
    return {
        "SUBIR PREÇO URGENTE": "Produtos muito abaixo do mercado. Reajustar imediatamente.",
        "SUBIR PREÇO": "Produtos abaixo do mercado com oportunidade de ganho.",
        "MANTER": "Preço alinhado ao mercado. Monitorar concorrência.",
        "COMPETITIVO": "Preço agressivo. Avaliar margem e estratégia comercial.",
        "ANALISAR REDUÇÃO": "Preço elevado frente ao mercado. Revisar posicionamento.",
        "SEM CUSTO": "Produto sem custo cadastrado. Necessário saneamento do cadastro."
    }


