# --------------------------------------------------
# ADAPTER DE COMPATIBILIDADE - CURVA ABC
# --------------------------------------------------

def eirox_coluna_existente(df, opcoes):
    try:
        for c in opcoes:
            if c in df.columns:
                return c
    except Exception:
        pass
    return None


def eirox_serie_segura(df, opcoes, default=None):
    """
    Retorna uma Series compatível com o índice do dataframe.
    Evita KeyError quando a engine nova usa nomes diferentes.
    """
    col = eirox_coluna_existente(df, opcoes)
    if col:
        return df[col]

    if default is None:
        default = ""

    return pd.Series([default] * len(df), index=df.index)


def eirox_preparar_abc_exibir(abc_base, df_contexto=None):
    """
    Converte a saída da nova Curva ABC para o formato esperado pelo dashboard antigo.

    Colunas garantidas:
    - Produto
    - Potencial de Captura
    - Menor Preço
    - Rede
    - Farmácia
    - Data Pesquisa
    - Perc_Acum
    - ABC

    Também preserva EAN e informações do concorrente quando existirem.
    """
    try:
        if not isinstance(abc_base, pd.DataFrame):
            return pd.DataFrame()

        abc = abc_base.copy()

        if abc.empty:
            return pd.DataFrame(
                columns=[
                    "Produto",
                    "Potencial de Captura",
                    "Menor Preço",
                    "Rede",
                    "Farmácia",
                    "Data Pesquisa",
                    "Perc_Acum",
                    "ABC",
                ]
            )

        # Produto
        abc["Produto"] = eirox_serie_segura(
            abc,
            [
                "Produto",
                "Descricao_Unica",
                "Descrição",
                "Descricao",
                "Nome Produto",
            ],
            "Não informado",
        ).fillna("Não informado").astype(str)

        # EAN, quando existir
        if "EAN" not in abc.columns:
            abc["EAN"] = eirox_serie_segura(
                abc,
                ["EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"],
                "",
            ).astype(str)

        # Potencial de Captura
        potencial = eirox_serie_segura(
            abc,
            [
                "Potencial de Captura",
                "Ganho_Potencial",
                "Ganho Potencial",
                "Ganho_Produto",
                "Ganho Produto",
                "Ganho_Potencial_Atualizado",
                "Valor_ABC",
                "Venda_Final_Faturamento",
            ],
            0,
        )
        abc["Potencial de Captura"] = pd.to_numeric(
            potencial,
            errors="coerce",
        ).fillna(0)

        # Menor preço concorrente
        menor_preco = eirox_serie_segura(
            abc,
            [
                "Menor Preço",
                "Menor_Preco",
                "Menor_Preco_Concorrente",
                "Menor Preço Concorrente",
                "Preco_Menor_Concorrente",
            ],
            0,
        )
        abc["Menor Preço"] = pd.to_numeric(
            menor_preco,
            errors="coerce",
        ).fillna(0)

        # Rede do menor concorrente
        abc["Rede"] = eirox_serie_segura(
            abc,
            [
                "Rede",
                "Rede_Menor_Concorrente",
                "Rede Menor Concorrente",
                "Rede_Menor_Preco_Concorrente",
                "Rede_Concorrente",
            ],
            "Não informado",
        ).fillna("Não informado").astype(str)

        # Farmácia do menor concorrente
        abc["Farmácia"] = eirox_serie_segura(
            abc,
            [
                "Farmácia",
                "Farmacia",
                "Farmacia_Menor_Concorrente",
                "Farmácia Menor Concorrente",
                "Farmacia_Menor_Preco",
                "Farmácia Concorrente",
            ],
            "Não informado",
        ).fillna("Não informado").astype(str)

        # Data da pesquisa
        data = eirox_serie_segura(
            abc,
            [
                "Data Pesquisa",
                "Data_Pesquisa",
                "Data_Menor_Concorrente",
                "Data Pesquisa Concorrente",
                "Data Emissão",
                "Data_Emissao",
            ],
            pd.NaT,
        )
        abc["Data Pesquisa"] = pd.to_datetime(
            data,
            errors="coerce",
            dayfirst=True,
        )

        # Percentual acumulado
        perc = eirox_serie_segura(
            abc,
            [
                "Perc_Acum",
                "Perc_Acum_Venda",
                "Percentual Acumulado",
            ],
            0,
        )
        perc_num = pd.to_numeric(perc, errors="coerce").fillna(0)
        # Converte 0-100 para 0-1 se necessário
        if len(perc_num) and perc_num.max() > 1.5:
            perc_num = perc_num / 100
        abc["Perc_Acum"] = perc_num

        # Classe ABC
        classe = eirox_serie_segura(
            abc,
            [
                "ABC",
                "CURVA",
                "CURVA_VENDA_FINAL",
                "Classe ABC",
            ],
            "",
        ).fillna("").astype(str).str.upper().str.strip()

        # Recalcula caso venha vazia
        mask_vazia = ~classe.isin(["A", "B", "C"])
        if mask_vazia.any():
            classe.loc[mask_vazia] = abc.loc[mask_vazia, "Perc_Acum"].apply(
                lambda x: "A" if x <= 0.80 else "B" if x <= 0.95 else "C"
            )

        abc["ABC"] = classe

        # Se houver contexto completo, tenta enriquecer por EAN sem alterar o tamanho da ABC.
        if (
            isinstance(df_contexto, pd.DataFrame)
            and not df_contexto.empty
            and "EAN" in abc.columns
        ):
            contexto = df_contexto.copy()

            if "EAN" not in contexto.columns:
                for c in ["EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"]:
                    if c in contexto.columns:
                        contexto["EAN"] = contexto[c]
                        break

            if "EAN" in contexto.columns:
                contexto["EAN"] = (
                    contexto["EAN"]
                    .astype(str)
                    .str.replace(".0", "", regex=False)
                    .str.replace(r"\D", "", regex=True)
                )
                abc["EAN"] = (
                    abc["EAN"]
                    .astype(str)
                    .str.replace(".0", "", regex=False)
                    .str.replace(r"\D", "", regex=True)
                )

                enriquecer = pd.DataFrame({"EAN": contexto["EAN"]})

                mapa_campos = {
                    "Menor Preço": [
                        "Menor_Preco_Concorrente",
                        "Menor Preço Concorrente",
                        "Menor_Preco",
                    ],
                    "Rede": [
                        "Rede_Menor_Concorrente",
                        "Rede Menor Concorrente",
                        "Rede_Menor_Preco_Concorrente",
                    ],
                    "Farmácia": [
                        "Farmacia_Menor_Concorrente",
                        "Farmácia Menor Concorrente",
                        "Farmacia_Menor_Preco",
                    ],
                    "Data Pesquisa": [
                        "Data_Menor_Concorrente",
                        "Data Pesquisa Concorrente",
                        "Data_Pesquisa",
                    ],
                }

                for destino, opcoes in mapa_campos.items():
                    origem = eirox_coluna_existente(contexto, opcoes)
                    if origem:
                        enriquecer[destino] = contexto[origem]

                if len(enriquecer.columns) > 1:
                    enriquecer = enriquecer.drop_duplicates("EAN", keep="first")
                    abc = abc.merge(
                        enriquecer,
                        on="EAN",
                        how="left",
                        suffixes=("", "_ctx"),
                    )

                    for destino in mapa_campos:
                        ctx = f"{destino}_ctx"
                        if ctx in abc.columns:
                            if destino == "Menor Preço":
                                atual = pd.to_numeric(
                                    abc[destino],
                                    errors="coerce",
                                ).fillna(0)
                                novo = pd.to_numeric(
                                    abc[ctx],
                                    errors="coerce",
                                )
                                abc[destino] = atual.where(atual > 0, novo)
                            elif destino == "Data Pesquisa":
                                atual = pd.to_datetime(
                                    abc[destino],
                                    errors="coerce",
                                )
                                novo = pd.to_datetime(
                                    abc[ctx],
                                    errors="coerce",
                                    dayfirst=True,
                                )
                                abc[destino] = atual.fillna(novo)
                            else:
                                atual = abc[destino].fillna("").astype(str)
                                novo = abc[ctx].fillna("").astype(str)
                                abc[destino] = atual.where(
                                    ~atual.isin(["", "Não informado", "nan", "None"]),
                                    novo,
                                )
                            abc.drop(columns=[ctx], inplace=True)

        colunas = [
            "Produto",
            "Potencial de Captura",
            "Menor Preço",
            "Rede",
            "Farmácia",
            "Data Pesquisa",
            "Perc_Acum",
            "ABC",
        ]

        if "EAN" in abc.columns:
            colunas = ["EAN"] + colunas

        return abc[[c for c in colunas if c in abc.columns]].copy()

    except Exception:
        return pd.DataFrame(
            columns=[
                "Produto",
                "Potencial de Captura",
                "Menor Preço",
                "Rede",
                "Farmácia",
                "Data Pesquisa",
                "Perc_Acum",
                "ABC",
            ]
        )


def eirox_selecionar_colunas_seguras(df_base, colunas, defaults=None):
    """
    Garante todas as colunas solicitadas antes da seleção.
    Evita KeyError em tabelas construídas com engines diferentes.
    """
    try:
        if not isinstance(df_base, pd.DataFrame):
            return pd.DataFrame(columns=colunas)

        df_seguro = df_base.copy()
        defaults = defaults or {}

        for coluna in colunas:
            if coluna not in df_seguro.columns:
                valor = defaults.get(coluna, "")
                df_seguro[coluna] = valor

        return df_seguro[colunas].copy()
    except Exception:
        return pd.DataFrame(columns=colunas)


