# --------------------------------------------------
# PIPELINE MUNICÍPIO -> ENRIQUECIMENTO POR EAN
# --------------------------------------------------

def eirox_ean_norm_pipeline(valor):
    try:
        if pd.isna(valor):
            return ""
        s = str(valor).strip().replace(".0", "")
        return re.sub(r"\D", "", s)
    except Exception:
        return ""


def eirox_coluna_ean_pipeline(base):
    try:
        candidatos = [
            "EAN", "EAN (GTIN)", "GTIN", "Código de Barras",
            "Codigo de Barras", "codigobarras", "Cod Barras"
        ]
        mapa = {str(c).strip().lower(): c for c in base.columns}
        for c in candidatos:
            k = c.strip().lower()
            if k in mapa:
                return mapa[k]
    except Exception:
        pass
    return None


def eirox_merge_aux_por_ean(base_principal, base_aux, prefixo_aux):
    """
    Faz merge seguro por EAN sem exigir Município/Cidade na base auxiliar.
    """
    try:
        if not isinstance(base_principal, pd.DataFrame) or base_principal.empty:
            return base_principal
        if not isinstance(base_aux, pd.DataFrame) or base_aux.empty:
            return base_principal

        principal = base_principal.copy()
        aux = base_aux.copy()

        col_ean_principal = eirox_coluna_ean_pipeline(principal)
        col_ean_aux = eirox_coluna_ean_pipeline(aux)

        if not col_ean_principal or not col_ean_aux:
            return principal

        principal["_EAN_PIPE"] = principal[col_ean_principal].apply(eirox_ean_norm_pipeline)
        aux["_EAN_PIPE"] = aux[col_ean_aux].apply(eirox_ean_norm_pipeline)

        aux = aux[aux["_EAN_PIPE"].astype(str).str.len() > 0].copy()
        principal = principal[principal["_EAN_PIPE"].astype(str).str.len() > 0].copy()

        # Evita explosão de linhas: agrega uma linha útil por EAN.
        # Mantém primeira ocorrência não nula por coluna.
        def _primeiro_valido(serie):
            for v in serie:
                try:
                    if pd.isna(v):
                        continue
                    s = str(v).strip()
                    if s and s.lower() not in ["nan", "none", "null"]:
                        return v
                except Exception:
                    continue
            return None

        cols_aux = [c for c in aux.columns if c != "_EAN_PIPE"]

        agg = {c: _primeiro_valido for c in cols_aux}
        aux_agg = aux.groupby("_EAN_PIPE", as_index=False).agg(agg)

        # Renomeia apenas colunas conflitantes.
        rename = {}
        for c in aux_agg.columns:
            if c == "_EAN_PIPE":
                continue
            if c in principal.columns:
                rename[c] = f"{prefixo_aux}_{c}"

        aux_agg = aux_agg.rename(columns=rename)

        merged = principal.merge(aux_agg, on="_EAN_PIPE", how="left")
        return merged

    except Exception:
        return base_principal


def eirox_enriquecer_pipeline_municipio(df_pesquisa, compra_base, estoque_base, venda_base):
    """
    Fluxo correto:
    1. df_pesquisa já vem filtrado pelo Município.
    2. Enriquece por EAN usando compra, estoque e venda.
    3. Não exige Município nas bases auxiliares.
    4. Reaplica funções oficiais de laboratório/família/custo/recomendações.
    """
    try:
        if not isinstance(df_pesquisa, pd.DataFrame) or df_pesquisa.empty:
            return df_pesquisa

        dfp = df_pesquisa.copy()

        # Primeiro usa as funções oficiais já existentes no projeto.
        try:
            dfp = garantir_colunas_padrao_dashboard(dfp)
        except Exception:
            pass

        try:
            dfp = corrigir_pipeline_lab_familia_recomendacoes(
                dfp, compra_base, estoque_base
            )
        except Exception:
            pass

        try:
            dfp = aplicar_regras_cliente_e_custo_oficiais(
                dfp, estoque_base
            )
        except Exception:
            pass

        try:
            dfp = eirox_aplicar_cliente_contexto_global(dfp)
        except Exception:
            pass

        # Fallback de merge por EAN para garantir que dados auxiliares cheguem.
        dfp = eirox_merge_aux_por_ean(dfp, compra_base, "COMPRA")
        dfp = eirox_merge_aux_por_ean(dfp, estoque_base, "ESTOQUE")
        dfp = eirox_merge_aux_por_ean(dfp, venda_base, "VENDA")

        # Fallback para Laboratório/Família a partir das colunas auxiliares.
        if "Laboratório" not in dfp.columns:
            dfp["Laboratório"] = "Não informado"
        if "Família" not in dfp.columns:
            dfp["Família"] = "Não informado"
        if "CURVA" not in dfp.columns:
            dfp["CURVA"] = "Não informado"

        for destino, candidatos in {
            "Laboratório": [
                "COMPRA_Laboratório","COMPRA_Laboratorio","COMPRA_Fabricante",
                "ESTOQUE_Laboratório","ESTOQUE_Laboratorio","ESTOQUE_Fabricante",
                "Laboratorio","Fabricante"
            ],
            "Família": [
                "COMPRA_Família","COMPRA_Familia","COMPRA_Categoria",
                "ESTOQUE_Família","ESTOQUE_Familia","ESTOQUE_Categoria",
                "Familia","Categoria"
            ],
            "CURVA": [
                "VENDA_CURVA","COMPRA_CURVA","ESTOQUE_CURVA",
                "CURVA_VENDA_FINAL","ABC"
            ],
        }.items():
            atual = dfp[destino].fillna("").astype(str)
            mask = atual.str.strip().isin(["", "Não informado", "Nao informado", "nan", "None"])
            for c in candidatos:
                if c in dfp.columns and mask.any():
                    novo = dfp[c].fillna("").astype(str)
                    usar = mask & ~novo.str.strip().isin(["", "nan", "None"])
                    dfp.loc[usar, destino] = novo[usar]
                    atual = dfp[destino].fillna("").astype(str)
                    mask = atual.str.strip().isin(["", "Não informado", "Nao informado", "nan", "None"])

        # Reaplica custo/recomendação depois do enriquecimento.
        try:
            dfp = aplicar_regras_cliente_e_custo_oficiais(dfp, estoque_base)
        except Exception:
            pass

        try:
            dfp = aplicar_engine_recomendacoes_restaurada(dfp)
        except Exception:
            pass

        try:
            dfp = aplicar_regra_rede_menor_preco(dfp)
        except Exception:
            pass

        try:
            dfp = corrigir_lab_familia_recomendacoes(
                dfp, compra_base, estoque_base
            )
        except Exception:
            pass

        return dfp

    except Exception:
        return df_pesquisa


VERSAO_APP = "Enterprise v1.4.43"

# --------------------------------------------------
# FORMATACAO BRASIL
# --------------------------------------------------

def moeda_br(valor):

    try:

        if pd.isna(valor):
            return ""

        return (
            f"{eirox_brl(float(valor))}"
            .replace(",", "X")
            .replace(".", ",")
            .replace("X", ".")
        )

    except Exception:
        return ""


def moeda_br_kpi(valor):

    """
    Formata moeda para KPI sem cortar o valor no card.
    Mantém o padrão brasileiro e usa MM quando o valor passa de 1 milhão.
    """

    try:
        if pd.isna(valor):
            return ""

        valor = float(valor)

        if abs(valor) >= 1_000_000:
            return (
                f"{eirox_brl(valor / 1_000_000)} MM"
                .replace(",", "X")
                .replace(".", ",")
                .replace("X", ".")
            )

        return moeda_br(valor)

    except Exception:
        return moeda_br(valor)


def numero_br(valor):

    try:

        if pd.isna(valor):
            return ""

        return (
            f"{float(valor):,.2f}"
            .replace(",", "X")
            .replace(".", ",")
            .replace("X", ".")
        )

    except Exception:
        return ""


def percentual_br(valor):

    try:

        if pd.isna(valor):
            return ""

        return (
            f"{float(valor):,.2f}%"
            .replace(",", "X")
            .replace(".", ",")
            .replace("X", ".")
        )

    except Exception:
        return ""


# --------------------------------------------------
# FORMATAÇÃO BRASILEIRA GLOBAL PARA EXIBIÇÃO
# --------------------------------------------------

def inteiro_br(valor):

    try:
        if pd.isna(valor):
            return ""
        return f"{float(valor):,.0f}".replace(",", ".")
    except Exception:
        return ""


def data_br(valor):

    try:
        if pd.isna(valor):
            return ""
        try:
            data = pd.to_datetime(valor, errors="coerce", dayfirst=True, format="mixed")
        except Exception:
            data = pd.to_datetime(valor, errors="coerce", dayfirst=True)
        if pd.isna(data):
            return str(valor)
        return data.strftime("%d/%m/%Y")
    except Exception:
        return str(valor) if valor is not None else ""


def _eirox_tipo_coluna_br(nome_coluna):
    nome = str(nome_coluna).lower().strip()

    # V1.4.12 — prioridade semântica: campos de Data/Rede/Loja/Farmácia
    # associados a preço nunca podem ser classificados como moeda só porque
    # o nome contém "preço". Isso corrige, por exemplo, "Data Menor Preço"
    # e "Data Preço Máximo Competitivo" em todas as tabelas.
    if any(t in nome for t in [
        "data", "dt ", "dt_", "modificado", "criado", "atualização", "atualizacao"
    ]):
        return "data"

    if any(t in nome for t in [
        "rede ", "rede_", "loja ", "loja_", "farmácia", "farmacia",
        "estabelecimento", "concorrente"
    ]) and ("preço" in nome or "preco" in nome):
        return "texto"

    # Margem nominal é valor financeiro, não percentual.
    if "nominal" in nome or "valor_margem" in nome:
        return "moeda"

    if any(t in nome for t in [
        "margem", "percent", "particip", "%", "variação", "variacao",
        "rentabilidade", "share", "taxa"
    ]):
        return "percentual"

    if any(t in nome for t in [
        "preço", "preco", "custo", "valor", "faturamento", "venda",
        "receita", "lucro", "ganho", "potencial", "captura", "ticket",
        "despesa", "saldo", "total r$", "r$", "recomendado", "sugerido"
    ]):
        return "moeda"

    if any(t in nome for t in [
        "qtd", "qtde", "quantidade", "unidades", "estoque", "itens",
        "produtos", "skus", "ranking", "posição", "posicao", "arquivos", "registros"
    ]):
        return "inteiro"

    if "score" in nome or "índice" in nome or "indice" in nome:
        return "numero"

    return "texto"


def formatar_dataframe_br(base):
    """
    Formata uma cópia do DataFrame apenas para exibição no padrão brasileiro.
    Não altera a base original usada nos cálculos.
    """

    if not isinstance(base, pd.DataFrame) or base.empty:
        return base

    df_view = base.copy()

    # Nomes mais claros para o usuário final.
    renomear = {
        "Ganho_Potencial": "Potencial de Captura",
        "Ganho_Potencial_Final": "Potencial de Captura Final",
        "Ganho_Potencial_Atualizado": "Potencial de Captura Atualizado",
        "Ganho_Potencial_Simulador": "Potencial de Captura Simulado",
        "Margem_%": "Rentabilidade Atual",
        "Margem_Media": "Rentabilidade Atual",
        "Score_Eirox": "Índice de Oportunidade Eirox",
        "Preco_Atual": "Preço Atual",
        "Preco_Sugerido_Mercado": "Preço Máximo Competitivo",
        "Rede_Preco_Maximo_Competitivo": "Rede Preço Máximo Competitivo",
        "Data_Preco_Maximo_Competitivo": "Data Preço Máximo Competitivo",
        "Menor_Preco": "Menor Preço",
        "Rede_Menor_Preco": "Rede Menor Preço",
        "Data_Menor_Preco": "Data Menor Preço",
        "Preco_Recomendado": "Preço Recomendado",
        "Qtd_Vendida_Mes_Anterior": "Qtd Vendida Mês Anterior"
    }

    df_view = df_view.rename(columns={c: renomear.get(c, c) for c in df_view.columns})

    for coluna in df_view.columns:
        tipo = _eirox_tipo_coluna_br(coluna)

        if tipo == "moeda":
            s_num = pd.to_numeric(df_view[coluna], errors="coerce")
            if s_num.notna().any():
                df_view[coluna] = s_num.apply(moeda_br)

        elif tipo == "percentual":
            s_num = pd.to_numeric(df_view[coluna], errors="coerce")
            if s_num.notna().any():
                df_view[coluna] = s_num.apply(percentual_br)

        elif tipo == "inteiro":
            s_num = pd.to_numeric(df_view[coluna], errors="coerce")
            if s_num.notna().any():
                df_view[coluna] = s_num.apply(inteiro_br)

        elif tipo == "numero":
            s_num = pd.to_numeric(df_view[coluna], errors="coerce")
            if s_num.notna().any():
                df_view[coluna] = s_num.apply(numero_br)

        elif tipo == "data":
            # V1.4.10 — datas visuais no padrão brasileiro sem perder datas > dia 12.
            #
            # O Streamlit passa a tabela por esta função mesmo quando a data já
            # chega pronta como dd/mm/aaaa. O pandas, sem dayfirst=True, podia
            # inferir o primeiro valor (ex.: 08/04/2026) como mês/dia e depois
            # transformar 29/07/2026, 18/07/2026 etc. em NaT. Na tela isso
            # aparecia como None, enquanto o Excel permanecia correto.
            serie_original = df_view[coluna].copy()
            try:
                convertido = pd.to_datetime(
                    serie_original,
                    errors="coerce",
                    dayfirst=True,
                    format="mixed"
                )
            except Exception:
                convertido = pd.to_datetime(
                    serie_original,
                    errors="coerce",
                    dayfirst=True
                )

            # Só substitui os valores que foram realmente reconhecidos como data.
            # Valores textuais legítimos são preservados; vazios continuam vazios.
            formatada = serie_original.astype("object").copy()
            mascara_data = convertido.notna()
            if mascara_data.any():
                formatada.loc[mascara_data] = convertido.loc[mascara_data].dt.strftime("%d/%m/%Y")

            mascara_vazio = serie_original.isna() | (
                serie_original.astype(str).str.strip().str.lower().isin(
                    ["", "none", "nan", "nat", "null", "<na>"]
                )
            )
            formatada.loc[mascara_vazio] = ""
            df_view[coluna] = formatada

    return df_view


def valor_metrica_br(label, valor):
    """Padroniza KPIs no formato brasileiro conforme o tipo do indicador."""

    if isinstance(valor, str):
        return valor

    try:
        nome = str(label).lower()

        if any(t in nome for t in ["preço", "preco", "custo", "valor", "faturamento", "venda", "lucro", "ganho", "potencial", "captura", "ticket", "receita", "despesa", "saldo"]):
            return moeda_br(valor)

        if any(t in nome for t in ["margem", "rentabilidade", "particip", "%", "percent", "taxa"]):
            return percentual_br(valor)

        if any(t in nome for t in ["produtos", "itens", "qtd", "quantidade", "estoque", "arquivos", "registros", "usuários", "usuarios"]):
            return inteiro_br(valor)

        if "score" in nome or "índice" in nome or "indice" in nome:
            return numero_br(valor)

        return numero_br(valor) if isinstance(valor, (int, float, np.integer, np.floating)) else valor

    except Exception:
        return valor



# Compatibilidade Streamlit: algumas versões não aceitam width em st.dataframe.
def _limpar_width_dataframe_kwargs(kwargs):
    try:
        kwargs = _limpar_width_dataframe_kwargs(kwargs)
    except Exception:
        pass
    return kwargs



def eirox_estilo_global_tabela_v1426(df):
    """Visual global V1.4.26: replica o padrão funcional da tabela Geral.

    Opera somente sobre uma cópia visual já formatada. Não altera dados,
    cálculos, filtros, recomendações ou a base usada nas exportações.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df

    def _norm(v):
        return str(v or "").strip().upper()

    def _row_style(row):
        # Aceita os nomes usados nas diferentes telas.
        v = ""
        for c in ["Ação", "Acao", "Recomendação", "Recomendacao", "Status", "Situação", "Situacao"]:
            if c in row.index:
                vv = _norm(row.get(c, ""))
                if vv:
                    v = vv
                    break
        if "SUBIR" in v:
            bg = "rgba(14,84,66,.24)"
        elif "BAIXAR" in v:
            bg = "rgba(119,37,54,.22)"
        elif "NEGOCIAR" in v:
            bg = "rgba(112,83,24,.22)"
        elif "MANTER" in v or "COMPETITIVO" in v:
            bg = "rgba(25,65,101,.20)"
        else:
            bg = "rgba(8,30,43,.55)"
        return [f"background-color:{bg};" for _ in row.index]

    def _status(v):
        t = _norm(v)
        if "SUBIR" in t or "PREÇO CALCULADO" in t or "PRECO CALCULADO" in t:
            return "background-color:#0f4d3d;color:#5dffc2;font-weight:850;"
        if "BAIXAR" in t or "BLOQUE" in t or "SEM BASE" in t:
            return "background-color:#51202f;color:#ff94aa;font-weight:850;"
        if "NEGOCIAR" in t or "ATEN" in t or "SEM CUSTO" in t:
            return "background-color:#4a3a18;color:#ffd66d;font-weight:850;"
        if "MANTER" in t or "COMPETITIVO" in t:
            return "background-color:#173b5e;color:#93d2ff;font-weight:850;"
        return ""

    def _pct(v):
        try:
            t=str(v).replace('%','').replace('.','').replace(',','.').strip()
            n=float(t)
            if n >= 20:
                return "background-color:#123b31;color:#76e8bd;font-weight:800;"
            if n >= 10:
                return "background-color:#443719;color:#ffd36b;font-weight:800;"
            return "background-color:#48212b;color:#ff91a6;font-weight:800;"
        except Exception:
            return ""

    styler = df.style.apply(_row_style, axis=1)

    # Status/ação em todas as nomenclaturas encontradas no projeto.
    for c in df.columns:
        n = str(c).lower()
        if any(k in n for k in ["ação","acao","recomend","status","situação","situacao","flag preço","flag preco"]):
            try:
                styler = styler.map(_status, subset=[c])
            except Exception:
                pass

    # Preços e valores de referência = azul como na tela Geral.
    blue=[]
    green=[]
    for c in df.columns:
        n=str(c).lower()
        if any(k in n for k in ["preço","preco"]):
            # Colunas descritivas ligadas a preço não recebem fundo monetário.
            if any(k in n for k in ["loja","rede","farm","data"]):
                continue
            if any(k in n for k in ["sugerido","recomendado"]):
                green.append(c)
            else:
                blue.append(c)
    if blue:
        styler = styler.set_properties(subset=blue, **{
            "background-color":"#123556", "color":"#9fd3ff", "font-weight":"750"
        })
    if green:
        styler = styler.set_properties(subset=green, **{
            "background-color":"#123b31", "color":"#7ce9c0", "font-weight":"850"
        })

    # Margens/percentuais = semáforo.
    for c in df.columns:
        n=str(c).lower()
        if "margem" in n or "%" in str(c):
            try:
                styler = styler.map(_pct, subset=[c])
            except Exception:
                pass

    # Ganho/impacto/potencial positivo = verde.
    gain_cols=[c for c in df.columns if any(k in str(c).lower() for k in ["ganho","impacto","potencial"])]
    if gain_cols:
        styler = styler.set_properties(subset=gain_cols, **{
            "background-color":"#123b31", "color":"#76e8bd", "font-weight":"800"
        })

    # Loja/data = azul-marinho neutro para leitura.
    ref_cols=[c for c in df.columns if any(k in str(c).lower() for k in ["loja do menor","data da pesquisa","data pesquisa","data_pesquisa"])]
    if ref_cols:
        styler = styler.set_properties(subset=ref_cols, **{
            "background-color":"#0c243c", "color":"#d5e8fa"
        })

    styler = styler.set_table_styles([
        {"selector":"th","props":[
            ("background-color","#102b49"),("color","#dcecff"),
            ("font-weight","800"),("border-bottom","1px solid #35526e")
        ]},
        {"selector":"td","props":[("border-color","#27445e")]},
    ], overwrite=False)
    return styler


def aplicar_formatacao_brasileira_streamlit():
    """

qtd_arquivos_pesquisa = quantidade_pesquisas_card(historico, df_filtrado)
    Intercepta st.dataframe e st.metric para exibir números, dinheiro,
    percentuais e datas no padrão brasileiro em todo o dashboard.
    """

    if getattr(st, "_eirox_formatacao_br_aplicada", False):
        return

    st._eirox_dataframe_original = st.dataframe
    st._eirox_metric_original = st.metric

    def dataframe_br(data=None, *args, **kwargs):
        """Renderiza toda tabela do projeto e garante a exportação Excel padrão."""
        kwargs.pop("width", None)
        kwargs["use_container_width"] = True

        # Guarda a base ORIGINAL para exportar a informação completa, sem limitar
        # às linhas do FASTLOAD e sem transformar números/datas em texto visual.
        base_exportacao = data.copy() if isinstance(data, pd.DataFrame) else data
        data_visual = data

        try:
            if isinstance(data_visual, pd.DataFrame):
                aviso_fastload_tabela(data_visual)
                data_visual = dataframe_tela_fastload(data_visual)
                data_visual = formatar_dataframe_br(data_visual)
                # V1.4.26 — estilo funcional aplicado diretamente no interceptor global.
                # A função já existe neste ponto da execução, evitando depender
                # de funções declaradas milhares de linhas abaixo.
                data_visual = eirox_estilo_global_tabela_v1426(data_visual)
        except Exception:
            pass

        resultado = st._eirox_dataframe_original(data_visual, *args, **kwargs)

        # V1.4.22 — padrão universal: toda tabela informativa recebe o mesmo Excel.
        # Algumas tabelas que já possuem um bloco de exportação próprio podem
        # suprimir somente este botão automático durante a renderização.
        try:
            if (
                isinstance(base_exportacao, pd.DataFrame)
                and not base_exportacao.empty
                and not bool(globals().get("_eirox_suprimir_export_auto_st", False))
            ):
                _eirox_exportar_excel_automatico(base_exportacao)
        except Exception:
            pass

        return resultado

    def metric_br(label, value, delta=None, *args, **kwargs):
        try:
            value = valor_metrica_br(label, value)
            if delta is not None and not isinstance(delta, str):
                delta = valor_metrica_br(label, delta)
        except Exception:
            pass
        return st._eirox_metric_original(label, value, delta, *args, **kwargs)

    st.dataframe = dataframe_br
    st.metric = metric_br
    st._eirox_formatacao_br_aplicada = True


aplicar_formatacao_brasileira_streamlit()



def explicacao_calculo(titulo, itens):
    """
    Exibe, no painel, a explicação visual dos cálculos usados em cada visão.
    Mantém a regra de negócio transparente para o usuário final.
    """

    try:
        if not isinstance(itens, (list, tuple)):
            itens = [str(itens)]

        lista_html = "".join(
            f"<li>{str(item)}</li>"
            for item in itens
            if str(item).strip()
        )

        st.markdown(
            f"""
            <div class="eirox-card">
                <div class="eirox-section-title">Como calcular</div>
                <h4 style="margin-top:0;color:#F6FAFF!important;">{titulo}</h4>
                <ul style="margin-bottom:0;color:#BFD7FF;line-height:1.55;">
                    {lista_html}
                </ul>
            """,
            unsafe_allow_html=True
        )
    except Exception:
        pass



