# LEITURA COMPATÍVEL DE EXCEL / CSV
# --------------------------------------------------

def carregar_pasta_excel_compat(pastas, nome_base="base"):

    bases = []

    for pasta_nome in pastas:

        pasta = Path(pasta_nome)

        if not pasta.exists() or not pasta.is_dir():
            continue

        arquivos = []

        for ext in [
            "*.xls",
            "*.xlsx",
            "*.xlsm",
            "*.csv"
        ]:
            arquivos.extend(list(pasta.glob(ext)))

        for arquivo in sorted(arquivos):

            try:

                if arquivo.suffix.lower() == ".csv":

                    try:
                        temp = pd.read_csv(
                            arquivo,
                            sep=";",
                            encoding="utf-8-sig"
                        )
                    except Exception:
                        temp = pd.read_csv(
                            arquivo,
                            encoding="utf-8-sig"
                        )

                else:

                    temp = pd.read_excel(
                        arquivo
                    )

                if not temp.empty:

                    temp["Arquivo_Origem"] = arquivo.name
                    temp["Fonte_Carregamento"] = str(pasta)
                    bases.append(temp)

            except Exception as erro:

                print(
                    f"Falha ao ler {nome_base} / {arquivo}: {erro}"
                )

    if bases:

        base = pd.concat(
            bases,
            ignore_index=True
        )

        base.columns = (
            base.columns
            .astype(str)
            .str.strip()
        )

        return base

    return pd.DataFrame()


