def _cluster2_coluna(base, exatos, contem):
    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return None

        for alvo in exatos:
            for col in base.columns:
                if str(col).strip().lower() == str(alvo).strip().lower():
                    return col

        for termo in contem:
            termo = str(termo).lower()
            for col in base.columns:
                if termo in str(col).lower():
                    return col

        return None
    except Exception:
        return None


def _cluster2_distancia_km(lat_ref, lon_ref, lat, lon):
    try:
        raio = 6371.0
        lat_ref = np.radians(float(lat_ref))
        lon_ref = np.radians(float(lon_ref))
        lat = np.radians(pd.to_numeric(lat, errors="coerce"))
        lon = np.radians(pd.to_numeric(lon, errors="coerce"))

        dlat = lat - lat_ref
        dlon = lon - lon_ref

        a = (
            np.sin(dlat / 2) ** 2
            + np.cos(lat_ref) * np.cos(lat) * np.sin(dlon / 2) ** 2
        )

        return raio * 2 * np.arcsin(np.sqrt(a))
    except Exception:
        return np.nan


def _cluster2_preparar_base(base):
    """
    Prepara o cluster preservando a identidade do cliente.

    CNPJs vinculados ao cliente em contexto = Principal.
    Todos os demais = Concorrente.
    """
    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return pd.DataFrame()

        base = base.copy()
        base.columns = base.columns.astype(str).str.strip()

        # Aplica primeiro a regra oficial do cliente/grupo.
        try:
            base = eirox_aplicar_cliente_contexto_global(base)
        except Exception:
            pass

        c_lat = _cluster2_coluna(
            base,
            ["Latitude", "Lat", "latitude", "lat"],
            ["latitude", "lat"]
        )
        c_lon = _cluster2_coluna(
            base,
            ["Longitude", "Lon", "Lng", "longitude", "lon", "lng"],
            ["longitude", "lon", "lng"]
        )
        c_preco = _cluster2_coluna(
            base,
            ["Preço (R$)", "Preco (R$)", "Preço", "Preco", "Preço Atual", "Preco_Atual"],
            ["preço", "preco", "valor"]
        )

        if not c_lat or not c_lon or not c_preco:
            return pd.DataFrame()

        c_ean = _cluster2_coluna(
            base,
            ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"],
            ["ean", "gtin", "barras"]
        )
        c_produto = _cluster2_coluna(
            base,
            ["Produto", "Descrição", "Descricao", "Termo Pesquisado", "Descricao_Unica"],
            ["produto", "descr", "termo"]
        )
        c_rede = _cluster2_coluna(
            base,
            ["Rede", "Rede Concorrente", "Bandeira", "Grupo", "Concorrente"],
            ["rede", "bandeira", "grupo", "concorr"]
        )
        c_loja = _cluster2_coluna(
            base,
            ["Farmácia", "Farmacia", "Loja", "Estabelecimento", "Razão Social", "Razao Social"],
            ["farm", "loja", "estabelec", "razão", "razao", "social"]
        )
        c_cnpj = _cluster2_coluna(
            base,
            ["CNPJ", "CPF/CNPJ", "CNPJ Loja", "CNPJ_Loja", "CNPJ Estabelecimento"],
            ["cnpj"]
        )
        c_data = _cluster2_coluna(
            base,
            ["Data", "Data Emissão", "Data_Emissao", "Data Pesquisa", "Data da Pesquisa", "Dt Pesquisa"],
            ["data", "emissao", "emissão", "dt"]
        )

        out = pd.DataFrame(index=base.index)
        out["Latitude"] = pd.to_numeric(base[c_lat], errors="coerce")
        out["Longitude"] = pd.to_numeric(base[c_lon], errors="coerce")
        out["Preço"] = (
            converter_numero_brasil(base[c_preco])
            if "converter_numero_brasil" in globals()
            else pd.to_numeric(base[c_preco], errors="coerce")
        )

        out["EAN"] = (
            base[c_ean]
            .astype(str)
            .str.replace(".0", "", regex=False)
            .str.replace(r"\D", "", regex=True)
            .str.strip()
            if c_ean else ""
        )

        out["Produto"] = base[c_produto].astype(str) if c_produto else ""

        if "serie_nome_rede_eirox" in globals():
            out["Rede"] = serie_nome_rede_eirox(base, c_rede, c_loja)
        else:
            out["Rede"] = base[c_rede].astype(str) if c_rede else ""

        out["Loja"] = base[c_loja].astype(str) if c_loja else out["Rede"]
        out["CNPJ"] = base[c_cnpj].astype(str) if c_cnpj else ""
        out["Data"] = base[c_data] if c_data else ""

        # Herda a classificação oficial já calculada na base original.
        if "Tipo_Estabelecimento" in base.columns:
            out["Tipo_Estabelecimento"] = (
                base["Tipo_Estabelecimento"]
                .fillna("Concorrente")
                .astype(str)
            )
        else:
            # Fallback formal por CNPJ.
            try:
                cnpjs_cliente = eirox_cnpjs_cliente_global()
                if c_cnpj and cnpjs_cliente:
                    normalizados = base[c_cnpj].apply(eirox_norm_cnpj_global)
                    out["Tipo_Estabelecimento"] = np.where(
                        normalizados.isin(cnpjs_cliente),
                        "Principal",
                        "Concorrente"
                    )
                else:
                    out["Tipo_Estabelecimento"] = "Concorrente"
            except Exception:
                out["Tipo_Estabelecimento"] = "Concorrente"

        # Rede dos registros principais deve sempre ser o grupo/cliente em contexto.
        try:
            _, nome_cliente = eirox_cliente_contexto_global()
            if nome_cliente:
                mask_principal = out["Tipo_Estabelecimento"].eq("Principal")
                out.loc[mask_principal, "Rede"] = nome_cliente
        except Exception:
            pass

        out = out.dropna(subset=["Latitude", "Longitude", "Preço"])
        out = out[
            (out["Preço"] > 0)
            & (out["Preço"] <= 5000)
        ].copy()

        return out

    except Exception:
        return pd.DataFrame()



def _cluster2_escolher_preco_por_custo(precos_concorrencia, custo):
    """
    Regra:
    - Tenta seguir o menor preço da concorrência.
    - Se o menor preço não cobrir o custo, tenta o segundo menor.
    - Segue para o próximo preço até encontrar um preço acima do custo.
    - Se nenhum preço cobrir o custo, sinaliza revisão.
    """

    try:
        precos = pd.to_numeric(pd.Series(precos_concorrencia), errors="coerce").dropna()
        precos = sorted(set([float(p) for p in precos if p > 0]))

        if not precos:
            return np.nan, "Sem preço concorrente válido", "Revisar pesquisa"

        try:
            custo = float(custo)
        except Exception:
            custo = np.nan

        if pd.isna(custo) or custo <= 0:
            return precos[0], "Sem custo informado: usando menor preço concorrente", "Cadastrar custo para validar margem"

        for idx, preco in enumerate(precos):
            if preco > custo:
                if idx == 0:
                    return preco, "Seguir menor preço concorrente", "Pode acompanhar o menor preço"
                if idx == 1:
                    return preco, "Menor preço não cobre custo: usar 2º menor preço", "Não acompanhar menor preço; usar 2º menor"
                return preco, f"Preços anteriores não cobrem custo: usar {idx + 1}º menor preço", f"Não acompanhar preços abaixo do custo; usar {idx + 1}º menor"

        return precos[-1], "Nenhum preço concorrente cobre o custo", "Não acompanhar concorrência; revisar custo/margem"

    except Exception:
        return np.nan, "Erro ao aplicar regra de custo", "Revisar dados"


def _cluster2_calcular_sugestoes(base_cluster, loja_ref, raio_km=2.0):
    try:
        if not isinstance(base_cluster, pd.DataFrame) or base_cluster.empty:
            return pd.DataFrame(), pd.DataFrame()

        base = base_cluster.copy()

        lat_ref = float(loja_ref["Latitude"])
        lon_ref = float(loja_ref["Longitude"])
        loja_nome = str(loja_ref["Loja"]).strip()

        base["Distância KM"] = _cluster2_distancia_km(
            lat_ref,
            lon_ref,
            base["Latitude"],
            base["Longitude"]
        )

        pontos_raio = base[
            (base["Distância KM"] <= float(raio_km))
            & (base["Distância KM"] >= 0)
        ].copy()

        if pontos_raio.empty:
            return pd.DataFrame(), pd.DataFrame()

        # A loja escolhida serve como ponto geográfico de referência,
        # mas a classificação Principal x Concorrente vem do CLIENTE/GRUPO.
        if "Tipo_Estabelecimento" in pontos_raio.columns:
            principal = pontos_raio[
                pontos_raio["Tipo_Estabelecimento"].astype(str).eq("Principal")
            ].copy()

            concorrentes = pontos_raio[
                ~pontos_raio["Tipo_Estabelecimento"].astype(str).eq("Principal")
            ].copy()
        else:
            # Fallback antigo somente se a classificação formal não existir.
            principal = pontos_raio[
                pontos_raio["Loja"].astype(str).str.strip().eq(loja_nome)
            ].copy()

            concorrentes = pontos_raio[
                ~pontos_raio["Loja"].astype(str).str.strip().eq(loja_nome)
            ].copy()

        # Para o preço atual principal, prioriza especificamente a loja escolhida
        # dentro do grupo do cliente.
        principal_loja_ref = principal[
            principal["Loja"].astype(str).str.strip().eq(loja_nome)
        ].copy()

        if principal_loja_ref.empty:
            principal_loja_ref = principal.copy()

        if concorrentes.empty:
            return pd.DataFrame(), pontos_raio

        sugestao = (
            concorrentes
            .groupby("EAN", dropna=False)
            .agg(
                Produto=("Produto", lambda x: x.mode().iloc[0] if not x.mode().empty else x.iloc[0]),
                Menor_Preço_Concorrente_2KM=("Preço", "min"),
                Preço_Médio_Concorrente_2KM=("Preço", "mean"),
                Preço_Máximo_Competitivo_2KM=("Preço", lambda s: float(pd.to_numeric(s, errors="coerce").quantile(0.75))),
                Concorrentes_2KM=("Loja", "nunique"),
                Redes_Concorrentes_2KM=("Rede", lambda x: ", ".join(sorted(set([str(v) for v in x if str(v).strip()]))[:8])),
                Distância_Mínima_KM=("Distância KM", "min")
            )
            .reset_index()
        )

        if not principal_loja_ref.empty:
            atual = (
                principal_loja_ref
                .groupby("EAN", dropna=False)
                .agg(Preço_Atual_Principal=("Preço", "mean"))
                .reset_index()
            )

            sugestao = sugestao.merge(atual, on="EAN", how="left")
        else:
            sugestao["Preço_Atual_Principal"] = np.nan

        sugestao["Preço_Sugerido_Cluster_2KM"] = sugestao["Preço_Máximo_Competitivo_2KM"]
        sugestao["Ganho_Unitário_Cluster_2KM"] = sugestao["Preço_Sugerido_Cluster_2KM"] - sugestao["Preço_Atual_Principal"]
        sugestao["Diferença_%_Cluster_2KM"] = (
            sugestao["Ganho_Unitário_Cluster_2KM"]
            / sugestao["Preço_Atual_Principal"].replace(0, np.nan)
        ) * 100

        sugestao["Recomendação_Cluster_2KM"] = np.select(
            [
                sugestao["Ganho_Unitário_Cluster_2KM"] > 0.05,
                sugestao["Ganho_Unitário_Cluster_2KM"] < -0.05
            ],
            [
                "SUBIR PREÇO",
                "BAIXAR PREÇO"
            ],
            default="MANTER"
        )

        # Custo e margem seguindo menor preço do cluster, quando o custo existir na base principal.
        custo_base = globals().get("df", pd.DataFrame())
        sugestao["Custo"] = np.nan

        if isinstance(custo_base, pd.DataFrame) and not custo_base.empty and "EAN" in custo_base.columns:
            c_custo = _cluster2_coluna(custo_base, ["Custo", "Custo Médio", "Custo_Medio", "Custo Atual"], ["custo"])

            if c_custo:
                custos = custo_base[["EAN", c_custo]].copy()
                custos["EAN"] = custos["EAN"].astype(str).str.replace(".0", "", regex=False).str.strip()
                custos["Custo"] = converter_numero_brasil(custos[c_custo]) if "converter_numero_brasil" in globals() else pd.to_numeric(custos[c_custo], errors="coerce")
                custos = custos.groupby("EAN", as_index=False)["Custo"].mean()
                sugestao = sugestao.drop(columns=["Custo"]).merge(custos, on="EAN", how="left")

        sugestao["Margem_%_Menor_Preço_2KM"] = (
            (sugestao["Menor_Preço_Concorrente_2KM"] - sugestao["Custo"])
            / sugestao["Menor_Preço_Concorrente_2KM"].replace(0, np.nan)
        ) * 100

        sugestao["Valor_Margem_Menor_Preço_2KM"] = sugestao["Menor_Preço_Concorrente_2KM"] - sugestao["Custo"]

        # Regra oficial do cluster:
        # seguir o menor preço concorrente somente se cobrir o custo.
        # Caso contrário, usar o segundo menor, terceiro menor e assim sucessivamente.
        precos_por_ean = (
            concorrentes
            .groupby("EAN")["Preço"]
            .apply(lambda s: sorted(set(pd.to_numeric(s, errors="coerce").dropna().astype(float).tolist())))
            .to_dict()
        )

        regras_aplicadas = []
        acoes_recomendadas = []
        precos_regra = []

        for _, linha in sugestao.iterrows():
            ean_linha = linha.get("EAN", "")
            custo_linha = linha.get("Custo", np.nan)
            preco_regra, regra, acao = _cluster2_escolher_preco_por_custo(
                precos_por_ean.get(ean_linha, []),
                custo_linha
            )
            precos_regra.append(preco_regra)
            regras_aplicadas.append(regra)
            acoes_recomendadas.append(acao)

        sugestao["Preço_Sugerido_Regra_Custo_2KM"] = precos_regra
        sugestao["Regra_Aplicada_Cluster_2KM"] = regras_aplicadas
        sugestao["Ação_Necessária_Cluster_2KM"] = acoes_recomendadas

        # O preço sugerido final passa a respeitar a regra de custo.
        sugestao["Preço_Sugerido_Cluster_2KM"] = sugestao["Preço_Sugerido_Regra_Custo_2KM"]
        sugestao["Ganho_Unitário_Cluster_2KM"] = sugestao["Preço_Sugerido_Cluster_2KM"] - sugestao["Preço_Atual_Principal"]
        sugestao["Diferença_%_Cluster_2KM"] = (
            sugestao["Ganho_Unitário_Cluster_2KM"]
            / sugestao["Preço_Atual_Principal"].replace(0, np.nan)
        ) * 100

        sugestao["Margem_%_Preço_Sugerido_2KM"] = (
            (sugestao["Preço_Sugerido_Cluster_2KM"] - sugestao["Custo"])
            / sugestao["Preço_Sugerido_Cluster_2KM"].replace(0, np.nan)
        ) * 100

        sugestao["Valor_Margem_Preço_Sugerido_2KM"] = (
            sugestao["Preço_Sugerido_Cluster_2KM"] - sugestao["Custo"]
        )

        sugestao["Recomendação_Cluster_2KM"] = np.select(
            [
                sugestao["Ação_Necessária_Cluster_2KM"].astype(str).str.contains("Não acompanhar concorrência", case=False, na=False),
                sugestao["Ganho_Unitário_Cluster_2KM"] > 0.05,
                sugestao["Ganho_Unitário_Cluster_2KM"] < -0.05
            ],
            [
                "REVISAR CUSTO/MARGEM",
                "SUBIR PREÇO",
                "BAIXAR PREÇO"
            ],
            default="MANTER"
        )

        for col in [
            "Menor_Preço_Concorrente_2KM",
            "Preço_Médio_Concorrente_2KM",
            "Preço_Máximo_Competitivo_2KM",
            "Preço_Atual_Principal",
            "Preço_Sugerido_Cluster_2KM",
            "Ganho_Unitário_Cluster_2KM",
            "Diferença_%_Cluster_2KM",
            "Distância_Mínima_KM",
            "Custo",
            "Margem_%_Menor_Preço_2KM",
            "Valor_Margem_Menor_Preço_2KM",
            "Preço_Sugerido_Regra_Custo_2KM",
            "Margem_%_Preço_Sugerido_2KM",
            "Valor_Margem_Preço_Sugerido_2KM"
        ]:
            if col in sugestao.columns:
                sugestao[col] = pd.to_numeric(sugestao[col], errors="coerce").round(2)

        ordem = {"SUBIR PREÇO": 1, "BAIXAR PREÇO": 2, "MANTER": 3}
        sugestao["_ordem"] = sugestao["Recomendação_Cluster_2KM"].map(ordem).fillna(9)
        sugestao = sugestao.sort_values(["_ordem", "Ganho_Unitário_Cluster_2KM"], ascending=[True, False]).drop(columns=["_ordem"])

        return sugestao, pontos_raio

    except Exception as erro:
        st.error(f"Erro ao calcular sugestão do cluster 2 km: {erro}")
        return pd.DataFrame(), pd.DataFrame()



def formatar_valores_cluster_2km_para_exibicao(base):
    """
    Corrige formatação da tabela do cluster:
    colunas de valor/margem nominal devem aparecer em R$, não em %.
    """

    try:
        if not isinstance(base, pd.DataFrame) or base.empty:
            return base

        base = base.copy()

        colunas_moeda = [
            "Valor_Margem_Preço_Sugerido_2KM",
            "Valor_Margem_Menor_Preço_2KM",
            "Margem_Nominal_Preço_Sugerido_2KM",
            "Margem_Nominal_Menor_Preço_2KM",
            "Ganho_Unitário_Cluster_2KM",
            "Preço_Sugerido_Cluster_2KM",
            "Preço_Sugerido_Regra_Custo_2KM",
            "Preço_Atual_Principal",
            "Menor_Preço_Concorrente_2KM",
            "Preço_Médio_Concorrente_2KM",
            "Preço_Máximo_Competitivo_2KM",
            "Custo"
        ]

        colunas_percentual = [
            "Margem_%_Preço_Sugerido_2KM",
            "Margem_%_Menor_Preço_2KM",
            "Diferença_%_Cluster_2KM"
        ]

        for col in colunas_moeda:
            if col in base.columns:
                base[col] = pd.to_numeric(base[col], errors="coerce").apply(moeda_br)

        for col in colunas_percentual:
            if col in base.columns:
                base[col] = pd.to_numeric(base[col], errors="coerce").apply(percentual_br)

        return base

    except Exception:
        return base


def renderizar_cluster_2km_mapa(mapa_filtrado_base):
    try:
        st.markdown("---")
        st.markdown("### 🎯 Cluster da loja selecionada — raio de concorrência")

        base_cluster = _cluster2_preparar_base(mapa_filtrado_base)

        if base_cluster.empty:
            st.warning("Não foi possível montar o cluster. A base precisa ter loja, latitude, longitude e preço.")
            return

        lojas = (
            base_cluster
            .groupby(
                ["Rede", "Loja", "Tipo_Estabelecimento"],
                dropna=False
            )
            .agg(
                Latitude=("Latitude", "median"),
                Longitude=("Longitude", "median"),
                Produtos=("EAN", "nunique"),
                Preço_Médio=("Preço", "mean")
            )
            .reset_index()
        )

        # Somente lojas/CNPJs do grupo do usuário podem ser escolhidos como Principal.
        lojas_principais = lojas[
            lojas["Tipo_Estabelecimento"].astype(str).eq("Principal")
        ].copy()

        if lojas_principais.empty:
            st.warning(
                "Nenhuma loja do cliente em contexto foi identificada nas pesquisas. "
                "Revise os CNPJs vinculados ao cliente."
            )
            return

        _, _nome_cliente_cluster = eirox_cliente_contexto_global()

        lojas_principais["Seleção"] = (
            lojas_principais["Rede"].astype(str)
            + " - "
            + lojas_principais["Loja"].astype(str)
        )

        c1, c2, c3 = st.columns([2.2, 0.8, 1])

        loja_sel = c1.selectbox(
            "Loja principal",
            sorted(
                lojas_principais["Seleção"]
                .dropna()
                .astype(str)
                .tolist()
            ),
            index=0,
            help=(
                f"Somente lojas do cliente {_nome_cliente_cluster} podem ser Principal. "
                "Todos os demais CNPJs são concorrentes."
            ),
            key="cluster_loja_principal_cliente"
        )

        raio_km = c2.number_input(
            "Raio KM",
            min_value=0.5,
            max_value=10.0,
            value=2.0,
            step=0.5
        )

        filtro_rec = c3.selectbox(
            "Recomendação",
            ["Todas", "SUBIR PREÇO", "BAIXAR PREÇO", "MANTER"],
            key="cluster_2km_filtro_recomendacao"
        )

        loja_ref = lojas_principais[
            lojas_principais["Seleção"].astype(str).eq(str(loja_sel))
        ].iloc[0].to_dict()

        sugestao, pontos_raio = _cluster2_calcular_sugestoes(
            base_cluster,
            loja_ref,
            raio_km=raio_km
        )

        if pontos_raio.empty:
            st.info("Nenhuma farmácia encontrada dentro do raio selecionado.")
            return

        if not sugestao.empty and filtro_rec != "Todas":
            sugestao = sugestao[sugestao["Recomendação_Cluster_2KM"].astype(str).eq(filtro_rec)].copy()

        k1, k2, k3, k4 = st.columns(4)
        k1.metric("Lojas no raio", int(pontos_raio["Loja"].nunique()))
        k2.metric("Redes no raio", int(pontos_raio["Rede"].nunique()))
        k3.metric("Produtos sugeridos", int(sugestao["EAN"].nunique()) if not sugestao.empty else 0)
        k4.metric("Raio aplicado", f"{raio_km:.1f} km")

        st.markdown("#### 📋 Sugestão de ajuste de preço considerando concorrentes próximos")

        if sugestao.empty:
            st.info("Existem lojas no raio, mas não há produtos comparáveis suficientes para gerar sugestão.")
        else:
            colunas = [
                "EAN",
                "Produto",
                "Preço_Atual_Principal",
                "Menor_Preço_Concorrente_2KM",
                "Preço_Médio_Concorrente_2KM",
                "Preço_Máximo_Competitivo_2KM",
                "Preço_Sugerido_Cluster_2KM",
                "Ação_Necessária_Cluster_2KM",
                "Margem_%_Preço_Sugerido_2KM",
                "Valor_Margem_Preço_Sugerido_2KM",
                "Ganho_Unitário_Cluster_2KM",
                "Diferença_%_Cluster_2KM",
                "Recomendação_Cluster_2KM",
                "Concorrentes_2KM",
                "Redes_Concorrentes_2KM",
                "Distância_Mínima_KM",
                "Custo",
                "Margem_%_Menor_Preço_2KM",
                "Valor_Margem_Menor_Preço_2KM"
            ]

            colunas = [c for c in colunas if c in sugestao.columns]

            sugestao_exibir = formatar_valores_cluster_2km_para_exibicao(sugestao[colunas])

            eirox_dataframe_brl(
                sugestao_exibir,
                use_container_width=True,
                hide_index=True,
                height=420
            )

            st.download_button(
                "📥 Exportar sugestão cluster 2 km",
                data=sugestao.to_csv(index=False, sep=";", encoding="utf-8-sig"),
                file_name="sugestao_cluster_2km.csv",
                mime="text/csv",
                use_container_width=True
            )
            eirox_botao_excel_padrao(
                sugestao,
                "Sugestão Cluster 2 km",
                "sugestao_cluster_2km.xlsx",
                key="excel_cluster_2km",
                use_container_width=True
            )

        st.markdown("#### 🗺️ Seleção no mapa")

        pontos_mapa = pontos_raio.copy()
        loja_nome = str(loja_ref.get("Loja", "")).strip()

        if "Tipo_Estabelecimento" in pontos_mapa.columns:
            pontos_mapa["Tipo"] = np.where(
                pontos_mapa["Loja"].astype(str).str.strip().eq(loja_nome),
                "Loja principal",
                np.where(
                    pontos_mapa["Tipo_Estabelecimento"].astype(str).eq("Principal"),
                    "Outra loja do cliente",
                    "Concorrente no raio"
                )
            )
        else:
            pontos_mapa["Tipo"] = np.where(
                pontos_mapa["Loja"].astype(str).str.strip().eq(loja_nome),
                "Loja principal",
                "Concorrente no raio"
            )

        centro = {
            "lat": float(pd.to_numeric(pontos_mapa["Latitude"], errors="coerce").median()),
            "lon": float(pd.to_numeric(pontos_mapa["Longitude"], errors="coerce").median())
        }

        # V73 — mapa no padrão visual oficial da referência
        # Mantém exatamente as regras já calculadas em pontos_mapa:
        # Loja principal / Outra loja do cliente / Concorrente no raio.
        pontos_mapa["Rotulo_Loja"] = (
            pontos_mapa["Loja"]
            .fillna("")
            .astype(str)
            .str.strip()
        )

        # Cores fixas conforme identidade visual.
        cores_tipo = {
            "Loja principal": "#19C8F5",
            "Outra loja do cliente": "#19C8F5",
            "Concorrente no raio": "#F04B43",
        }

        fig_cluster = px.scatter_mapbox(
            pontos_mapa,
            lat="Latitude",
            lon="Longitude",
            color="Tipo",
            text="Rotulo_Loja",
            color_discrete_map=cores_tipo,
            hover_name="Loja",
            hover_data={
                "Rede": True,
                "Produto": True,
                "Preço": ":.2f",
                "Distância KM": ":.2f",
                "Data": True,
                "Latitude": False,
                "Longitude": False,
                "Rotulo_Loja": False,
            },
            center=centro,
            zoom=15,
            height=620,
            title=f"Cluster local: {loja_sel} | raio {raio_km:.1f} km"
        )

        # Rótulos permanentes + tamanho diferenciado por tipo.
        for _trace in fig_cluster.data:
            _nome = str(getattr(_trace, "name", ""))

            _trace.mode = "markers+text"
            _trace.textposition = "top right"
            _trace.textfont = dict(size=10, color="#F4F7FB")

            if _nome in ("Loja principal", "Outra loja do cliente"):
                _trace.marker.update(
                    size=17 if _nome == "Loja principal" else 13,
                    opacity=1.0,
                    color="#19C8F5"
                )
            else:
                _trace.marker.update(
                    size=10,
                    opacity=0.92,
                    color="#F04B43"
                )

        fig_cluster.update_layout(
            mapbox_style="carto-darkmatter",
            paper_bgcolor="#06111f",
            plot_bgcolor="#06111f",
            font=dict(color="#EAF2FF"),
            margin=dict(l=4, r=4, t=46, b=4),
            legend=dict(
                title=None,
                orientation="h",
                yanchor="bottom",
                y=1.01,
                xanchor="left",
                x=0,
                bgcolor="rgba(0,0,0,0)",
                font=dict(size=11, color="#EAF2FF"),
            ),
        )

        st.plotly_chart(fig_cluster, use_container_width=True)

    except Exception as erro:
        st.error(f"Erro ao renderizar cluster 2 km: {erro}")


