def eirox_v66_curva_ia_por_ean(motor):
    """
    Recupera CURVA da fonte oficial do projeto por EAN.

    Prioridade:
    1. coluna de curva já presente no dataframe/motor;
    2. COMPRA_TESTE (global compra), onde a BASE DE COMPRA possui CURVA;
    3. ESTOQUE_TESTE (global estoque), se também houver curva.

    Não cria classificação artificial.
    """
    if not isinstance(motor, pd.DataFrame) or motor.empty:
        return pd.Series(dtype=object)

    idx = motor.index

    def _norm_ean_ia(v):
        try:
            s = re.sub(r"\D", "", str(v))
            if not s:
                return ""
            return s
        except Exception:
            return ""

    def _texto_curva(v):
        try:
            if pd.isna(v):
                return ""
            s = str(v).strip()
            if s.lower() in {"", "nan", "none", "null", "nat", "não informado", "nao informado"}:
                return ""
            return s
        except Exception:
            return ""

    c_ean_motor = _eirox_first_col(
        motor,
        ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras", "codigobarras"]
    )

    if c_ean_motor:
        ean_motor = motor[c_ean_motor].apply(_norm_ean_ia)
    else:
        ean_motor = pd.Series("", index=idx)

    # Curva já existente no dataframe principal.
    c_curva_motor = _eirox_first_col(
        motor,
        [
            "CURVA", "Curva", "curva",
            "Curva ABC", "CURVA ABC", "ABC",
            "Classificação ABC", "Classificacao ABC",
            "Curva Venda", "Curva_Venda"
        ]
    )

    if c_curva_motor:
        curva = motor[c_curva_motor].apply(_texto_curva)
    else:
        curva = pd.Series("", index=idx, dtype=object)

    # Enriquece somente onde ainda está vazio.
    for nome_global in ["compra", "estoque"]:
        faltando = curva.apply(_texto_curva).eq("")
        if not faltando.any():
            break

        aux = globals().get(nome_global, pd.DataFrame())
        if not isinstance(aux, pd.DataFrame) or aux.empty:
            continue

        c_ean_aux = _eirox_first_col(
            aux,
            ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras", "codigobarras", "Cod Barras"]
        )
        c_curva_aux = _eirox_first_col(
            aux,
            [
                "CURVA", "Curva", "curva",
                "Curva ABC", "CURVA ABC", "ABC",
                "Classificação ABC", "Classificacao ABC",
                "Curva Venda", "Curva_Venda"
            ]
        )

        if not c_ean_aux or not c_curva_aux:
            continue

        mapa = aux[[c_ean_aux, c_curva_aux]].copy()
        mapa["_EAN_IA"] = mapa[c_ean_aux].apply(_norm_ean_ia)
        mapa["_CURVA_IA"] = mapa[c_curva_aux].apply(_texto_curva)

        mapa = mapa[
            mapa["_EAN_IA"].ne("")
            & mapa["_CURVA_IA"].ne("")
        ].copy()

        if mapa.empty:
            continue

        # Se houver várias linhas do mesmo EAN, mantém a primeira curva válida.
        mapa = (
            mapa.groupby("_EAN_IA", as_index=False)["_CURVA_IA"]
            .first()
        )
        dic = dict(zip(mapa["_EAN_IA"], mapa["_CURVA_IA"]))

        curva_aux = ean_motor.map(dic).fillna("")
        curva = curva.where(~faltando, curva_aux)

    return curva.apply(lambda v: _texto_curva(v) or "Não informado")





def eirox_v67_curva_abc_venda(motor):
    """
    CURVA ABC OFICIAL PELA VENDA REAL.

    Fonte primária obrigatória:
        venda_rede -> pasta VENDA_FINAL_TESTE

    Regra:
    - A: até 80% do faturamento acumulado
    - B: acima de 80% até 95%
    - C: acima de 95%
    - Sem Venda: somente quando o EAN realmente não possui venda > 0
      na VENDA_FINAL_TESTE carregada.

    Classificação por EAN.
    """
    if not isinstance(motor, pd.DataFrame) or motor.empty:
        return pd.Series(dtype=object)

    def _norm_ean(v):
        try:
            if pd.isna(v):
                return ""
            s = str(v).strip()
            # Evita notação float típica de leitura Excel.
            s = re.sub(r"\.0$", "", s)
            s = re.sub(r"\D", "", s)
            return s
        except Exception:
            return ""

    def _num_br(serie):
        if not isinstance(serie, pd.Series):
            return pd.Series(dtype=float)

        # Tenta primeiro o conversor oficial já existente no projeto.
        try:
            if "converter_numero_brasil" in globals():
                return converter_numero_brasil(serie).fillna(0)
        except Exception:
            pass

        s = serie.astype(str).str.strip()
        tem_virgula = s.str.contains(",", regex=False)

        out = pd.Series(index=serie.index, dtype="float64")
        s_br = (
            s[tem_virgula]
            .str.replace(".", "", regex=False)
            .str.replace(",", ".", regex=False)
        )
        s_us = s[~tem_virgula].str.replace(",", "", regex=False)

        out.loc[s_br.index] = pd.to_numeric(s_br, errors="coerce")
        out.loc[s_us.index] = pd.to_numeric(s_us, errors="coerce")
        return out.fillna(0)

    c_ean_motor = _eirox_first_col(
        motor,
        [
            "EAN", "EAN (GTIN)", "GTIN",
            "Código de Barras", "Codigo de Barras",
            "Cód. Barras/Etiq.", "Cod. Barras/Etiq."
        ]
    )

    if not c_ean_motor:
        return pd.Series("Sem Venda", index=motor.index)

    ean_motor = motor[c_ean_motor].apply(_norm_ean)

    # ---------------------------------------------------------------
    # FONTE CORRETA: venda_rede / VENDA_FINAL_TESTE
    # ---------------------------------------------------------------
    venda_df = globals().get("venda_rede", pd.DataFrame())

    if not isinstance(venda_df, pd.DataFrame) or venda_df.empty:
        # Fallback somente para uma base explicitamente identificada como venda.
        for _nome in ["vendas", "df_vendas", "base_vendas", "venda_base"]:
            _obj = globals().get(_nome, pd.DataFrame())
            if isinstance(_obj, pd.DataFrame) and not _obj.empty:
                venda_df = _obj
                break

    if not isinstance(venda_df, pd.DataFrame) or venda_df.empty:
        return pd.Series("Sem Venda", index=motor.index)

    venda_df = venda_df.copy()
    venda_df.columns = venda_df.columns.astype(str).str.strip()

    c_ean_v = _eirox_first_col(
        venda_df,
        [
            "Cód. Barras/Etiq.", "Cod. Barras/Etiq.",
            "EAN", "EAN (GTIN)", "GTIN",
            "Código de Barras", "Codigo de Barras",
            "codigobarras", "Cod Barras"
        ]
    )

    if not c_ean_v:
        return pd.Series("Sem Venda", index=motor.index)

    # Na VENDA_FINAL_TESTE do projeto, "Venda" é o faturamento total
    # e "Itens" é a quantidade vendida.
    c_valor = _eirox_first_col(
        venda_df,
        [
            "Venda", "Valor Venda", "Valor_Venda",
            "Faturamento", "Valor Total", "Valor_Total",
            "Total Venda", "Total_Venda",
            "Valor Líquido", "Valor Liquido",
            "Receita"
        ]
    )

    c_qtd = _eirox_first_col(
        venda_df,
        [
            "Itens", "Item", "Quantidade", "Qtd", "QTD", "Qtde",
            "Quantidade Vendida", "Qtd Vendida",
            "Quantidade_Vendida", "Venda_Qtd", "Unidades"
        ]
    )

    if c_valor:
        venda_df["_FAT_ABC"] = _num_br(venda_df[c_valor])
    else:
        c_preco = _eirox_first_col(
            venda_df,
            [
                "Preço Venda", "Preco Venda", "Preco_Venda",
                "Preço (R$)", "Preco (R$)",
                "Valor Unitário", "Valor Unitario",
                "Preço Médio", "Preco Medio", "Preco_Medio",
                "Preço", "Preco"
            ]
        )
        if c_qtd and c_preco:
            venda_df["_FAT_ABC"] = (
                _num_br(venda_df[c_qtd])
                * _num_br(venda_df[c_preco])
            )
        else:
            return pd.Series("Sem Venda", index=motor.index)

    venda_df["_EAN_ABC"] = venda_df[c_ean_v].apply(_norm_ean)

    # Considera venda real somente com EAN válido e faturamento positivo.
    venda_df = venda_df[
        venda_df["_EAN_ABC"].ne("")
        & venda_df["_FAT_ABC"].gt(0)
    ].copy()

    if venda_df.empty:
        return pd.Series("Sem Venda", index=motor.index)

    abc = (
        venda_df
        .groupby("_EAN_ABC", as_index=False)["_FAT_ABC"]
        .sum()
        .sort_values("_FAT_ABC", ascending=False, kind="stable")
        .reset_index(drop=True)
    )

    total = float(abc["_FAT_ABC"].sum())
    if total <= 0:
        return pd.Series("Sem Venda", index=motor.index)

    abc["_PERC_ACUM_ABC"] = abc["_FAT_ABC"].cumsum() / total

    abc["CURVA_ABC_VENDA"] = np.select(
        [
            abc["_PERC_ACUM_ABC"] <= 0.80,
            abc["_PERC_ACUM_ABC"] <= 0.95,
        ],
        ["A", "B"],
        default="C"
    )

    mapa_curva = dict(
        zip(
            abc["_EAN_ABC"].astype(str),
            abc["CURVA_ABC_VENDA"].astype(str)
        )
    )

    return ean_motor.map(mapa_curva).fillna("Sem venda no período")


def eirox_v67_metricas_curva_abc_venda(motor):
    curva = eirox_v67_curva_abc_venda(motor)
    if not isinstance(curva, pd.Series) or curva.empty:
        return {"A":0, "B":0, "C":0, "Sem Venda":0}
    vc = curva.value_counts(dropna=False).to_dict()
    return {
        "A": int(vc.get("A", 0)),
        "B": int(vc.get("B", 0)),
        "C": int(vc.get("C", 0)),
        "Sem Venda": int(vc.get("Sem Venda", 0)),
    }



def gerar_ia_pricing_enterprise(margem_minima=25, margem_alvo=35, limite_reducao=8, limite_aumento=12, top_n=150):
    """
    IA Pricing V65
    Usa o MESMO motor central das telas Geral/Subir/Baixar/Negociar.
    Evita campos financeiros zerados por divergência de nomes de colunas.
    """
    try:
        # Prioriza exatamente a base já filtrada por cliente/município da tela.
        base = globals().get("df_filtrado", pd.DataFrame())
        if not isinstance(base, pd.DataFrame) or base.empty:
            base = globals().get("df", pd.DataFrame())
        if not isinstance(base, pd.DataFrame) or base.empty:
            base = globals().get("base_pesquisa", pd.DataFrame())
        if not isinstance(base, pd.DataFrame) or base.empty:
            return pd.DataFrame()

        base = base.copy()

        # Mantém filtro de empresa quando aplicável.
        try:
            if "aplicar_filtro_empresa" in globals():
                base = aplicar_filtro_empresa(base)
        except Exception:
            pass

        # Fonte financeira oficial do projeto.
        motor = eirox_motor_oportunidades(base)
        if not isinstance(motor, pd.DataFrame) or motor.empty:
            return pd.DataFrame()

        empresa_id = empresa_contexto_atual() if "empresa_contexto_atual" in globals() else "1"
        empresa_nome = obter_nome_empresa(empresa_id) if "obter_nome_empresa" in globals() else ""

        c_ean = _eirox_first_col(motor, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras"])
        c_prod = _eirox_first_col(motor, ["Produto", "Produto_Base_SIM", "Descrição", "Descricao", "Produto na Pesquisa"])
        c_lab = _eirox_first_col(motor, ["Laboratório", "Laboratorio", "Fabricante", "Fornecedor"])
        c_cat = _eirox_first_col(motor, ["Categoria", "Família", "Familia", "Departamento", "Classe"])
        c_curva = _eirox_first_col(motor, ["CURVA", "Curva", "ABC", "Curva ABC"])
        c_estoque = _eirox_first_col(motor, ["Estoque", "Estoque Atual", "Qtde Estoque", "Quantidade Estoque", "Qtd Estoque"])

        preco = pd.to_numeric(motor["Preço_Atual_Eirox"], errors="coerce")
        custo = pd.to_numeric(motor["Custo_Unitario_Eirox"], errors="coerce")
        preco_mercado = pd.to_numeric(motor["Preço_Mercado_Eirox"], errors="coerce")
        preco_recomendado = pd.to_numeric(motor["Preço_Sugerido_Eirox"], errors="coerce")
        margem_atual = pd.to_numeric(motor["Margem_Atual_Eirox"], errors="coerce") * 100
        margem_recomendada = pd.to_numeric(motor["Margem_no_Mercado_Eirox"], errors="coerce") * 100
        qtd = pd.to_numeric(motor.get("Qtd_Vendida_Eirox", 0), errors="coerce").fillna(0)
        estoque = pd.to_numeric(motor[c_estoque], errors="coerce").fillna(0) if c_estoque else pd.Series(0.0, index=motor.index)

        # Se preço recomendado não estiver válido, mantém o atual.
        preco_recomendado = preco_recomendado.where(
            preco_recomendado.notna() & (preco_recomendado > 0),
            preco
        )

        # Variação coerente com preço real.
        variacao = pd.Series(0.0, index=motor.index)
        mask_preco = preco.notna() & (preco > 0) & preco_recomendado.notna()
        variacao.loc[mask_preco] = (
            (preco_recomendado.loc[mask_preco] - preco.loc[mask_preco])
            / preco.loc[mask_preco]
        ) * 100

        # Ganho/impacto conforme a ação central.
        ganho = pd.Series(0.0, index=motor.index)
        rec = motor["Recomendacao_Central"].fillna("MANTER").astype(str)

        mask_subir = rec.eq("SUBIR PREÇO")
        if "Ganho_Lucro_Potencial_Eirox" in motor.columns:
            ganho.loc[mask_subir] = pd.to_numeric(
                motor.loc[mask_subir, "Ganho_Lucro_Potencial_Eirox"], errors="coerce"
            ).fillna(0)

        # Para baixar, impacto é redução de preço x volume; para negociar, redução de custo x volume.
        mask_outros = ~mask_subir
        ganho.loc[mask_outros] = pd.to_numeric(
            motor.loc[mask_outros, "Impacto_Financeiro_Eirox"], errors="coerce"
        ).fillna(0)

        # Fallback histórico quando não houver volume, sem zerar oportunidade já calculada.
        c_ganho_hist = _eirox_first_col(
            motor,
            ["Ganho_Potencial", "Ganho Potencial", "Ganho_Potencial_Final", "Ganho_Potencial_Atualizado", "Ganho Produto"]
        )
        if c_ganho_hist:
            ganho_hist = pd.to_numeric(motor[c_ganho_hist], errors="coerce").fillna(0)
            ganho = ganho.where(ganho.abs() > 0, ganho_hist)

        mapa_acao = {
            "SUBIR PREÇO": "Aumentar preço",
            "BAIXAR PREÇO": "Reduzir preço",
            "NEGOCIAR COMPRA": "Negociar compra",
            "MANTER": "Manter",
            "SEM CUSTO": "Revisar custo",
        }

        out = pd.DataFrame(index=motor.index)
        out["EmpresaID"] = empresa_id
        out["Empresa"] = empresa_nome
        out["EAN"] = motor[c_ean].astype(str) if c_ean else ""
        out["Produto"] = motor[c_prod].astype(str) if c_prod else ""
        out["Laboratório"] = motor[c_lab].astype(str) if c_lab else "Não informado"
        out["Categoria"] = motor[c_cat].astype(str) if c_cat else "Não informado"
        out["Curva"] = eirox_qd_curva_abc_venda(motor).reindex(motor.index).fillna("Sem venda no período")
        out["Ação"] = rec.map(mapa_acao).fillna("Manter")
        out["Preço_Atual"] = preco.fillna(0)
        out["Preço_Recomendado"] = preco_recomendado.fillna(0)
        out["Variação_Pct"] = variacao.fillna(0)
        out["Margem_Atual"] = margem_atual.fillna(0)
        out["Margem_Recomendada"] = margem_recomendada.fillna(0)
        out["Preço_Concorrente"] = preco_mercado.fillna(0)
        out["Custo_Unitário"] = custo.fillna(0)
        out["Qtd_Vendida"] = qtd
        out["Estoque"] = estoque
        out["Ganho_Estimado"] = ganho.fillna(0)

        # Campos de referência de concorrência já presentes no projeto.
        for destino, candidatos in {
            "Loja_Menor_Preço": ["Loja do Menor Preço", "Loja_Menor_Preco", "Farmácia Menor Preço"],
            "Data_Pesquisa": ["Data da Pesquisa", "Data_Pesquisa", "Data Pesquisa"],
        }.items():
            c = _eirox_first_col(motor, candidatos)
            out[destino] = motor[c].fillna("").astype(str) if c else ""

        out["Motivo"] = out["Ação"].map({
            "Aumentar preço": "Preço atual abaixo da referência competitiva; existe espaço para capturar margem/lucro.",
            "Reduzir preço": "Preço acima da referência competitiva e a margem permite ajuste.",
            "Negociar compra": "Custo atual impede acompanhar o mercado preservando a margem mínima.",
            "Revisar custo": "Produto sem custo unitário válido para decisão automática.",
            "Manter": "Preço atual está compatível com a referência de mercado dentro da regra central."
        }).fillna("Analisar produto.")

        # Score: prioriza ganho/impacto, gap de preço e criticidade de margem.
        ganho_rank = out["Ganho_Estimado"].abs().rank(pct=True).fillna(0)
        gap_rank = out["Variação_Pct"].abs().rank(pct=True).fillna(0)
        margem_risco = (100 - out["Margem_Atual"].clip(0,100)) / 100
        out["Score_IA"] = (ganho_rank*55 + gap_rank*25 + margem_risco*20).round(2)

        # Remove linhas sem produto/EAN e sem qualquer base de decisão útil.
        mask_ident = out["EAN"].astype(str).str.strip().ne("") | out["Produto"].astype(str).str.strip().ne("")
        mask_fin = (
            out["Preço_Atual"].gt(0)
            | out["Preço_Concorrente"].gt(0)
            | out["Custo_Unitário"].gt(0)
            | out["Ganho_Estimado"].abs().gt(0)
        )
        out = out[mask_ident & mask_fin].copy()

        # Agrupa por produto sem destruir valores financeiros.
        group_cols = ["EmpresaID","Empresa","EAN","Produto","Laboratório","Categoria","Curva","Ação","Motivo"]
        agg = out.groupby(group_cols, dropna=False).agg(
            Score_IA=("Score_IA","max"),
            Preço_Atual=("Preço_Atual","mean"),
            Preço_Recomendado=("Preço_Recomendado","mean"),
            Variação_Pct=("Variação_Pct","mean"),
            Margem_Atual=("Margem_Atual","mean"),
            Margem_Recomendada=("Margem_Recomendada","mean"),
            Preço_Concorrente=("Preço_Concorrente","mean"),
            Custo_Unitário=("Custo_Unitário","mean"),
            Qtd_Vendida=("Qtd_Vendida","sum"),
            Estoque=("Estoque","sum"),
            Ganho_Estimado=("Ganho_Estimado","sum"),
            Loja_Menor_Preço=("Loja_Menor_Preço","first"),
            Data_Pesquisa=("Data_Pesquisa","first"),
        ).reset_index()

        agg["Curva"] = agg["Curva"].apply(
            lambda v: (
                str(v).strip()
                if str(v).strip().lower() not in ["", "nan", "none", "null", "não informado", "nao informado"]
                else "Não informado"
            )
        )

        agg = agg.sort_values(["Score_IA","Ganho_Estimado"], ascending=[False,False])
        if top_n is not None and int(top_n) > 0:
            agg = agg.head(int(top_n))
        agg["Ranking"] = range(1, len(agg)+1)

        cols = [
            "Ranking","EmpresaID","Empresa","EAN","Produto","Laboratório","Categoria","Curva","Ação",
            "Preço_Atual","Preço_Recomendado","Variação_Pct","Margem_Atual","Margem_Recomendada",
            "Preço_Concorrente","Custo_Unitário","Qtd_Vendida","Estoque","Ganho_Estimado",
            "Loja_Menor_Preço","Data_Pesquisa","Score_IA","Motivo"
        ]
        return agg[cols]

    except Exception as erro:
        # Não mascarar silenciosamente a origem: retorna uma linha de diagnóstico legível.
        return pd.DataFrame([{
            "Ranking":1,"EmpresaID":"","Empresa":"","EAN":"","Produto":"ERRO AO GERAR IA",
            "Laboratório":"","Categoria":"","Curva":"","Ação":"Erro",
            "Preço_Atual":0,"Preço_Recomendado":0,"Variação_Pct":0,"Margem_Atual":0,
            "Margem_Recomendada":0,"Preço_Concorrente":0,"Custo_Unitário":0,"Qtd_Vendida":0,
            "Estoque":0,"Ganho_Estimado":0,"Loja_Menor_Preço":"","Data_Pesquisa":"",
            "Score_IA":0,"Motivo":str(erro)
        }])

def enviar_ia_pricing_telegram(ia_df, limite_envio=10):
    try:
        if ia_df is None or ia_df.empty:
            return False, "Nenhuma recomendação para enviar."
        top=ia_df.head(int(limite_envio)); ganho_total=ia_df["Ganho_Estimado"].sum() if "Ganho_Estimado" in ia_df.columns else 0
        linhas=[f"• <b>{r.get('Produto','')}</b> | {r.get('Ação','')} | R$ {_ia_numero_br(r.get('Preço_Recomendado',0))}" for _,r in top.iterrows()]
        mensagem=("🤖 <b>IA Pricing Enterprise</b>\n\n"+f"🏢 <b>Empresa:</b> {top.iloc[0].get('Empresa','')}\n"+f"🎯 <b>Recomendações:</b> {len(ia_df)}\n"+f"💵 <b>Ganho estimado:</b> R$ {_ia_numero_br(ganho_total)}\n\n"+"\n".join(linhas)+f"\n\n🏷️ <b>Versão:</b> {VERSAO_APP}")
        ok=enviar_alerta_telegram(mensagem) if "enviar_alerta_telegram" in globals() else False
        return bool(ok), "Recomendações enviadas ao Telegram." if ok else "Não foi possível enviar ao Telegram."
    except Exception as erro:
        return False, str(erro)



