# --------------------------------------------------
def eirox_v1413_enriquecer_venda_compra(base, simulacao_ref=None, compra_ref=None):
    """
    Preenche, sem sobrescrever valores válidos, os campos operacionais que
    alimentam Top Oportunidades e demais tabelas:
    - Qtd_Vendida_Mes_Anterior
    - Preco_Atual_Venda
    - Laboratório_Compra

    Fonte prioritária de venda: simulacao_global, que já é calculada a partir
    da VENDA_FINAL_TESTE e preserva a relação quantidade/preço/faturamento.
    Fonte de laboratório: COMPRA_TESTE por EAN.
    """
    try:
        if not isinstance(base, pd.DataFrame) or base.empty or "EAN" not in base.columns:
            return base

        out = base.copy()
        out["_EAN_V1413"] = out["EAN"].apply(_normalizar_ean_eirox)

        # --- Venda real / simulador oficial ---
        sim = simulacao_ref if isinstance(simulacao_ref, pd.DataFrame) else pd.DataFrame()
        if not sim.empty:
            c_ean_s = _achar_coluna_eirox(sim, ["EAN", "EAN (GTIN)", "GTIN"], ["ean", "gtin"])
            if c_ean_s:
                s = pd.DataFrame(index=sim.index)
                s["_EAN_V1413"] = sim[c_ean_s].apply(_normalizar_ean_eirox)

                c_qtd_s = _achar_coluna_eirox(
                    sim,
                    ["Qtd_Vendida_Mes_Anterior", "Qtd Vendida Mês Anterior", "Qtd Vendida Mes Anterior", "Qtd Vendida", "Quantidade Vendida"],
                    ["qtd", "quant", "vendida"]
                )
                c_preco_s = _achar_coluna_eirox(
                    sim,
                    ["Preco_Atual", "Preço Atual", "Preco_Atual_Venda", "Preço Venda", "Preco Venda"],
                    ["preco", "preço", "atual", "venda"]
                )
                c_venda_s = _achar_coluna_eirox(
                    sim,
                    ["Venda_Preco_Antigo", "Venda Preço Antigo", "Venda Preco Antigo", "Faturamento Atual"],
                    ["venda", "fatur"]
                )

                if c_qtd_s:
                    s["_QTD_V1413"] = sim[c_qtd_s].apply(_numero_br_para_float_eirox)
                else:
                    s["_QTD_V1413"] = np.nan
                if c_preco_s:
                    s["_PRECO_V1413"] = sim[c_preco_s].apply(_numero_br_para_float_eirox)
                else:
                    s["_PRECO_V1413"] = np.nan
                if c_venda_s:
                    s["_VENDA_V1413"] = sim[c_venda_s].apply(_numero_br_para_float_eirox)
                else:
                    s["_VENDA_V1413"] = np.nan

                # Consolida por EAN mantendo os valores oficiais do simulador.
                s = s[s["_EAN_V1413"].astype(str).str.len() > 0].copy()
                s = s.groupby("_EAN_V1413", as_index=False).agg(
                    _QTD_V1413=("_QTD_V1413", "max"),
                    _PRECO_V1413=("_PRECO_V1413", "max"),
                    _VENDA_V1413=("_VENDA_V1413", "max"),
                )

                # Se houver faturamento e quantidade, a razão é a melhor fonte de preço atual.
                _preco_calc = s["_VENDA_V1413"] / s["_QTD_V1413"].replace(0, np.nan)
                s["_PRECO_V1413"] = s["_PRECO_V1413"].where(
                    s["_PRECO_V1413"].notna() & (s["_PRECO_V1413"] > 0),
                    _preco_calc
                )

                out = out.merge(s, on="_EAN_V1413", how="left")

                if "Qtd_Vendida_Mes_Anterior" not in out.columns:
                    out["Qtd_Vendida_Mes_Anterior"] = np.nan
                qtd_atual = pd.to_numeric(out["Qtd_Vendida_Mes_Anterior"], errors="coerce")
                out["Qtd_Vendida_Mes_Anterior"] = qtd_atual.where(
                    qtd_atual.notna() & (qtd_atual > 0),
                    out["_QTD_V1413"]
                )

                if "Preco_Atual_Venda" not in out.columns:
                    out["Preco_Atual_Venda"] = np.nan
                preco_atual_venda = pd.to_numeric(out["Preco_Atual_Venda"], errors="coerce")
                out["Preco_Atual_Venda"] = preco_atual_venda.where(
                    preco_atual_venda.notna() & (preco_atual_venda > 0),
                    out["_PRECO_V1413"]
                )

                # Preço Atual também deve preferir preço real de venda quando disponível.
                if "Preco_Atual" in out.columns:
                    pa = pd.to_numeric(out["Preco_Atual"], errors="coerce")
                    pav = pd.to_numeric(out["Preco_Atual_Venda"], errors="coerce")
                    out["Preco_Atual"] = pav.where(pav.notna() & (pav > 0), pa)
                if "Preço Atual" in out.columns:
                    pav = pd.to_numeric(out["Preco_Atual_Venda"], errors="coerce")
                    pa2 = pd.to_numeric(out["Preço Atual"], errors="coerce")
                    out["Preço Atual"] = pav.where(pav.notna() & (pav > 0), pa2)

                out.drop(columns=["_QTD_V1413", "_PRECO_V1413", "_VENDA_V1413"], inplace=True, errors="ignore")

        # --- Laboratório/Fabricante da compra ---
        comp = compra_ref if isinstance(compra_ref, pd.DataFrame) else pd.DataFrame()
        if not comp.empty:
            c_ean_c = _achar_coluna_eirox(comp, ["EAN", "EAN (GTIN)", "GTIN", "Código de Barras", "Codigo de Barras"], ["ean", "gtin", "barras"])
            c_lab_c = _achar_coluna_eirox(comp, ["Laboratório", "Laboratorio", "Fabricante", "Marca"], ["labor", "fabric", "marca"])
            if c_ean_c and c_lab_c:
                c = pd.DataFrame({
                    "_EAN_V1413": comp[c_ean_c].apply(_normalizar_ean_eirox),
                    "_LAB_V1413": comp[c_lab_c].astype(str).str.strip(),
                })
                c = c[
                    c["_EAN_V1413"].astype(str).str.len().gt(0)
                    & c["_LAB_V1413"].notna()
                    & ~c["_LAB_V1413"].str.lower().isin(["", "nan", "none", "nat"])
                ].copy()
                if not c.empty:
                    c = c.groupby("_EAN_V1413", as_index=False)["_LAB_V1413"].first()
                    out = out.merge(c, on="_EAN_V1413", how="left")
                    if "Laboratório_Compra" not in out.columns:
                        out["Laboratório_Compra"] = ""
                    atual_lab = out["Laboratório_Compra"].astype(str).str.strip()
                    vazio_lab = atual_lab.str.lower().isin(["", "nan", "none", "nat", "não informado", "nao informado"])
                    out.loc[vazio_lab, "Laboratório_Compra"] = out.loc[vazio_lab, "_LAB_V1413"]
                    out.drop(columns=["_LAB_V1413"], inplace=True, errors="ignore")

        # Espelhos usados por telas/exportações.
        if "Qtd_Vendida_Mes_Anterior" in out.columns:
            out["Qtd Vendida Mês Anterior"] = pd.to_numeric(out["Qtd_Vendida_Mes_Anterior"], errors="coerce").fillna(0)
        if "Preco_Atual_Venda" in out.columns:
            out["Preco_Atual_Venda"] = pd.to_numeric(out["Preco_Atual_Venda"], errors="coerce")

        out.drop(columns=["_EAN_V1413"], inplace=True, errors="ignore")
        return out
    except Exception:
        try:
            out.drop(columns=["_EAN_V1413"], inplace=True, errors="ignore")
            return out
        except Exception:
            return base


