EIROX_MARGEM_MINIMA_PADRAO = 0.20

def _eirox_num(s):
    try:
        if isinstance(s, pd.Series):
            if "converter_numero_brasil" in globals():
                return converter_numero_brasil(s)
            return pd.to_numeric(s, errors="coerce")
        return pd.to_numeric(s, errors="coerce")
    except Exception:
        return pd.to_numeric(s, errors="coerce")

def _eirox_first_col(df, nomes):
    if not isinstance(df, pd.DataFrame):
        return None
    mapa = {str(c).strip().lower(): c for c in df.columns}
    for nome in nomes:
        k = str(nome).strip().lower()
        if k in mapa:
            return mapa[k]
    return None

def _eirox_moeda_num(v):
    try:
        if pd.isna(v):
            return ""
        return f"{eirox_brl(float(v))}".replace(",", "X").replace(".", ",").replace("X", ".")
    except Exception:
        return ""

def _eirox_pct_num(v):
    try:
        if pd.isna(v):
            return ""
        return f"{float(v)*100:.1f}%".replace(".", ",")
    except Exception:
        return ""




def eirox_v70_aplicar_rotulos_plotly(fig):
    """Adiciona rótulos permanentes aos traces geográficos existentes."""
    try:
        if fig is None or not hasattr(fig, "data"):
            return fig

        for trace in fig.data:
            tipo = str(getattr(trace, "type", "")).lower()
            if tipo not in ("scattermapbox", "scattermap", "scattergeo"):
                continue

            texto = getattr(trace, "text", None)
            if texto is None:
                texto = getattr(trace, "hovertext", None)

            if texto is not None:
                try:
                    trace.text = texto
                    trace.mode = "markers+text"
                    trace.textposition = "top right"
                    trace.textfont = dict(size=10, color="#F4F7FB")
                except Exception:
                    pass
        return fig
    except Exception:
        return fig


def eirox_v72_mapa_referencia(fig):
    """
    Padrão visual oficial dos mapas Eirox.
    Não altera classificação, filtros, raio, município ou dados.
    """
    try:
        if fig is None or not hasattr(fig, "data"):
            return fig

        fig = eirox_v70_aplicar_rotulos_plotly(fig)

        try:
            fig.update_layout(mapbox_style="carto-darkmatter")
        except Exception:
            pass
        try:
            fig.update_layout(map_style="carto-darkmatter")
        except Exception:
            pass

        fig.update_layout(
            paper_bgcolor="#06111f",
            plot_bgcolor="#06111f",
            font=dict(color="#EAF2FF"),
            margin=dict(l=4, r=4, t=38, b=4),
            legend=dict(
                orientation="h",
                yanchor="bottom",
                y=1.01,
                xanchor="left",
                x=0,
                bgcolor="rgba(0,0,0,0)",
                font=dict(size=11, color="#EAF2FF"),
                title=None,
            ),
        )

        for trace in fig.data:
            tipo = str(getattr(trace, "type", "")).lower()
            if tipo not in ("scattermapbox", "scattermap", "scattergeo"):
                continue

            nome = str(getattr(trace, "name", "") or "").upper()

            eh_cliente = any(
                chave in nome
                for chave in ["CLIENTE PRINCIPAL", "LOJA PRINCIPAL", "OUTRA LOJA DO CLIENTE"]
            )
            eh_concorrente = any(
                chave in nome
                for chave in ["CONCORRENTE", "CONCORRÊNCIA", "CONCORRENCIA"]
            )

            try:
                if getattr(trace, "text", None) is not None:
                    trace.mode = "markers+text"
                    trace.textposition = "top right"
                    trace.textfont = dict(size=10, color="#F4F7FB")
            except Exception:
                pass

            try:
                if eh_cliente:
                    trace.marker = dict(
                        size=17,
                        color="#19C8F5",
                        opacity=1.0
                    )
                elif eh_concorrente:
                    trace.marker = dict(
                        size=10,
                        color="#F04B43",
                        opacity=0.92
                    )
            except Exception:
                pass

        return fig
    except Exception:
        return fig


def eirox_v71_mapa_escuro(fig):
    return eirox_v72_mapa_referencia(fig)


def eirox_v72_aplicar_em_todos_mapas(fig):
    return eirox_v72_mapa_referencia(fig)




