def eirox_qd_normalizar_ean(v):
    try:
        if pd.isna(v):
            return ""
        s = str(v).strip()
        s = re.sub(r"\.0$", "", s)
        return re.sub(r"\D", "", s)
    except Exception:
        return ""


def eirox_qd_texto_valido(v):
    try:
        if pd.isna(v):
            return ""
        s = str(v).strip()
        if s.lower() in {
            "", "nan", "none", "null", "nat", "-", "--",
            "não informado", "nao informado",
            "sem informação", "sem informacao"
        }:
            return ""
        return s
    except Exception:
        return ""


def eirox_qd_first(df, nomes):
    try:
        c = _eirox_first_col(df, nomes)
        if c:
            return c
    except Exception:
        pass
    if not isinstance(df, pd.DataFrame):
        return None
    mp = {str(c).strip().lower(): c for c in df.columns}
    for n in nomes:
        c = mp.get(str(n).strip().lower())
        if c:
            return c
    return None


def eirox_qd_numero_br(serie):
    try:
        if "converter_numero_brasil" in globals():
            return converter_numero_brasil(serie).fillna(0)
    except Exception:
        pass
    s = serie.astype(str).str.strip()
    virg = s.str.contains(",", regex=False)
    out = pd.Series(index=serie.index, dtype=float)
    out.loc[virg] = pd.to_numeric(
        s[virg].str.replace(".", "", regex=False).str.replace(",", ".", regex=False),
        errors="coerce"
    )
    out.loc[~virg] = pd.to_numeric(s[~virg], errors="coerce")
    return out.fillna(0)


def eirox_qd_curva_abc_venda(base):
    """
    Curva oficial pela VENDA_FINAL_TESTE/venda_rede:
    A até 80%, B até 95%, C acima de 95%.
    """
    if not isinstance(base, pd.DataFrame) or base.empty:
        return pd.Series(dtype=object)

    c_ean_base = eirox_qd_first(
        base, ["EAN","EAN (GTIN)","GTIN","Cód. Barras/Etiq.","Cod. Barras/Etiq.","Código de Barras","Codigo de Barras"]
    )
    if not c_ean_base:
        return pd.Series("Sem EAN", index=base.index)

    venda = globals().get("venda_rede", pd.DataFrame())
    if not isinstance(venda, pd.DataFrame) or venda.empty:
        return pd.Series("Sem venda no período", index=base.index)

    c_ean_v = eirox_qd_first(
        venda, ["Cód. Barras/Etiq.","Cod. Barras/Etiq.","EAN","EAN (GTIN)","GTIN","Código de Barras","Codigo de Barras"]
    )
    c_fat = eirox_qd_first(
        venda, ["Venda","Valor Venda","Valor_Venda","Faturamento","Valor Total","Valor_Total","Receita","Valor Líquido","Valor Liquido"]
    )
    c_qtd = eirox_qd_first(
        venda, ["Itens","Quantidade","Qtd","QTD","Qtde","Quantidade Vendida","Qtd Vendida"]
    )
    c_preco = eirox_qd_first(
        venda, ["Preço Venda","Preco Venda","Preco_Venda","Preço (R$)","Preco (R$)","Preço","Preco","Valor Unitário","Valor Unitario"]
    )

    if not c_ean_v:
        return pd.Series("Sem venda no período", index=base.index)

    v = venda.copy()
    v["_EAN_QD"] = v[c_ean_v].apply(eirox_qd_normalizar_ean)

    if c_fat:
        v["_FAT_QD"] = eirox_qd_numero_br(v[c_fat])
    elif c_qtd and c_preco:
        v["_FAT_QD"] = eirox_qd_numero_br(v[c_qtd]) * eirox_qd_numero_br(v[c_preco])
    else:
        return pd.Series("Sem venda no período", index=base.index)

    v = v[v["_EAN_QD"].ne("") & v["_FAT_QD"].gt(0)].copy()
    if v.empty:
        return pd.Series("Sem venda no período", index=base.index)

    abc = (
        v.groupby("_EAN_QD", as_index=False)["_FAT_QD"]
        .sum()
        .sort_values("_FAT_QD", ascending=False, kind="stable")
        .reset_index(drop=True)
    )
    total = float(abc["_FAT_QD"].sum())
    if total <= 0:
        return pd.Series("Sem venda no período", index=base.index)

    abc["_ACUM"] = abc["_FAT_QD"].cumsum() / total
    abc["_CURVA"] = np.select(
        [abc["_ACUM"] <= 0.80, abc["_ACUM"] <= 0.95],
        ["A", "B"],
        default="C"
    )
    mapa = dict(zip(abc["_EAN_QD"], abc["_CURVA"]))
    eans = base[c_ean_base].apply(eirox_qd_normalizar_ean)
    return eans.map(mapa).fillna("Sem venda no período")


def eirox_qd_mapa_ean(df, valor_cols):
    if not isinstance(df, pd.DataFrame) or df.empty:
        return {}
    c_ean = eirox_qd_first(
        df, ["EAN","EAN (GTIN)","GTIN","Cód. Barras/Etiq.","Cod. Barras/Etiq.","Código de Barras","Codigo de Barras"]
    )
    c_val = eirox_qd_first(df, valor_cols)
    if not c_ean or not c_val:
        return {}
    a = df[[c_ean,c_val]].copy()
    a["_EAN"] = a[c_ean].apply(eirox_qd_normalizar_ean)
    a["_VAL"] = a[c_val].apply(eirox_qd_texto_valido)
    a = a[a["_EAN"].ne("") & a["_VAL"].ne("")]
    if a.empty:
        return {}
    a = a.groupby("_EAN", as_index=False)["_VAL"].first()
    return dict(zip(a["_EAN"], a["_VAL"]))


def eirox_qd_recuperar_cadastro(base):
    """
    Preenche dados cadastrais por EAN usando todas as bases oficiais já carregadas.
    """
    if not isinstance(base, pd.DataFrame) or base.empty:
        return base

    d = base.copy()
    c_ean = eirox_qd_first(
        d, ["EAN","EAN (GTIN)","GTIN","Cód. Barras/Etiq.","Cod. Barras/Etiq.","Código de Barras","Codigo de Barras"]
    )
    if not c_ean:
        return d

    eans = d[c_ean].apply(eirox_qd_normalizar_ean)
    fontes = []
    for nm in ["compra","estoque","venda_rede","historico","df"]:
        obj = globals().get(nm, pd.DataFrame())
        if isinstance(obj, pd.DataFrame) and not obj.empty:
            fontes.append(obj)

    config = {
        "Laboratório": (
            ["Laboratório","Laboratorio","Fabricante","Marca"],
            "Sem laboratório cadastrado"
        ),
        "Família": (
            ["Família","Familia","Categoria","Departamento","Grupo"],
            "Sem família cadastrada"
        ),
        "Produto": (
            ["Produto","Descrição","Descricao","Produto na Pesquisa"],
            "Produto sem descrição"
        ),
    }

    for destino, (cands, fallback) in config.items():
        if destino in d.columns:
            atual = d[destino].apply(eirox_qd_texto_valido)
        else:
            atual = pd.Series("", index=d.index, dtype=object)

        faltando = atual.eq("")
        if faltando.any():
            for fonte in fontes:
                mp = eirox_qd_mapa_ean(fonte, cands)
                if not mp:
                    continue
                rec = eans.map(mp).fillna("")
                atual = atual.where(~faltando, rec)
                faltando = atual.apply(eirox_qd_texto_valido).eq("")
                if not faltando.any():
                    break

        d[destino] = atual.apply(lambda x: eirox_qd_texto_valido(x) or fallback)

    curva = eirox_qd_curva_abc_venda(d)
    d["CURVA"] = curva
    d["Curva"] = curva
    return d




def eirox_fin_padronizar_ganho(df):
    """
    Padroniza ganhos financeiros antes de exibição/exportação.
    Mantém exatamente:
    Ganho Produto = Ganho Unitário x Quantidade.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df

    out = df.copy()

    # possíveis nomes finais usados nas tabelas/exportações
    ganho_unit_cols = [
        "Ganho Unitário", "Ganho Unitario",
        "Ganho_Lucro_Unitario_Eirox"
    ]
    qtd_cols = [
        "Qtd Vendida", "Qtd_Vendida_Eirox",
        "Qtd Vendida Mês Anterior", "Qtd_Vendida_Mes_Anterior",
        "Quantidade Vendida"
    ]
    ganho_prod_cols = [
        "Ganho Produto", "Ganho Potencial",
        "Ganho_Lucro_Potencial_Eirox"
    ]

    c_gu = next((c for c in ganho_unit_cols if c in out.columns), None)
    c_qt = next((c for c in qtd_cols if c in out.columns), None)
    c_gp = next((c for c in ganho_prod_cols if c in out.columns), None)

    if c_gu:
        out[c_gu] = pd.to_numeric(out[c_gu], errors="coerce").fillna(0).round(2)

    if c_qt:
        out[c_qt] = pd.to_numeric(out[c_qt], errors="coerce").fillna(0)

    if c_gu and c_qt:
        calculado = (
            pd.to_numeric(out[c_gu], errors="coerce").fillna(0)
            * pd.to_numeric(out[c_qt], errors="coerce").fillna(0)
        ).round(2)

        if c_gp:
            out[c_gp] = calculado
        else:
            out["Ganho Produto"] = calculado

    # arredondamento das colunas financeiras usuais
    for c in [
        "Preço Atual", "Preço Sugerido", "Menor Preço Concorrente",
        "Custo Unitário", "Custo Unitario",
        "Preço_Atual_Eirox", "Preço_Sugerido_Eirox",
        "Custo_Unitario_Eirox", "Impacto_Financeiro_Eirox"
    ]:
        if c in out.columns:
            out[c] = pd.to_numeric(out[c], errors="coerce").round(2)

    return out




def eirox_v135_corrigir_financeiro_subir_preco(df):
    """
    V1.3.5 - reconcilia os campos financeiros de SUBIR PREÇO.
    Não cria quantidade vendida artificialmente.
    Usa relações matemáticas já presentes na própria linha como fallback.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df

    d = df.copy()

    def _num_series(col):
        if col not in d.columns:
            return pd.Series(np.nan, index=d.index, dtype="float64")
        s = d[col]
        if s.dtype == object:
            s = (s.astype(str)
                   .str.replace("R$", "", regex=False)
                   .str.replace(".", "", regex=False)
                   .str.replace(",", ".", regex=False)
                   .str.strip())
        return pd.to_numeric(s, errors="coerce")

    def _first_numeric(names):
        result = pd.Series(np.nan, index=d.index, dtype="float64")
        for c in names:
            if c in d.columns:
                s = _num_series(c)
                result = result.where(result.notna() & (result > 0), s)
        return result

    preco_atual = _first_numeric([
        "Preço Atual", "Preco Atual", "Preco_Atual", "Preço_Atual",
        "Preco_Venda", "Preço Venda", "Preco Venda", "Preço atual"
    ])

    preco_sugerido = _first_numeric([
        "Preço Sugerido", "Preco Sugerido", "Preco_Sugerido", "Preço_Sugerido",
        "Menor Preço Concorrente", "Menor_Preco", "Preço Mercado", "Preco_Mercado"
    ])

    qtd = _first_numeric([
        "Qtd Vendida Mês Anterior", "Qtd Vendida Mes Anterior",
        "Qtd_Vendida_Mes_Anterior", "Qtd Vendida", "Qtd_Vendida",
        "Quantidade Vendida", "Quantidade_Vendida", "Qtd Venda", "Qtd_Venda"
    ])

    venda_antiga = _first_numeric([
        "Venda Preço Antigo", "Venda Preco Antigo", "Venda_Preco_Antigo",
        "Faturamento Atual", "Faturamento_Atual", "Venda Atual", "Venda_Atual"
    ])

    venda_projetada = _first_numeric([
        "Venda Projetada Preço Sugerido", "Venda Projetada Preco Sugerido",
        "Venda_Projetada_Preco_Sugerido", "Faturamento Projetado",
        "Faturamento_Projetado"
    ])

    # Reconciliação em ordem que funciona mesmo quando Qtd e Preço Atual vieram zerados.
    # 1) Preço sugerido normalmente existe no mercado.
    # 2) Venda projetada / preço sugerido recupera a quantidade.
    qtd_por_proj = venda_projetada / preco_sugerido.replace(0, np.nan)
    qtd = qtd.where(qtd.notna() & (qtd > 0), qtd_por_proj)

    # 3) Com a quantidade recuperada, Venda Preço Antigo / Qtd recupera Preço Atual.
    calc_preco_por_venda = venda_antiga / qtd.replace(0, np.nan)
    preco_atual = preco_atual.where(preco_atual.notna() & (preco_atual > 0), calc_preco_por_venda)

    # 4) Se ainda faltar quantidade, tenta Venda Antiga / Preço Atual.
    qtd_por_antiga = venda_antiga / preco_atual.replace(0, np.nan)
    qtd = qtd.where(qtd.notna() & (qtd > 0), qtd_por_antiga)

    # 5) Se ainda faltar preço sugerido e houver quantidade, recupera pela venda projetada.
    calc_sugerido = venda_projetada / qtd.replace(0, np.nan)
    preco_sugerido = preco_sugerido.where(preco_sugerido.notna() & (preco_sugerido > 0), calc_sugerido)

    # Quantidade de unidades deve ser inteira quando matematicamente próxima.
    qtd = qtd.round(0)

    ganho_unit = preco_sugerido - preco_atual
    ganho_prod = ganho_unit * qtd

    # Para a tela SUBIR PREÇO, ganho negativo não é ganho de subida.
    ganho_unit = ganho_unit.where(ganho_unit > 0, 0.0)
    ganho_prod = ganho_prod.where(ganho_prod > 0, 0.0)

    # Recalcula faturamentos coerentes quando temos preço e quantidade.
    venda_antiga_calc = preco_atual * qtd
    venda_proj_calc = preco_sugerido * qtd

    d["Preço Atual"] = preco_atual.round(2)
    d["Preço Sugerido"] = preco_sugerido.round(2)
    d["Qtd Vendida Mês Anterior"] = qtd.fillna(0).astype(float)
    d["Ganho Unitário"] = ganho_unit.fillna(0).round(2)
    d["Ganho Produto"] = ganho_prod.fillna(0).round(2)

    if "Venda Preço Antigo" in d.columns:
        d["Venda Preço Antigo"] = venda_antiga.where(
            venda_antiga.notna() & (venda_antiga > 0), venda_antiga_calc
        ).fillna(0).round(2)
    else:
        d["Venda Preço Antigo"] = venda_antiga_calc.fillna(0).round(2)

    if "Venda Projetada Preço Sugerido" in d.columns:
        d["Venda Projetada Preço Sugerido"] = venda_projetada.where(
            venda_projetada.notna() & (venda_projetada > 0), venda_proj_calc
        ).fillna(0).round(2)
    else:
        d["Venda Projetada Preço Sugerido"] = venda_proj_calc.fillna(0).round(2)

    return d


@st.cache_data(show_spinner=False, max_entries=8)
def eirox_mapa_data_pesquisa_bruta_cacheado(assinatura_historico):
    """Mapa EAN -> última Data Emissão diretamente dos arquivos de VENDA_TESTE.

    Fallback de produção independente do DataFrame historico transformado.
    Garante a Data da Pesquisa no Streamlit Cloud sem interferir no heatmap.
    """
    mapa = {}
    try:
        base_dir = Path(__file__).resolve().parent
        pasta = base_dir / "VENDA_TESTE"
        if not pasta.exists():
            return mapa

        arquivos = []
        for padrao in ("*.xlsx", "*.xls", "*.xlsm", "*.csv"):
            arquivos.extend(pasta.glob(padrao))

        for arquivo in sorted(set(arquivos), key=lambda x: x.name.lower()):
            try:
                suf = arquivo.suffix.lower()
                if suf == ".csv":
                    try:
                        temp = pd.read_csv(arquivo, sep=None, engine="python", encoding="utf-8-sig")
                    except Exception:
                        temp = pd.read_csv(arquivo, sep=None, engine="python", encoding="latin1")
                elif suf == ".xls":
                    temp = pd.read_excel(arquivo, engine="xlrd")
                else:
                    temp = pd.read_excel(arquivo, engine="openpyxl")
                if not isinstance(temp, pd.DataFrame) or temp.empty:
                    continue
                temp.columns = temp.columns.astype(str).str.strip()
                c_ean = next((c for c in ["EAN", "EAN (GTIN)", "GTIN"] if c in temp.columns), None)
                c_data = next((c for c in ["Data Emissão", "Data Emissao", "Data da Pesquisa", "Data Pesquisa", "Data"] if c in temp.columns), None)
                if not c_ean:
                    continue

                eans = (temp[c_ean].astype(str)
                        .str.replace(".0", "", regex=False)
                        .str.replace(r"\D", "", regex=True)
                        .str.strip())

                if c_data:
                    vals = temp[c_data].fillna("").astype(str).str.strip()
                    vals = vals.str.replace(
                        r"\s+(AMT|AMST|BRT|BRST|GMT(?:[+-]\d+)?|UTC(?:[+-]\d+)?)\s+",
                        " ", regex=True, flags=re.IGNORECASE
                    )
                    try:
                        dts = pd.to_datetime(vals, errors="coerce", dayfirst=True, format="mixed")
                    except Exception:
                        dts = pd.to_datetime(vals, errors="coerce", dayfirst=True)
                else:
                    dts = pd.Series(pd.NaT, index=temp.index)

                # Fallback pelo nome Pesquisa_YYYYMMDD_HHMMSS.xlsx quando a célula não trouxer data.
                m = re.search(r"Pesquisa[_ -]?(\d{8})", arquivo.stem, flags=re.IGNORECASE)
                dt_nome = pd.to_datetime(m.group(1), format="%Y%m%d", errors="coerce") if m else pd.NaT

                for i, ean in eans.items():
                    if not ean:
                        continue
                    dt = dts.loc[i] if i in dts.index else pd.NaT
                    if pd.isna(dt):
                        dt = dt_nome
                    if pd.isna(dt):
                        continue
                    anterior = mapa.get(ean)
                    if anterior is None or dt > anterior:
                        mapa[ean] = dt
            except Exception:
                continue
    except Exception:
        return {}
    return mapa


def eirox_v142_data_final_unica(df, historico_base=None):
    """Fonte única de Data da Pesquisa para tela, CSV e Excel."""
    if not isinstance(df, pd.DataFrame):
        return df
    out = df.copy()
    if "Data da Pesquisa" not in out.columns:
        out["Data da Pesquisa"] = ""

    def _ok(v):
        if v is None:
            return False
        try:
            if pd.isna(v):
                return False
        except Exception:
            pass
        s = str(v).strip()
        return s.lower() not in {"","none","nan","nat","null","<na>","sem data na fonte","sem pesquisa válida","sem pesquisa valida"}

    # Primeiro usa a rotina já existente do projeto.
    try:
        rec = eirox_qd_preservar_e_recuperar_data(
            out.copy(),
            historico_base if historico_base is not None else (historico if "historico" in globals() else None)
        )
        if isinstance(rec, pd.DataFrame) and "Data da Pesquisa" in rec.columns:
            for idx in out.index:
                if not _ok(out.at[idx, "Data da Pesquisa"]):
                    nv = rec.at[idx, "Data da Pesquisa"] if idx in rec.index else None
                    if _ok(nv):
                        out.at[idx, "Data da Pesquisa"] = nv
    except Exception:
        pass

    # Fallback direto no histórico por EAN; usa a data válida mais recente.
    try:
        hist = historico_base if historico_base is not None else (historico if "historico" in globals() else pd.DataFrame())
        if isinstance(hist, pd.DataFrame) and not hist.empty:
            c_ean_o = next((c for c in ["EAN","EAN (GTIN)","GTIN"] if c in out.columns), None)
            c_ean_h = next((c for c in ["EAN","EAN (GTIN)","GTIN"] if c in hist.columns), None)
            c_data_h = next((c for c in ["Data da Pesquisa","Data Pesquisa","Data Emissão","Data Emissao","Data"] if c in hist.columns), None)
            if c_ean_o and c_ean_h and c_data_h:
                h=hist[[c_ean_h,c_data_h]].copy()
                h["_EAN_V142"]=(h[c_ean_h].astype(str).str.replace(".0","",regex=False).str.replace(r"\D","",regex=True).str.strip())
                s=h[c_data_h].fillna("").astype(str).str.strip()
                s=s.str.replace(r"\s+(AMT|AMST|BRT|BRST|GMT(?:[+-]\d+)?|UTC(?:[+-]\d+)?)\s+"," ",regex=True,flags=re.IGNORECASE)
                try:
                    h["_DT_V142"]=pd.to_datetime(s,errors="coerce",dayfirst=True,format="mixed")
                except Exception:
                    h["_DT_V142"]=pd.to_datetime(s,errors="coerce",dayfirst=True)
                h=h.dropna(subset=["_DT_V142"])
                if not h.empty:
                    mapa=h.groupby("_EAN_V142")["_DT_V142"].max().to_dict()
                    eans=(out[c_ean_o].astype(str).str.replace(".0","",regex=False).str.replace(r"\D","",regex=True).str.strip())
                    for idx in out.index:
                        if not _ok(out.at[idx,"Data da Pesquisa"]):
                            dt=mapa.get(eans.loc[idx])
                            if dt is not None and not pd.isna(dt):
                                out.at[idx,"Data da Pesquisa"]=dt.strftime("%d/%m/%Y")
    except Exception:
        pass

    # Fallback final de produção: consulta diretamente VENDA_TESTE.
    # Não depende do histórico já transformado/cacheado e por isso funciona no Cloud.
    try:
        mapa_bruto = eirox_mapa_data_pesquisa_bruta_cacheado(
            assinatura_pasta("VENDA_TESTE")
        )
        c_ean_o = next((c for c in ["EAN", "EAN (GTIN)", "GTIN"] if c in out.columns), None)
        if c_ean_o and mapa_bruto:
            eans = (out[c_ean_o].astype(str)
                    .str.replace(".0", "", regex=False)
                    .str.replace(r"\D", "", regex=True)
                    .str.strip())
            for idx in out.index:
                if not _ok(out.at[idx, "Data da Pesquisa"]):
                    dt = mapa_bruto.get(eans.loc[idx])
                    if dt is not None and not pd.isna(dt):
                        out.at[idx, "Data da Pesquisa"] = dt.strftime("%d/%m/%Y")
    except Exception:
        pass

    def _fmt(v):
        if not _ok(v):
            return "Sem data na fonte"
        s=str(v).strip()
        if re.fullmatch(r"\d{2}/\d{2}/\d{4}",s):
            return s
        try:
            dt=pd.to_datetime(s,errors="coerce",dayfirst=True)
            if not pd.isna(dt):
                return dt.strftime("%d/%m/%Y")
        except Exception:
            pass
        return s
    out["Data da Pesquisa"]=out["Data da Pesquisa"].apply(_fmt).astype(str)
    # Mantém aliases usados por telas antigas e novas sincronizados.
    for _alias_data in ["Data_Pesquisa", "Data Pesquisa"]:
        if _alias_data in out.columns:
            out[_alias_data] = out["Data da Pesquisa"]
    return out


def eirox_qd_preservar_e_recuperar_data(df, historico_base=None):
    """
    V1.3.4
    Preserva a Data da Pesquisa já válida.
    Só consulta/enriquece o histórico nas linhas sem data.
    Nunca substitui uma data válida por vazio/None.
    """
    if not isinstance(df, pd.DataFrame):
        return df

    out = df.copy()

    if "Data da Pesquisa" not in out.columns:
        out["Data da Pesquisa"] = ""

    def _valida(v):
        if pd.isna(v):
            return False
        s = str(v).strip()
        if s.lower() in {
            "", "none", "nan", "nat", "null",
            "sem data na fonte",
            "sem pesquisa válida", "sem pesquisa valida"
        }:
            return False
        if re.fullmatch(r"\d{2}/\d{2}/\d{4}", s):
            return True
        try:
            d = pd.to_datetime(s, errors="coerce", dayfirst=True)
            return not pd.isna(d)
        except Exception:
            return False

    # guarda a informação original, porque ela tem prioridade
    original = out["Data da Pesquisa"].copy()
    faltando = ~original.apply(_valida)

    if faltando.any():
        try:
            enriquecido = eirox_enriquecer_menor_preco_concorrente(
                out.copy(),
                historico_base if historico_base is not None
                else (historico if "historico" in globals() else None)
            )

            if isinstance(enriquecido, pd.DataFrame) and "Data da Pesquisa" in enriquecido.columns:
                for idx in out.index[faltando]:
                    if idx in enriquecido.index:
                        nv = enriquecido.at[idx, "Data da Pesquisa"]
                        if _valida(nv):
                            out.at[idx, "Data da Pesquisa"] = nv
        except Exception:
            pass

    # fallback direto por EAN + loja + preço e depois EAN + loja
    try:
        hist = historico_base if historico_base is not None else (
            historico if "historico" in globals() else pd.DataFrame()
        )

        if isinstance(hist, pd.DataFrame) and not hist.empty:
            c_ean_o = next((c for c in ["EAN","EAN (GTIN)","GTIN"] if c in out.columns), None)
            c_loja_o = next((c for c in ["Loja do Menor Preço","Loja_Menor_Preco_Concorrente"] if c in out.columns), None)
            c_preco_o = next((c for c in ["Menor Preço Concorrente","Menor_Preco","Menor Preço"] if c in out.columns), None)

            c_ean_h = next((c for c in ["EAN","EAN (GTIN)","GTIN"] if c in hist.columns), None)
            c_loja_h = next((c for c in ["Farmácia","Farmacia","Loja","Estabelecimento"] if c in hist.columns), None)
            c_preco_h = next((c for c in ["Preço (R$)","Preco (R$)","Preço","Preco","Valor"] if c in hist.columns), None)
            c_data_h = next((c for c in ["Data da Pesquisa","Data Pesquisa","Data Emissão","Data Emissao","Data"] if c in hist.columns), None)

            if c_ean_o and c_ean_h and c_data_h:
                h = hist.copy()

                h["_EAN_FIX"] = (
                    h[c_ean_h].astype(str)
                    .str.replace(".0","",regex=False)
                    .str.replace(r"\D","",regex=True)
                    .str.strip()
                )

                if c_loja_h:
                    h["_LOJA_FIX"] = h[c_loja_h].fillna("").astype(str).str.strip().str.upper()
                else:
                    h["_LOJA_FIX"] = ""

                if c_preco_h:
                    h["_PRECO_FIX"] = pd.to_numeric(h[c_preco_h], errors="coerce").round(2)
                else:
                    h["_PRECO_FIX"] = np.nan

                s = h[c_data_h].fillna("").astype(str).str.strip()
                s = s.str.replace(
                    r"\s+(AMT|AMST|BRT|BRST|GMT(?:[+-]\d+)?|UTC(?:[+-]\d+)?)\s+",
                    " ",
                    regex=True,
                    flags=re.IGNORECASE
                )

                try:
                    h["_DATA_FIX"] = pd.to_datetime(s, errors="coerce", dayfirst=True, format="mixed")
                except Exception:
                    h["_DATA_FIX"] = pd.to_datetime(s, errors="coerce", dayfirst=True)

                h = h.dropna(subset=["_DATA_FIX"])

                # mapas
                mapa_ean = h.groupby("_EAN_FIX")["_DATA_FIX"].max().to_dict()

                mapa_ean_loja = {}
                if c_loja_h:
                    mapa_ean_loja = (
                        h.groupby(["_EAN_FIX","_LOJA_FIX"])["_DATA_FIX"]
                        .max()
                        .to_dict()
                    )

                mapa_ean_loja_preco = {}
                if c_loja_h and c_preco_h:
                    mapa_ean_loja_preco = (
                        h.dropna(subset=["_PRECO_FIX"])
                        .groupby(["_EAN_FIX","_LOJA_FIX","_PRECO_FIX"])["_DATA_FIX"]
                        .max()
                        .to_dict()
                    )

                for idx in out.index:
                    if _valida(out.at[idx,"Data da Pesquisa"]):
                        continue

                    ean = re.sub(r"\D","",str(out.at[idx,c_ean_o]).replace(".0",""))
                    loja = str(out.at[idx,c_loja_o]).strip().upper() if c_loja_o else ""
                    try:
                        preco = round(float(out.at[idx,c_preco_o]),2) if c_preco_o else None
                    except Exception:
                        preco = None

                    dt = None
                    if preco is not None and loja:
                        dt = mapa_ean_loja_preco.get((ean,loja,preco))
                    if dt is None and loja:
                        dt = mapa_ean_loja.get((ean,loja))
                    if dt is None:
                        dt = mapa_ean.get(ean)

                    if dt is not None and not pd.isna(dt):
                        out.at[idx,"Data da Pesquisa"] = dt.strftime("%d/%m/%Y")
    except Exception:
        pass

    # Restaura datas originais válidas, por segurança absoluta
    for idx in out.index:
        if idx in original.index and _valida(original.loc[idx]):
            out.at[idx,"Data da Pesquisa"] = original.loc[idx]

    # Formatação final
    def _fmt(v):
        if not _valida(v):
            return "Sem data na fonte"
        s = str(v).strip()
        if re.fullmatch(r"\d{2}/\d{2}/\d{4}", s):
            return s
        try:
            dt = pd.to_datetime(s, errors="coerce", dayfirst=True)
            return dt.strftime("%d/%m/%Y") if not pd.isna(dt) else "Sem data na fonte"
        except Exception:
            return "Sem data na fonte"

    out["Data da Pesquisa"] = out["Data da Pesquisa"].apply(_fmt)
    return out


def eirox_qd_corrigir_data_exibicao(df):
    """Garante que nenhuma tela exiba None/NaN/vazio em Data da Pesquisa."""
    if not isinstance(df, pd.DataFrame):
        return df
    out = df.copy()
    if "Data da Pesquisa" in out.columns:
        out["Data da Pesquisa"] = out["Data da Pesquisa"].apply(
            lambda v: (
                "Sem data na fonte"
                if pd.isna(v) or str(v).strip().lower() in {
                    "", "none", "nan", "nat", "null",
                    "sem pesquisa válida", "sem pesquisa valida"
                }
                else str(v)
            )
        )
    return out


def eirox_qd_sanitizar(base):
    """
    Camada geral usada antes de qualquer tela.
    """
    if not isinstance(base, pd.DataFrame) or base.empty:
        return base

    d = eirox_qd_recuperar_cadastro(base)

    # Recupera concorrência com a rotina oficial.
    try:
        d = eirox_enriquecer_menor_preco_concorrente(d)
    except Exception:
        pass

    # Textos factuais em vez de NaN/None.
    for c in d.columns:
        if d[c].dtype == object:
            d[c] = d[c].apply(
                lambda v: "" if str(v).strip().lower() in {"nan","none","null","nat"} else v
            )

    if "Loja do Menor Preço" in d.columns:
        d["Loja do Menor Preço"] = d["Loja do Menor Preço"].apply(
            lambda v: eirox_qd_texto_valido(v) or "Sem concorrente válido"
        )

    if "Data da Pesquisa" in d.columns:
        _orig_data = d["Data da Pesquisa"].copy()
        _dt_data = pd.to_datetime(
            _orig_data.where(
                ~_orig_data.astype(str).str.contains("Sem data na fonte", case=False, na=False),
                None
            ),
            errors="coerce",
            dayfirst=True
        )
        d["Data da Pesquisa"] = [
            x.strftime("%d/%m/%Y") if not pd.isna(x) else "Sem data na fonte"
            for x in _dt_data
        ]
    else:
        d["Data da Pesquisa"] = "Sem data na fonte"

    return d


def eirox_motor_oportunidades(base, margem_minima=EIROX_MARGEM_MINIMA_PADRAO):
    if not isinstance(base, pd.DataFrame) or base.empty:
        return pd.DataFrame()

    d = base.copy()

    c_preco = _eirox_first_col(d, [
        "Preço Principal","Preco Principal","Preço_Atual","Preco_Atual",
        "Preço Atual","Preco Atual","Preco_Medio","Preço Médio",
        "Preço (R$)","Preco (R$)"
    ])
    c_mercado = _eirox_first_col(d, [
        "Menor Preço Concorrente","Menor_Preco_Concorrente",
        "Menor_Preco","Menor Preço",
        "Preco_Sugerido_Mercado","Preço Sugerido Mercado",
        "Preco_Maximo_Competitivo","Preço Máximo Competitivo",
        "Preco_Medio_Concorrente","Preço Médio Concorrente"
    ])
    c_custo = _eirox_first_col(d, [
        "Custo_Estoque_Unitario","Custo Unitário","Custo_Unitario",
        "Custo Unitario","Custo Médio Unitário","Custo_Medio_Unitario",
        "Custo","Custo Atual"
    ])
    c_qtd = _eirox_first_col(d, [
        "Qtd_Vendida_Mes_Anterior","Qtd Vendida Mês Anterior",
        "Quantidade_Vendida","Quantidade Vendida","Qtd Vendida",
        "Qtd_Vendida_30D","Venda_Qtd","Quantidade"
    ])
    c_ganho = _eirox_first_col(d, [
        "Ganho_Potencial","Ganho Potencial",
        "Ganho_Potencial_Final","Ganho_Potencial_Atualizado"
    ])

    if not c_custo:
        cm = _eirox_first_col(d, ["Custo Médio","Custo Medio","Custo_Medio","Custo Médio Total"])
        est = _eirox_first_col(d, ["Estoque","Quantidade Estoque","Qtd Estoque","Estoque Atual"])
        if cm and est:
            estoque_v = _eirox_num(d[est]).replace(0, np.nan)
            d["_Custo_Unitario_Eirox"] = _eirox_num(d[cm]) / estoque_v
            c_custo = "_Custo_Unitario_Eirox"

    d["Preço_Atual_Eirox"] = _eirox_num(d[c_preco]) if c_preco else np.nan
    d["Preço_Mercado_Eirox"] = _eirox_num(d[c_mercado]) if c_mercado else np.nan
    d["Custo_Unitario_Eirox"] = _eirox_num(d[c_custo]) if c_custo else np.nan
    d["Qtd_Vendida_Eirox"] = _eirox_num(d[c_qtd]).fillna(0) if c_qtd else 0

    p = d["Preço_Atual_Eirox"]
    m = d["Preço_Mercado_Eirox"]
    c = d["Custo_Unitario_Eirox"]

    d["Margem_Atual_Eirox"] = np.where((p > 0) & c.notna(), (p-c)/p, np.nan)
    d["Margem_no_Mercado_Eirox"] = np.where((m > 0) & c.notna(), (m-c)/m, np.nan)
    d["Custo_Maximo_20_Eirox"] = m * (1 - float(margem_minima))
    d["Reducao_Custo_Necessaria_Eirox"] = (c - d["Custo_Maximo_20_Eirox"]).clip(lower=0)

    tol = 0.02
    abaixo = (p > 0) & (m > 0) & (p < m * (1-tol))
    acima = (p > 0) & (m > 0) & (p > m * (1+tol))
    sem_custo = c.isna() | (c <= 0)
    margem_mercado_ok = d["Margem_no_Mercado_Eirox"] >= float(margem_minima)

    d["Recomendacao_Central"] = "MANTER"
    d.loc[sem_custo, "Recomendacao_Central"] = "SEM CUSTO"
    d.loc[abaixo & ~sem_custo, "Recomendacao_Central"] = "SUBIR PREÇO"
    d.loc[acima & ~sem_custo & margem_mercado_ok, "Recomendacao_Central"] = "BAIXAR PREÇO"
    d.loc[acima & ~sem_custo & ~margem_mercado_ok, "Recomendacao_Central"] = "NEGOCIAR COMPRA"

    d["Preço_Sugerido_Eirox"] = p
    mask_acao = d["Recomendacao_Central"].isin(["SUBIR PREÇO","BAIXAR PREÇO","NEGOCIAR COMPRA"])
    d.loc[mask_acao, "Preço_Sugerido_Eirox"] = m

    d["Impacto_Unitario_Eirox"] = (d["Preço_Sugerido_Eirox"] - p).abs()
    impacto_volume = d["Impacto_Unitario_Eirox"] * d["Qtd_Vendida_Eirox"]

    if c_ganho:
        ganho_exist = _eirox_num(d[c_ganho]).fillna(0).abs()
        d["Impacto_Financeiro_Eirox"] = np.maximum(impacto_volume.fillna(0), ganho_exist)
    else:
        d["Impacto_Financeiro_Eirox"] = impacto_volume.fillna(0)

    mask_neg = d["Recomendacao_Central"].eq("NEGOCIAR COMPRA")
    impacto_neg = d["Reducao_Custo_Necessaria_Eirox"] * d["Qtd_Vendida_Eirox"].replace(0, 1)
    d.loc[mask_neg, "Impacto_Financeiro_Eirox"] = impacto_neg[mask_neg]


    # --------------------------------------------------
    # GANHO DE LUCRO COMPETITIVO - REGRA HISTÓRICA
    # --------------------------------------------------
    # O motor já possui:
    # d["Preço_Atual_Eirox"]
    # d["Preço_Sugerido_Eirox"]
    # d["Qtd_Vendida_Eirox"]
    #
    # Portanto não buscamos novas colunas nem criamos outro dataframe.
    # V1.3.2 — arredondamento financeiro padronizado:
    # o ganho unitário é fechado em 2 casas antes da multiplicação.
    # Assim, a conferência manual do CSV fecha exatamente:
    # Ganho Unitário x Quantidade = Ganho Produto.
    d["Ganho_Lucro_Unitario_Eirox"] = (
        pd.to_numeric(d["Preço_Sugerido_Eirox"], errors="coerce")
        - pd.to_numeric(d["Preço_Atual_Eirox"], errors="coerce")
    ).clip(lower=0).fillna(0).round(2)

    d["Qtd_Vendida_Eirox"] = (
        pd.to_numeric(d["Qtd_Vendida_Eirox"], errors="coerce")
        .fillna(0)
    )

    d["Ganho_Lucro_Potencial_Eirox"] = (
        d["Ganho_Lucro_Unitario_Eirox"]
        * d["Qtd_Vendida_Eirox"]
    ).round(2)

    # Ganho de aumento competitivo existe somente em SUBIR PREÇO.
    d.loc[
        ~d["Recomendacao_Central"].astype(str).eq("SUBIR PREÇO"),
        ["Ganho_Lucro_Unitario_Eirox", "Ganho_Lucro_Potencial_Eirox"]
    ] = 0.0

    return d

def eirox_resumo_oportunidades(base):
    d = eirox_motor_oportunidades(base)
    if d.empty:
        return {"subir":0,"baixar":0,"negociar":0,"captura":0.0,"reducao_custo":0.0,"margem_projetada":np.nan}

    rec = d["Recomendacao_Central"]
    margem_proj = np.where(
        d["Preço_Sugerido_Eirox"] > 0,
        (d["Preço_Sugerido_Eirox"] - d["Custo_Unitario_Eirox"]) / d["Preço_Sugerido_Eirox"],
        np.nan
    )
    margem_s = pd.Series(margem_proj)

    return {
        "subir": int(rec.eq("SUBIR PREÇO").sum()),
        "baixar": int(rec.eq("BAIXAR PREÇO").sum()),
        "negociar": int(rec.eq("NEGOCIAR COMPRA").sum()),
        "captura": float(d.loc[rec.eq("SUBIR PREÇO"), "Impacto_Financeiro_Eirox"].fillna(0).sum()),
        "reducao_custo": float(d.loc[rec.eq("NEGOCIAR COMPRA"), "Impacto_Financeiro_Eirox"].fillna(0).sum()),
        "margem_projetada": float(margem_s.dropna().mean()) if margem_s.notna().any() else np.nan
    }




