def eirox_formatar_view_ia(df_view):
    if not isinstance(df_view, pd.DataFrame) or df_view.empty:
        return df_view
    v = df_view.copy()
    for c in ["Preço_Atual","Preço_Recomendado","Preço_Concorrente","Custo_Unitário","Ganho_Estimado"]:
        if c in v.columns:
            v[c] = pd.to_numeric(v[c], errors="coerce").map(lambda x: f"R$ {_ia_numero_br(x)}" if pd.notna(x) else "")
    for c in ["Variação_Pct","Margem_Atual","Margem_Recomendada"]:
        if c in v.columns:
            v[c] = pd.to_numeric(v[c], errors="coerce").map(lambda x: f"{_ia_numero_br(x)}%" if pd.notna(x) else "")
    for c in ["Qtd_Vendida","Estoque"]:
        if c in v.columns:
            v[c] = pd.to_numeric(v[c], errors="coerce").fillna(0).round(0).astype(int)
    return v


