def _v1431_coalesce(_df, _fontes):
    _saida = pd.Series(np.nan, index=_df.index, dtype="object")
    for _fonte in _fontes:
        if _fonte not in _df.columns:
            continue
        _serie = _df[_fonte]
        _txt = _serie.astype(str).str.strip().str.lower()
        _valida = _serie.notna() & ~_txt.isin([
            "", "none", "nan", "nat", "sem data na fonte", "r$ nan"
        ])
        _mask = _saida.isna() & _valida
        _saida.loc[_mask] = _serie.loc[_mask]
    return _saida

